// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

// ─── Interfaces ───────────────────────────────────────────────────────────────

interface IERC20 {
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

/// @dev Permit2 AllowanceTransfer
interface IPermit2 {
    function transferFrom(address from, address to, uint160 amount, address token) external;
}

/// @dev Uniswap V3 Pool (World Chain specific factory)
interface IUniswapV3Pool {
    function swap(
        address recipient,
        bool zeroForOne,
        int256 amountSpecified,
        uint160 sqrtPriceLimitX96,
        bytes calldata data
    ) external returns (int256 amount0, int256 amount1);
    function token0() external view returns (address);
    function token1() external view returns (address);
    function fee() external view returns (uint24);
    function slot0() external view returns (
        uint160 sqrtPriceX96, int24 tick, uint16, uint16, uint16, uint8, bool
    );
}

/// @dev Uniswap V3 Swap Callback
interface IUniswapV3SwapCallback {
    function uniswapV3SwapCallback(
        int256 amount0Delta,
        int256 amount1Delta,
        bytes calldata data
    ) external;
}

/// @dev Uniswap V2 Router (Uniswap V2 on World Chain)
interface ISwapRouterV2 {
    function swapExactTokensForTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external returns (uint256[] memory amounts);
    function getAmountsOut(uint amountIn, address[] memory path)
        external view returns (uint[] memory amounts);
}

/// @dev Volume tracking
interface IVolumeRewards {
    function recordSwap(address user, uint256 usdcAmount) external;
}

// ─── AcuaSwapRouter ───────────────────────────────────────────────────────────

/**
 * @title AcuaSwapRouter
 * @notice On-chain fee wrapper for Uniswap V3 (direct pool calls) and V2 on World Chain.
 *         Uses Permit2 AllowanceTransfer for token pulls.
 *         Calls World Chain V3 pools directly (factory = 0x7a5028...) since the standard
 *         SwapRouter02 is deployed with the Ethereum mainnet factory address.
 *
 * Fee model:
 *   swapFeeBps (default 200 = 2%) — split evenly among feeOwners
 *   h2oFeeBps  (default 10  = 0.1%) — pooled for periodic H2O buyback
 */
contract AcuaSwapRouter is IUniswapV3SwapCallback {

    // ─── Constants ────────────────────────────────────────────────────────────
    IPermit2 public constant PERMIT2 = IPermit2(0x000000000022D473030F116dDEE9F6B43aC78BA3);

    /// @dev World Chain Uniswap V3 factory (different from Ethereum mainnet)
    address public constant V3_FACTORY    = 0x7a5028BDa40e7B173C278C5342087826455ea25a;
    bytes32 public constant V3_POOL_INIT_CODE_HASH =
        0xe34f199b19b2b4f47f68442619d555527d244f78a3297ea89325f843f87b8b54;

    /// @dev Standard Uniswap V2 router deployed on World Chain
    ISwapRouterV2 public constant ROUTER_V2 = ISwapRouterV2(0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D);

    address public constant H2O  = 0x17392e5483983945dEB92e0518a8F2C4eB6bA59d;
    address public constant WLD  = 0x2cFc85d8E48F8EAB294be644d9E25C3030863003;
    address public constant USDC = 0x79A02482A880bCE3F13e09Da970dC34db4CD24d1;

    uint160 private constant _MIN_SQRT_RATIO = 4295128739;
    uint160 private constant _MAX_SQRT_RATIO = 1461446703485210103287273052203988822378723970342;
    uint256 public  constant MAX_FEE_BPS = 1000;

    // ─── Config ───────────────────────────────────────────────────────────────
    address   public owner;
    address[3] public feeOwners;
    uint256   public swapFeeBps = 200;
    uint256   public h2oFeeBps  = 10;
    address   public volumeRewards;

    // ─── Fee accounting ───────────────────────────────────────────────────────
    mapping(address => mapping(address => uint256)) public ownerFees;
    mapping(address => uint256) public h2oFeePool;

    // ─── Transient swap context (re-entrant callback) ─────────────────────────
    address private _swapUser;
    address private _swapToken;

    // ─── Events ───────────────────────────────────────────────────────────────
    event SwappedV3(address indexed user, address tokenIn, address tokenOut, uint256 amountIn, uint256 amountOut);
    event SwappedV2(address indexed user, address tokenIn, address tokenOut, uint256 amountIn, uint256 amountOut);
    event FeeClaimed(address indexed who, address indexed token, uint256 amount);
    event H2OBought(address indexed token, uint256 tokenIn, uint256 h2oOut);
    event ConfigUpdated();

    modifier onlyOwner() { require(msg.sender == owner, "Not owner"); _; }

    // ─── Constructor ──────────────────────────────────────────────────────────
    constructor(address[3] memory _feeOwners) {
        owner = msg.sender;
        feeOwners = _feeOwners;
    }

    // ─── Pool address computation ─────────────────────────────────────────────
    function _computePool(address tokenA, address tokenB, uint24 fee)
        internal pure returns (address pool)
    {
        (address t0, address t1) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
        bytes32 salt = keccak256(abi.encode(t0, t1, fee));
        pool = address(uint160(uint256(keccak256(abi.encodePacked(
            bytes1(0xff), V3_FACTORY, salt, V3_POOL_INIT_CODE_HASH
        )))));
    }

    // ─── V3 Swap Callback ─────────────────────────────────────────────────────
    /**
     * @dev Called by the pool after our swap() call. We push owed tokens from our balance.
     *      The router holds the net amount (after fees) at this point.
     */
    function uniswapV3SwapCallback(
        int256 amount0Delta,
        int256 amount1Delta,
        bytes calldata /* data */
    ) external override {
        // The caller must be the pool we computed (security check)
        require(_swapToken != address(0), "No active swap");
        // We already hold the net token amount, just transfer it to the pool
        if (amount0Delta > 0) {
            IERC20(_swapToken).transfer(msg.sender, uint256(amount0Delta));
        } else if (amount1Delta > 0) {
            IERC20(_swapToken).transfer(msg.sender, uint256(amount1Delta));
        }
    }

    // ─── Internal fee deduction ───────────────────────────────────────────────
    function _deductFees(address token, uint256 amount) internal returns (uint256 netAmount) {
        uint256 swapFee = amount * swapFeeBps / 10000;
        uint256 h2oFee  = amount * h2oFeeBps  / 10000;

        if (swapFee > 0) {
            uint256 active;
            for (uint256 i; i < 3; ++i) if (feeOwners[i] != address(0)) ++active;
            if (active > 0) {
                uint256 per = swapFee / active;
                uint256 dust = swapFee - per * active;
                for (uint256 i; i < 3; ++i)
                    if (feeOwners[i] != address(0)) ownerFees[feeOwners[i]][token] += per;
                ownerFees[feeOwners[0]][token] += dust;
            } else {
                ownerFees[owner][token] += swapFee;
            }
        }
        if (h2oFee > 0) h2oFeePool[token] += h2oFee;
        netAmount = amount - swapFee - h2oFee;
    }

    // ─── Swap via Uniswap V3 (direct pool, single hop) ────────────────────────
    /**
     * @param tokenIn         Input token
     * @param tokenOut        Output token
     * @param fee             Pool fee tier (100, 500, 3000, or 10000)
     * @param amountIn        Gross input amount (fees deducted on-chain)
     * @param amountOutMin    Minimum output after slippage
     * @param usdcEquivalent  Input value in USDC-6-dec for volume tracking
     */
    function swapV3Single(
        address tokenIn,
        address tokenOut,
        uint24  fee,
        uint256 amountIn,
        uint256 amountOutMin,
        uint256 usdcEquivalent
    ) external returns (uint256 amountOut) {
        require(amountIn > 0 && amountIn <= type(uint160).max, "Bad amount");

        // Pull tokens via Permit2
        PERMIT2.transferFrom(msg.sender, address(this), uint160(amountIn), tokenIn);

        // Deduct fees
        uint256 netAmt = _deductFees(tokenIn, amountIn);

        // Set callback context
        _swapUser  = msg.sender;
        _swapToken = tokenIn;

        address pool = _computePool(tokenIn, tokenOut, fee);
        bool zeroForOne = tokenIn < tokenOut;
        uint160 sqrtLimit = zeroForOne ? _MIN_SQRT_RATIO + 1 : _MAX_SQRT_RATIO - 1;

        (int256 a0, int256 a1) = IUniswapV3Pool(pool).swap(
            msg.sender,        // recipient gets tokenOut
            zeroForOne,
            int256(netAmt),    // exact input
            sqrtLimit,
            ""
        );

        _swapToken = address(0); // clear callback context

        amountOut = zeroForOne ? uint256(-a1) : uint256(-a0);
        require(amountOut >= amountOutMin, "Too much slippage");

        _recordVolume(msg.sender, usdcEquivalent);
        emit SwappedV3(msg.sender, tokenIn, tokenOut, amountIn, amountOut);
    }

    // ─── Swap via Uniswap V3 (multi-hop: tokenIn -> hop -> tokenOut) ──────────
    /**
     * @param tokenIn       Input token
     * @param hopToken      Intermediate token (WLD or USDC typically)
     * @param tokenOut      Output token
     * @param fee1          Fee tier for first hop (tokenIn -> hop)
     * @param fee2          Fee tier for second hop (hop -> tokenOut)
     * @param amountIn      Gross input
     * @param amountOutMin  Minimum output
     * @param usdcEquivalent Input USD value (6-dec)
     */
    function swapV3Multi(
        address tokenIn,
        address hopToken,
        address tokenOut,
        uint24  fee1,
        uint24  fee2,
        uint256 amountIn,
        uint256 amountOutMin,
        uint256 usdcEquivalent
    ) external returns (uint256 amountOut) {
        require(amountIn > 0 && amountIn <= type(uint160).max, "Bad amount");

        PERMIT2.transferFrom(msg.sender, address(this), uint160(amountIn), tokenIn);
        uint256 netAmt = _deductFees(tokenIn, amountIn);

        // Hop 1: tokenIn -> hopToken (output to this contract)
        _swapUser  = msg.sender;
        _swapToken = tokenIn;
        address pool1 = _computePool(tokenIn, hopToken, fee1);
        bool z1 = tokenIn < hopToken;
        (int256 a0, int256 a1) = IUniswapV3Pool(pool1).swap(
            address(this), z1, int256(netAmt), z1 ? _MIN_SQRT_RATIO + 1 : _MAX_SQRT_RATIO - 1, ""
        );
        _swapToken = address(0);
        uint256 midAmt = z1 ? uint256(-a1) : uint256(-a0);

        // Hop 2: hopToken -> tokenOut (output directly to user)
        _swapToken = hopToken;
        address pool2 = _computePool(hopToken, tokenOut, fee2);
        bool z2 = hopToken < tokenOut;
        (int256 b0, int256 b1) = IUniswapV3Pool(pool2).swap(
            msg.sender, z2, int256(midAmt), z2 ? _MIN_SQRT_RATIO + 1 : _MAX_SQRT_RATIO - 1, ""
        );
        _swapToken = address(0);
        amountOut = z2 ? uint256(-b1) : uint256(-b0);

        require(amountOut >= amountOutMin, "Too much slippage");
        _recordVolume(msg.sender, usdcEquivalent);
        emit SwappedV3(msg.sender, tokenIn, tokenOut, amountIn, amountOut);
    }

    // ─── Swap via Uniswap V2 ──────────────────────────────────────────────────
    function swapV2(
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata v2Path,
        uint256 usdcEquivalent
    ) external returns (uint256 amountOut) {
        require(amountIn > 0 && amountIn <= type(uint160).max, "Bad amount");
        require(v2Path.length >= 2, "Bad path");

        PERMIT2.transferFrom(msg.sender, address(this), uint160(amountIn), tokenIn);
        uint256 netAmt = _deductFees(tokenIn, amountIn);

        IERC20(tokenIn).approve(address(ROUTER_V2), netAmt);
        uint256[] memory amounts = ROUTER_V2.swapExactTokensForTokens(
            netAmt, amountOutMin, v2Path, msg.sender, block.timestamp + 1800
        );
        amountOut = amounts[amounts.length - 1];

        _recordVolume(msg.sender, usdcEquivalent);
        emit SwappedV2(msg.sender, tokenIn, tokenOut, amountIn, amountOut);
    }

    // ─── Fee claims ───────────────────────────────────────────────────────────
    function claimFees(address token) external {
        uint256 amount = ownerFees[msg.sender][token];
        require(amount > 0, "Nothing to claim");
        ownerFees[msg.sender][token] = 0;
        IERC20(token).transfer(msg.sender, amount);
        emit FeeClaimed(msg.sender, token, amount);
    }

    function claimFeesBatch(address[] calldata tokens) external {
        for (uint256 i; i < tokens.length; ++i) {
            uint256 a = ownerFees[msg.sender][tokens[i]];
            if (a == 0) continue;
            ownerFees[msg.sender][tokens[i]] = 0;
            IERC20(tokens[i]).transfer(msg.sender, a);
            emit FeeClaimed(msg.sender, tokens[i], a);
        }
    }

    // ─── H2O buyback (owner calls periodically) ───────────────────────────────
    function buybackH2O(address token, uint24 feeHop, uint24 feeOut) external onlyOwner {
        uint256 amount = h2oFeePool[token];
        require(amount > 0, "No fees");
        h2oFeePool[token] = 0;

        if (token == H2O) {
            IERC20(H2O).transfer(owner, amount);
            emit H2OBought(token, amount, amount);
            return;
        }

        // Route token -> WLD -> H2O (via V3 direct pools on World Chain)
        _swapToken = token;
        address pool1 = _computePool(token, WLD, feeHop);
        bool z1 = token < WLD;
        (int256 a0, int256 a1) = IUniswapV3Pool(pool1).swap(
            address(this), z1, int256(amount), z1 ? _MIN_SQRT_RATIO + 1 : _MAX_SQRT_RATIO - 1, ""
        );
        _swapToken = address(0);
        uint256 wldAmt = z1 ? uint256(-a1) : uint256(-a0);

        _swapToken = WLD;
        address pool2 = _computePool(WLD, H2O, feeOut);
        bool z2 = WLD < H2O;
        (int256 b0, int256 b1) = IUniswapV3Pool(pool2).swap(
            owner, z2, int256(wldAmt), z2 ? _MIN_SQRT_RATIO + 1 : _MAX_SQRT_RATIO - 1, ""
        );
        _swapToken = address(0);
        uint256 h2oOut = z2 ? uint256(-b1) : uint256(-b0);

        emit H2OBought(token, amount, h2oOut);
    }

    // ─── Helpers ──────────────────────────────────────────────────────────────
    function _recordVolume(address user, uint256 usdcAmount) internal {
        if (volumeRewards != address(0) && usdcAmount > 0) {
            try IVolumeRewards(volumeRewards).recordSwap(user, usdcAmount) {} catch {}
        }
    }

    /// @notice Preview a single-hop V3 quote (spot price, no impact — only for UI use)
    function quoteSingle(address tokenIn, address tokenOut, uint24 fee, uint256 amountIn)
        external view returns (uint256 amountOut, address poolAddr)
    {
        poolAddr = _computePool(tokenIn, tokenOut, fee);
        (uint160 sqrtPriceX96,,,,,,) = IUniswapV3Pool(poolAddr).slot0();
        // price = (sqrtPriceX96 / 2^96)^2
        // token0 price in token1: price = sqrtPriceX96^2 / 2^192
        bool zeroForOne = tokenIn < tokenOut;
        uint256 priceX192 = uint256(sqrtPriceX96) * uint256(sqrtPriceX96);
        if (zeroForOne) {
            // tokenIn = token0, tokenOut = token1
            amountOut = amountIn * priceX192 / (1 << 192);
        } else {
            // tokenIn = token1, tokenOut = token0
            amountOut = amountIn * (1 << 192) / priceX192;
        }
    }

    // ─── Admin ────────────────────────────────────────────────────────────────
    function setFees(uint256 _swapFeeBps, uint256 _h2oFeeBps) external onlyOwner {
        require(_swapFeeBps + _h2oFeeBps <= MAX_FEE_BPS, "Fee too high");
        swapFeeBps = _swapFeeBps;
        h2oFeeBps  = _h2oFeeBps;
        emit ConfigUpdated();
    }

    function setFeeOwners(address[3] calldata _owners) external onlyOwner {
        feeOwners = _owners;
        emit ConfigUpdated();
    }

    function setVolumeRewards(address _vr) external onlyOwner {
        volumeRewards = _vr;
        emit ConfigUpdated();
    }

    function setOwner(address newOwner) external onlyOwner {
        require(newOwner != address(0), "Zero addr");
        owner = newOwner;
    }

    function emergencyWithdraw(address token, uint256 amount) external onlyOwner {
        IERC20(token).transfer(owner, amount);
    }

    function getPoolAddress(address tokenA, address tokenB, uint24 fee)
        external pure returns (address)
    {
        return _computePool(tokenA, tokenB, fee);
    }
}

contracts/AcuaSwapRouterV2.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "./IPermit2.sol";

// ─── Interfaces ───────────────────────────────────────────────────────────────

interface IERC20V2 {
    function transfer(address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

interface IUniswapV3Pool {
    function swap(
        address recipient,
        bool zeroForOne,
        int256 amountSpecified,
        uint160 sqrtPriceLimitX96,
        bytes calldata data
    ) external returns (int256 amount0, int256 amount1);
    function token0() external view returns (address);
    function token1() external view returns (address);
    function fee() external view returns (uint24);
    function slot0() external view returns (
        uint160 sqrtPriceX96, int24 tick, uint16, uint16, uint16, uint8, bool
    );
}

interface IUniswapV3SwapCallback {
    function uniswapV3SwapCallback(
        int256 amount0Delta,
        int256 amount1Delta,
        bytes calldata data
    ) external;
}

interface IVolumeRewards {
    function recordSwap(address user, uint256 usdcAmount) external;
}

// ─── AcuaSwapRouterV2 ─────────────────────────────────────────────────────────
/**
 * @title  AcuaSwapRouterV2
 * @notice Uniswap V3 swap router using Permit2 SignatureTransfer.
 *         Compatible with MiniKit's native permit2 field — requires only
 *         ONE transaction + one off-chain signature (no pre-approval needed).
 *
 * Fee model:
 *   swapFeeBps (default 200 = 2%)  — split evenly among feeOwners
 *   h2oFeeBps  (default 10  = 0.1%) — pooled for periodic H2O buyback
 */
contract AcuaSwapRouterV2 is IUniswapV3SwapCallback {

    // ─── Constants ────────────────────────────────────────────────────────────
    address public constant PERMIT2_ADDR = 0x000000000022D473030F116dDEE9F6B43aC78BA3;

    address public constant V3_FACTORY = 0x7a5028BDa40e7B173C278C5342087826455ea25a;
    bytes32 public constant V3_POOL_INIT_CODE_HASH =
        0xe34f199b19b2b4f47f68442619d555527d244f78a3297ea89325f843f87b8b54;

    address public constant H2O  = 0x17392e5483983945dEB92e0518a8F2C4eB6bA59d;
    address public constant WLD  = 0x2cFc85d8E48F8EAB294be644d9E25C3030863003;
    address public constant USDC = 0x79A02482A880bCE3F13e09Da970dC34db4CD24d1;

    uint160 private constant _MIN_SQRT_RATIO = 4295128739;
    uint160 private constant _MAX_SQRT_RATIO = 1461446703485210103287273052203988822378723970342;
    uint256 public  constant MAX_FEE_BPS = 1000;

    // ─── Config ───────────────────────────────────────────────────────────────
    address   public owner;
    address[3] public feeOwners;
    uint256   public swapFeeBps = 200;
    uint256   public h2oFeeBps  = 10;
    address   public volumeRewards;

    // ─── Fee accounting ───────────────────────────────────────────────────────
    mapping(address => mapping(address => uint256)) public ownerFees;
    mapping(address => uint256) public h2oFeePool;

    // ─── Transient swap context (re-entrant callback) ─────────────────────────
    address private _swapToken;

    // ─── Events ───────────────────────────────────────────────────────────────
    event SwappedV3(address indexed user, address tokenIn, address tokenOut, uint256 amountIn, uint256 amountOut);
    event FeeClaimed(address indexed who, address indexed token, uint256 amount);
    event H2OBought(address indexed token, uint256 tokenIn, uint256 h2oOut);
    event ConfigUpdated();

    modifier onlyOwner() { require(msg.sender == owner, "Not owner"); _; }

    // ─── Constructor ──────────────────────────────────────────────────────────
    constructor(address[3] memory _feeOwners) {
        owner = msg.sender;
        feeOwners = _feeOwners;
    }

    // ─── Pool address computation ─────────────────────────────────────────────
    function _computePool(address tokenA, address tokenB, uint24 fee)
        internal pure returns (address pool)
    {
        (address t0, address t1) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
        bytes32 salt = keccak256(abi.encode(t0, t1, fee));
        pool = address(uint160(uint256(keccak256(abi.encodePacked(
            bytes1(0xff), V3_FACTORY, salt, V3_POOL_INIT_CODE_HASH
        )))));
    }

    // ─── V3 Swap Callback ─────────────────────────────────────────────────────
    function uniswapV3SwapCallback(
        int256 amount0Delta,
        int256 amount1Delta,
        bytes calldata
    ) external override {
        require(_swapToken != address(0), "No active swap");
        if (amount0Delta > 0) {
            IERC20V2(_swapToken).transfer(msg.sender, uint256(amount0Delta));
        } else if (amount1Delta > 0) {
            IERC20V2(_swapToken).transfer(msg.sender, uint256(amount1Delta));
        }
    }

    // ─── Internal fee deduction ───────────────────────────────────────────────
    function _deductFees(address token, uint256 amount) internal returns (uint256 netAmount) {
        uint256 swapFee = amount * swapFeeBps / 10000;
        uint256 h2oFee  = amount * h2oFeeBps  / 10000;

        if (swapFee > 0) {
            uint256 active;
            for (uint256 i; i < 3; ++i) if (feeOwners[i] != address(0)) ++active;
            if (active > 0) {
                uint256 per = swapFee / active;
                uint256 dust = swapFee - per * active;
                for (uint256 i; i < 3; ++i)
                    if (feeOwners[i] != address(0)) ownerFees[feeOwners[i]][token] += per;
                ownerFees[feeOwners[0]][token] += dust;
            } else {
                ownerFees[owner][token] += swapFee;
            }
        }
        if (h2oFee > 0) h2oFeePool[token] += h2oFee;
        netAmount = amount - swapFee - h2oFee;
    }

    // ─── Receive tokens via Permit2 SignatureTransfer ─────────────────────────
    function _receiveViaPermit2(
        IPermit2.PermitTransferFrom calldata permit,
        bytes calldata signature,
        uint256 amount
    ) internal {
        IPermit2(PERMIT2_ADDR).permitTransferFrom(
            permit,
            IPermit2.SignatureTransferDetails({ to: address(this), requestedAmount: amount }),
            msg.sender,
            signature
        );
    }

    // ─── Swap V3 Single hop ───────────────────────────────────────────────────
    /**
     * @param tokenOut        Output token address
     * @param fee             Uniswap V3 pool fee tier (100, 500, 3000, 10000)
     * @param amountOutMin    Minimum output (slippage protection)
     * @param usdcEquivalent  Input value in USDC-6-dec for volume tracking
     * @param permit          Permit2 SignatureTransfer permit struct
     * @param signature       Permit2 signature (provided by MiniKit)
     */
    function swapV3Single(
        address tokenOut,
        uint24  fee,
        uint256 amountOutMin,
        uint256 usdcEquivalent,
        IPermit2.PermitTransferFrom calldata permit,
        bytes calldata signature
    ) external returns (uint256 amountOut) {
        address tokenIn = permit.permitted.token;
        uint256 amountIn = permit.permitted.amount;
        require(amountIn > 0, "Zero amount");

        // Pull tokens via Permit2 SignatureTransfer
        _receiveViaPermit2(permit, signature, amountIn);

        // Deduct fees
        uint256 netAmt = _deductFees(tokenIn, amountIn);

        // Execute V3 swap — callback will push tokens to the pool
        _swapToken = tokenIn;
        address pool = _computePool(tokenIn, tokenOut, fee);
        bool zeroForOne = tokenIn < tokenOut;
        uint160 sqrtLimit = zeroForOne ? _MIN_SQRT_RATIO + 1 : _MAX_SQRT_RATIO - 1;

        (int256 a0, int256 a1) = IUniswapV3Pool(pool).swap(
            msg.sender, zeroForOne, int256(netAmt), sqrtLimit, ""
        );
        _swapToken = address(0);

        amountOut = zeroForOne ? uint256(-a1) : uint256(-a0);
        require(amountOut >= amountOutMin, "Too much slippage");

        _recordVolume(msg.sender, usdcEquivalent);
        emit SwappedV3(msg.sender, tokenIn, tokenOut, amountIn, amountOut);
    }

    // ─── Swap V3 Multi hop (tokenIn -> hop -> tokenOut) ───────────────────────
    /**
     * @param hopToken        Intermediate token (e.g. WLD or USDC)
     * @param tokenOut        Final output token
     * @param fee1            Fee tier for first hop
     * @param fee2            Fee tier for second hop
     * @param amountOutMin    Minimum output
     * @param usdcEquivalent  Input USD value (6-dec)
     * @param permit          Permit2 SignatureTransfer permit struct
     * @param signature       Permit2 signature (provided by MiniKit)
     */
    function swapV3Multi(
        address hopToken,
        address tokenOut,
        uint24  fee1,
        uint24  fee2,
        uint256 amountOutMin,
        uint256 usdcEquivalent,
        IPermit2.PermitTransferFrom calldata permit,
        bytes calldata signature
    ) external returns (uint256 amountOut) {
        address tokenIn = permit.permitted.token;
        uint256 amountIn = permit.permitted.amount;
        require(amountIn > 0, "Zero amount");

        _receiveViaPermit2(permit, signature, amountIn);
        uint256 netAmt = _deductFees(tokenIn, amountIn);

        // Hop 1: tokenIn → hopToken (output stays in this contract)
        _swapToken = tokenIn;
        address pool1 = _computePool(tokenIn, hopToken, fee1);
        bool z1 = tokenIn < hopToken;
        (int256 a0, int256 a1) = IUniswapV3Pool(pool1).swap(
            address(this), z1, int256(netAmt), z1 ? _MIN_SQRT_RATIO + 1 : _MAX_SQRT_RATIO - 1, ""
        );
        _swapToken = address(0);
        uint256 midAmt = z1 ? uint256(-a1) : uint256(-a0);

        // Hop 2: hopToken → tokenOut (output directly to user)
        _swapToken = hopToken;
        address pool2 = _computePool(hopToken, tokenOut, fee2);
        bool z2 = hopToken < tokenOut;
        (int256 b0, int256 b1) = IUniswapV3Pool(pool2).swap(
            msg.sender, z2, int256(midAmt), z2 ? _MIN_SQRT_RATIO + 1 : _MAX_SQRT_RATIO - 1, ""
        );
        _swapToken = address(0);
        amountOut = z2 ? uint256(-b1) : uint256(-b0);

        require(amountOut >= amountOutMin, "Too much slippage");
        _recordVolume(msg.sender, usdcEquivalent);
        emit SwappedV3(msg.sender, tokenIn, tokenOut, amountIn, amountOut);
    }

    // ─── Quote (view, for UI) ─────────────────────────────────────────────────
    function quoteSingle(address tokenIn, address tokenOut, uint24 fee, uint256 amountIn)
        external view returns (uint256 amountOut, address poolAddr)
    {
        poolAddr = _computePool(tokenIn, tokenOut, fee);
        (uint160 sqrtPriceX96,,,,,,) = IUniswapV3Pool(poolAddr).slot0();
        bool zeroForOne = tokenIn < tokenOut;
        uint256 priceX192 = uint256(sqrtPriceX96) * uint256(sqrtPriceX96);
        if (zeroForOne) {
            amountOut = amountIn * priceX192 / (1 << 192);
        } else {
            amountOut = amountIn * (1 << 192) / priceX192;
        }
    }

    // ─── Fee claims ───────────────────────────────────────────────────────────
    function claimFees(address token) external {
        uint256 amount = ownerFees[msg.sender][token];
        require(amount > 0, "Nothing to claim");
        ownerFees[msg.sender][token] = 0;
        IERC20V2(token).transfer(msg.sender, amount);
        emit FeeClaimed(msg.sender, token, amount);
    }

    function claimFeesBatch(address[] calldata tokens) external {
        for (uint256 i; i < tokens.length; ++i) {
            uint256 a = ownerFees[msg.sender][tokens[i]];
            if (a == 0) continue;
            ownerFees[msg.sender][tokens[i]] = 0;
            IERC20V2(tokens[i]).transfer(msg.sender, a);
            emit FeeClaimed(msg.sender, tokens[i], a);
        }
    }

    // ─── H2O buyback ─────────────────────────────────────────────────────────
    function buybackH2O(address token, uint24 feeHop, uint24 feeOut) external onlyOwner {
        uint256 amount = h2oFeePool[token];
        require(amount > 0, "No fees");
        h2oFeePool[token] = 0;

        if (token == H2O) {
            IERC20V2(H2O).transfer(owner, amount);
            emit H2OBought(token, amount, amount);
            return;
        }

        _swapToken = token;
        address pool1 = _computePool(token, WLD, feeHop);
        bool z1 = token < WLD;
        (int256 a0, int256 a1) = IUniswapV3Pool(pool1).swap(
            address(this), z1, int256(amount), z1 ? _MIN_SQRT_RATIO + 1 : _MAX_SQRT_RATIO - 1, ""
        );
        _swapToken = address(0);
        uint256 wldAmt = z1 ? uint256(-a1) : uint256(-a0);

        _swapToken = WLD;
        address pool2 = _computePool(WLD, H2O, feeOut);
        bool z2 = WLD < H2O;
        (int256 b0, int256 b1) = IUniswapV3Pool(pool2).swap(
            owner, z2, int256(wldAmt), z2 ? _MIN_SQRT_RATIO + 1 : _MAX_SQRT_RATIO - 1, ""
        );
        _swapToken = address(0);
        uint256 h2oOut = z2 ? uint256(-b1) : uint256(-b0);

        emit H2OBought(token, amount, h2oOut);
    }

    // ─── Helpers ──────────────────────────────────────────────────────────────
    function _recordVolume(address user, uint256 usdcAmount) internal {
        if (volumeRewards != address(0) && usdcAmount > 0) {
            try IVolumeRewards(volumeRewards).recordSwap(user, usdcAmount) {} catch {}
        }
    }

    function getPoolAddress(address tokenA, address tokenB, uint24 fee)
        external pure returns (address)
    {
        return _computePool(tokenA, tokenB, fee);
    }

    // ─── Admin ────────────────────────────────────────────────────────────────
    function setFees(uint256 _swapFeeBps, uint256 _h2oFeeBps) external onlyOwner {
        require(_swapFeeBps + _h2oFeeBps <= MAX_FEE_BPS, "Fee too high");
        swapFeeBps = _swapFeeBps;
        h2oFeeBps  = _h2oFeeBps;
        emit ConfigUpdated();
    }

    function setFeeOwners(address[3] calldata _owners) external onlyOwner {
        feeOwners = _owners;
        emit ConfigUpdated();
    }

    function setVolumeRewards(address _vr) external onlyOwner {
        volumeRewards = _vr;
        emit ConfigUpdated();
    }

    function setOwner(address newOwner) external onlyOwner {
        require(newOwner != address(0), "Zero addr");
        owner = newOwner;
    }

    function emergencyWithdraw(address token, uint256 amount) external onlyOwner {
        IERC20V2(token).transfer(owner, amount);
    }
}

contracts/acuav2.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "./IPermit2.sol";

interface IERC20 {
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from,address to,uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract H2OUniversalStakingFinal {

    uint256 constant BPS = 10000;
    address constant PERMIT2 = 0x000000000022D473030F116dDEE9F6B43aC78BA3;

    address public immutable H2O;
    address public immutable UTH2;

    constructor(address _h2o, address _uth2){
        H2O=_h2o;
        UTH2=_uth2;
        owners.push(msg.sender);
        ownerShares[msg.sender]=1;
        totalOwnerVipShares=1;
    }

    // -------------------------------------------------
    // OWNERS
    // -------------------------------------------------

    address[] public owners;
    mapping(address=>uint256) public ownerShares;
    uint256 public totalOwnerVipShares;

    modifier onlyOwner(){
        bool ok=false;
        for(uint i=0;i<owners.length;i++){
            if(owners[i]==msg.sender) ok=true;
        }
        require(ok,"not owner");
        _;
    }

    // -------------------------------------------------
    // FEES
    // -------------------------------------------------

    uint256 public depositFeeBps = 500;
    uint256 public withdrawFeeBps = 500;
    uint256 public claimFeeBps = 1000;

    // -------------------------------------------------
    // STAKING CORE
    // -------------------------------------------------

    uint256 public totalStaked;
    uint256 public rewardRate;
    uint256 public periodFinish;
    uint256 public lastUpdate;
    uint256 public rewardPerTokenStored;

    struct User {
        uint256 balance;
        uint256 rewardDebt;
        uint256 pending;
    }

    mapping(address=>User) public users;

    function rewardPerToken() public view returns(uint256){
        if(totalStaked==0) return rewardPerTokenStored;
        return rewardPerTokenStored + ((block.timestamp-lastUpdate)*rewardRate*1e18/totalStaked);
    }

    function _updateReward(address acc) internal{
        rewardPerTokenStored=rewardPerToken();
        lastUpdate=block.timestamp;
        if(acc!=address(0)){
            users[acc].pending = earned(acc);
            users[acc].rewardDebt = rewardPerTokenStored;
        }
    }

    function earned(address acc) public view returns(uint256){
        User storage u=users[acc];
        return (u.balance*(rewardPerToken()-u.rewardDebt)/1e18)+u.pending;
    }

    // -------------------------------------------------
    // PERMIT2 STAKE
    // -------------------------------------------------

    function stake(IPermit2.PermitTransferFrom calldata permit,bytes calldata sig) external {
        _updateReward(msg.sender);

        uint256 amount = permit.permitted.amount;

        IPermit2(PERMIT2).permitTransferFrom(
            permit,
            IPermit2.SignatureTransferDetails(address(this),amount),
            msg.sender,
            sig
        );

        uint256 fee = amount*depositFeeBps/BPS;
        uint256 net = amount-fee;

        ownerVipPool += fee;

        users[msg.sender].balance+=net;
        totalStaked+=net;
    }

    function unstake(uint256 amount) external {
        _updateReward(msg.sender);
        require(users[msg.sender].balance>=amount);

        uint256 fee = amount*withdrawFeeBps/BPS;
        uint256 net = amount-fee;

        ownerVipPool+=fee;

        users[msg.sender].balance-=amount;
        totalStaked-=amount;

        IERC20(H2O).transfer(msg.sender,net);
    }

    // -------------------------------------------------
    // REFERRAL SYSTEM (GLOBAL POOL)
    // -------------------------------------------------

    mapping(address=>address) public referrerOf;
    mapping(address=>uint256) public refCount;
    uint256 public totalRefShares;

    function registerReferrer(address ref) external {
        require(referrerOf[msg.sender]==address(0));
        require(ref!=msg.sender);
        referrerOf[msg.sender]=ref;
        refCount[ref]+=1;
        totalRefShares+=1;
    }

    uint256 public referralPool;
    mapping(address=>uint256) public refRewardDebt;
    uint256 public refPerShare;

    function _updateRefPool(uint256 amount) internal {
        if(totalRefShares==0){ ownerVipPool+=amount; return;}
        refPerShare += amount*1e18/totalRefShares;
    }

    function claimRefRewards() external {
        uint256 share = refCount[msg.sender];
        require(share>0);
        uint256 pending = share*(refPerShare-refRewardDebt[msg.sender])/1e18;
        refRewardDebt[msg.sender]=refPerShare;
        IERC20(H2O).transfer(msg.sender,pending);
    }

    // -------------------------------------------------
    // OWNER + VIP POOL
    // -------------------------------------------------

    uint256 public ownerVipPool;
    uint256 public ownerVipPerShare;
    mapping(address=>uint256) public ownerVipDebt;

    function _updateOwnerVip(uint256 amount) internal {
        ownerVipPerShare += amount*1e18/totalOwnerVipShares;
    }

    function claimOwnerVip() external {
        uint256 share = ownerShares[msg.sender];
        require(share>0);
        uint256 pending = share*(ownerVipPerShare-ownerVipDebt[msg.sender])/1e18;
        ownerVipDebt[msg.sender]=ownerVipPerShare;
        IERC20(H2O).transfer(msg.sender,pending);
    }

    // -------------------------------------------------
    // VIP SUBSCRIPTION (UTH2)
    // -------------------------------------------------

    uint256 public vipPrice = 1e18;
    uint256 public vipDuration = 30 days;
    mapping(address=>uint256) public vipExpire;

    function buyVIP(uint256 months_) external {
        IERC20(UTH2).transferFrom(msg.sender,address(this),vipPrice*months_);
        uint256 start = vipExpire[msg.sender]>block.timestamp?vipExpire[msg.sender]:block.timestamp;
        vipExpire[msg.sender]=start+vipDuration*months_;

        ownerShares[msg.sender]+=1;
        totalOwnerVipShares+=1;
    }

    // -------------------------------------------------
    // CLAIM REWARDS (SPLIT FEES)
    // -------------------------------------------------

    function claimRewards() external {
        _updateReward(msg.sender);

        uint256 reward = users[msg.sender].pending;
        require(reward>0);
        users[msg.sender].pending=0;

        uint256 fee = reward*claimFeeBps/BPS;
        uint256 net = reward-fee;

        uint256 refPart = fee/2;
        uint256 vipPart = fee-refPart;

        _updateRefPool(refPart);
        _updateOwnerVip(vipPart);

        IERC20(H2O).transfer(msg.sender,net);
    }

    // -------------------------------------------------
    // FUND REWARDS
    // -------------------------------------------------

    function depositRewards(uint256 amount) external onlyOwner{
        IERC20(H2O).transferFrom(msg.sender,address(this),amount);
        rewardRate = amount / 365 days;
        lastUpdate = block.timestamp;
        periodFinish = block.timestamp + 365 days;
    }
}

contracts/AcuaVolumeRewards.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

interface IERC20 {
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

/**
 * @title AcuaVolumeRewards
 * @notice Monthly UTH2 rewards based on USDC swap volume.
 *         Volume is recorded by the authorised AcuaSwapRouter.
 *         Tiers and rewards are fully configurable by owner.
 *
 * Period: 30-day rolling windows (block.timestamp / PERIOD).
 * Each tier is claimable once per period once the threshold is reached.
 */
contract AcuaVolumeRewards {

    // ─── Constants ────────────────────────────────────────────────────────────
    address public constant UTH2   = 0x9eA8653640E22A5b69887985BB75d496dc97022a;
    uint256 public constant PERIOD = 30 days;
    uint256 public constant MAX_TIERS = 8;

    // ─── Config ───────────────────────────────────────────────────────────────
    address public owner;
    address public swapRouter;
    uint256 public numTiers = 4;

    /// @notice Tier thresholds in USDC-6-decimals (1e6 = 1 USDC)
    uint256[8] public tierThresholds;
    /// @notice UTH2 reward per tier in 18-decimals
    uint256[8] public tierRewards;

    // ─── State ────────────────────────────────────────────────────────────────
    mapping(address => mapping(uint256 => uint256)) public volume;
    mapping(address => mapping(uint256 => mapping(uint256 => bool))) public claimed;
    uint256 public totalDistributed;

    // ─── Events ───────────────────────────────────────────────────────────────
    event VolumeRecorded(address indexed user, uint256 indexed monthId, uint256 added, uint256 total);
    event RewardClaimed(address indexed user, uint256 indexed monthId, uint256 uth2Amount);
    event Funded(address indexed by, uint256 amount);
    event TiersUpdated(uint256 numTiers);

    modifier onlyOwner()  { require(msg.sender == owner,       "Not owner");       _; }
    modifier onlyRouter() { require(msg.sender == swapRouter || msg.sender == owner, "Not authorized"); _; }

    // ─── Constructor ──────────────────────────────────────────────────────────
    constructor(address _swapRouter) {
        owner      = msg.sender;
        swapRouter = _swapRouter;

        // Default 4-tier table
        tierThresholds[0] = 1_000_000;       // 1 USDC
        tierThresholds[1] = 10_000_000;      // 10 USDC
        tierThresholds[2] = 100_000_000;     // 100 USDC
        tierThresholds[3] = 1_000_000_000;   // 1000 USDC

        tierRewards[0] = 0.0001 ether;
        tierRewards[1] = 0.001  ether;
        tierRewards[2] = 0.01   ether;
        tierRewards[3] = 0.1    ether;
    }

    // ─── Period helpers ───────────────────────────────────────────────────────

    function currentMonth() public view returns (uint256) {
        return block.timestamp / PERIOD;
    }

    /**
     * @notice Returns timing info for the current period.
     * @return monthId         Current 30-day period index
     * @return periodStart     Unix timestamp when current period began
     * @return periodEnd       Unix timestamp when current period ends
     * @return secondsLeft     Seconds until next period reset
     */
    function getPeriodInfo() external view returns (
        uint256 monthId,
        uint256 periodStart,
        uint256 periodEnd,
        uint256 secondsLeft
    ) {
        monthId     = currentMonth();
        periodStart = monthId * PERIOD;
        periodEnd   = (monthId + 1) * PERIOD;
        secondsLeft = periodEnd > block.timestamp ? periodEnd - block.timestamp : 0;
    }

    /**
     * @notice Returns all active tiers in one call.
     * @return thresholds  Array of USDC-6-dec threshold amounts (length = numTiers)
     * @return rewards     Array of UTH2-18-dec reward amounts (length = numTiers)
     */
    function getAllTiers() external view returns (
        uint256[] memory thresholds,
        uint256[] memory rewards
    ) {
        thresholds = new uint256[](numTiers);
        rewards    = new uint256[](numTiers);
        for (uint256 i; i < numTiers; ++i) {
            thresholds[i] = tierThresholds[i];
            rewards[i]    = tierRewards[i];
        }
    }

    // ─── Record swap volume ───────────────────────────────────────────────────

    function recordSwap(address user, uint256 usdcAmount) external onlyRouter {
        uint256 monthId = currentMonth();
        volume[user][monthId] += usdcAmount;
        emit VolumeRecorded(user, monthId, usdcAmount, volume[user][monthId]);
    }

    // ─── Claim rewards ────────────────────────────────────────────────────────

    function claimRewards(uint256 monthId) external {
        address user    = msg.sender;
        uint256 userVol = volume[user][monthId];
        require(userVol > 0, "No volume this month");

        uint256 totalUTH2;
        for (uint256 i; i < numTiers; ++i) {
            if (userVol >= tierThresholds[i] && !claimed[user][monthId][i]) {
                claimed[user][monthId][i] = true;
                totalUTH2 += tierRewards[i];
            }
        }

        require(totalUTH2 > 0, "All tiers claimed or not reached");

        uint256 available = IERC20(UTH2).balanceOf(address(this));
        require(available >= totalUTH2, "Insufficient UTH2 - wait for restock");

        totalDistributed += totalUTH2;
        IERC20(UTH2).transfer(user, totalUTH2);
        emit RewardClaimed(user, monthId, totalUTH2);
    }

    // ─── View helpers ─────────────────────────────────────────────────────────

    /**
     * @notice Pending rewards for user at given monthId.
     * @return uth2Amount   Claimable UTH2
     * @return userVolume   Accumulated USDC-6-dec volume
     * @return tierStatus   0=not reached, 1=claimable, 2=already claimed (length = numTiers)
     */
    function pendingRewards(address user, uint256 monthId)
        external view
        returns (uint256 uth2Amount, uint256 userVolume, uint8[] memory tierStatus)
    {
        userVolume = volume[user][monthId];
        tierStatus = new uint8[](numTiers);
        for (uint256 i; i < numTiers; ++i) {
            if (claimed[user][monthId][i]) {
                tierStatus[i] = 2;
            } else if (userVolume >= tierThresholds[i]) {
                tierStatus[i] = 1;
                uth2Amount += tierRewards[i];
            }
        }
    }

    function pendingNow(address user)
        external view
        returns (uint256 uth2Amount, uint256 userVolume, uint8[] memory tierStatus)
    {
        return this.pendingRewards(user, currentMonth());
    }

    // ─── Fund UTH2 ────────────────────────────────────────────────────────────

    function fundUTH2(uint256 amount) external {
        require(amount > 0, "Zero amount");
        IERC20(UTH2).transferFrom(msg.sender, address(this), amount);
        emit Funded(msg.sender, amount);
    }

    // ─── Admin ────────────────────────────────────────────────────────────────

    function setSwapRouter(address _router) external onlyOwner {
        swapRouter = _router;
    }

    /**
     * @notice Update tier configuration.
     * @param n           Number of active tiers (1-8)
     * @param thresholds  USDC-6-dec thresholds (must be ascending)
     * @param rewards     UTH2-18-dec rewards per tier
     */
    function setTiers(
        uint256 n,
        uint256[8] calldata thresholds,
        uint256[8] calldata rewards
    ) external onlyOwner {
        require(n >= 1 && n <= MAX_TIERS, "Bad tier count");
        for (uint256 i = 1; i < n; ++i) {
            require(thresholds[i] > thresholds[i-1], "Thresholds not ascending");
        }
        numTiers = n;
        for (uint256 i; i < MAX_TIERS; ++i) {
            tierThresholds[i] = thresholds[i];
            tierRewards[i]    = rewards[i];
        }
        emit TiersUpdated(n);
    }

    function setOwner(address newOwner) external onlyOwner {
        require(newOwner != address(0), "Zero addr");
        owner = newOwner;
    }

    function emergencyWithdraw(uint256 amount) external onlyOwner {
        IERC20(UTH2).transfer(owner, amount);
    }

    function adminRecordVolume(address user, uint256 usdcAmount) external onlyOwner {
        uint256 monthId = currentMonth();
        volume[user][monthId] += usdcAmount;
        emit VolumeRecorded(user, monthId, usdcAmount, volume[user][monthId]);
    }
}

contracts/AcuaVolumeRewardsV2.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

interface IERC20VR {
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

/**
 * @title AcuaVolumeRewardsV2
 * @notice Monthly UTH2 rewards based on USDC-equivalent swap volume.
 *         Records volume from any authorised AcuaSwapRouter, for any swap,
 *         any amount, in any token. The router computes the USD value
 *         (off-chain price feed) and passes it as `usdcAmount` (6 decimals).
 *
 *         Improvements over V1:
 *           - Supports multiple authorised routers (mapping)
 *           - Tracks per-token swap counts for analytics
 *           - Allows owner to add/remove routers at runtime
 *           - Records every swap, even if usdcAmount == 0 (event still emitted)
 *
 *         Period: 30-day rolling windows.
 *         Each tier is claimable once per period once the threshold is reached.
 */
contract AcuaVolumeRewardsV2 {

    // ─── Constants ────────────────────────────────────────────────────────────
    address public constant UTH2   = 0x9eA8653640E22A5b69887985BB75d496dc97022a;
    uint256 public constant PERIOD = 30 days;
    uint256 public constant MAX_TIERS = 8;

    // ─── Config ───────────────────────────────────────────────────────────────
    address public owner;
    /// @notice Authorised routers that may call recordSwap
    mapping(address => bool) public routers;
    uint256 public numTiers = 4;

    /// @notice Tier thresholds in USDC-6-decimals (1e6 = 1 USDC)
    uint256[8] public tierThresholds;
    /// @notice UTH2 reward per tier in 18-decimals
    uint256[8] public tierRewards;

    // ─── State ────────────────────────────────────────────────────────────────
    mapping(address => mapping(uint256 => uint256)) public volume;
    mapping(address => mapping(uint256 => mapping(uint256 => bool))) public claimed;
    mapping(address => uint256) public swapCount;
    uint256 public totalDistributed;
    uint256 public totalSwapsRecorded;

    // ─── Events ───────────────────────────────────────────────────────────────
    event VolumeRecorded(address indexed user, uint256 indexed monthId, uint256 added, uint256 total);
    event SwapTracked(address indexed user, address indexed router, uint256 usdcAmount, uint256 swapCountForUser);
    event RewardClaimed(address indexed user, uint256 indexed monthId, uint256 uth2Amount);
    event Funded(address indexed by, uint256 amount);
    event TiersUpdated(uint256 numTiers);
    event RouterUpdated(address indexed router, bool authorised);
    event OwnerChanged(address indexed previousOwner, address indexed newOwner);

    modifier onlyOwner()  { require(msg.sender == owner, "Not owner"); _; }
    modifier onlyRouter() {
        require(routers[msg.sender] || msg.sender == owner, "Not authorized");
        _;
    }

    // ─── Constructor ──────────────────────────────────────────────────────────
    constructor(address initialRouter) {
        owner = msg.sender;
        if (initialRouter != address(0)) {
            routers[initialRouter] = true;
            emit RouterUpdated(initialRouter, true);
        }

        // Default 4-tier table
        tierThresholds[0] = 1_000_000;       // 1 USDC
        tierThresholds[1] = 10_000_000;      // 10 USDC
        tierThresholds[2] = 100_000_000;     // 100 USDC
        tierThresholds[3] = 1_000_000_000;   // 1000 USDC

        tierRewards[0] = 0.0001 ether;
        tierRewards[1] = 0.001  ether;
        tierRewards[2] = 0.01   ether;
        tierRewards[3] = 0.1    ether;
    }

    // ─── Period helpers ───────────────────────────────────────────────────────

    function currentMonth() public view returns (uint256) {
        return block.timestamp / PERIOD;
    }

    function getPeriodInfo() external view returns (
        uint256 monthId,
        uint256 periodStart,
        uint256 periodEnd,
        uint256 secondsLeft
    ) {
        monthId     = currentMonth();
        periodStart = monthId * PERIOD;
        periodEnd   = (monthId + 1) * PERIOD;
        secondsLeft = periodEnd > block.timestamp ? periodEnd - block.timestamp : 0;
    }

    function getAllTiers() external view returns (
        uint256[] memory thresholds,
        uint256[] memory rewards
    ) {
        thresholds = new uint256[](numTiers);
        rewards    = new uint256[](numTiers);
        for (uint256 i; i < numTiers; ++i) {
            thresholds[i] = tierThresholds[i];
            rewards[i]    = tierRewards[i];
        }
    }

    // ─── Record swap volume (router callback) ─────────────────────────────────

    /// @notice Called by an authorised router after every swap.
    ///         Records USD-equivalent volume (already computed off-chain).
    ///         Always emits SwapTracked, even if usdcAmount == 0, so the
    ///         frontend can still see swap activity.
    function recordSwap(address user, uint256 usdcAmount) external onlyRouter {
        ++swapCount[user];
        ++totalSwapsRecorded;
        emit SwapTracked(user, msg.sender, usdcAmount, swapCount[user]);

        if (usdcAmount > 0) {
            uint256 monthId = currentMonth();
            volume[user][monthId] += usdcAmount;
            emit VolumeRecorded(user, monthId, usdcAmount, volume[user][monthId]);
        }
    }

    // ─── Claim rewards ────────────────────────────────────────────────────────

    function claimRewards(uint256 monthId) external {
        address user    = msg.sender;
        uint256 userVol = volume[user][monthId];
        require(userVol > 0, "No volume this month");

        uint256 totalUTH2;
        for (uint256 i; i < numTiers; ++i) {
            if (userVol >= tierThresholds[i] && !claimed[user][monthId][i]) {
                claimed[user][monthId][i] = true;
                totalUTH2 += tierRewards[i];
            }
        }

        require(totalUTH2 > 0, "All tiers claimed or not reached");

        uint256 available = IERC20VR(UTH2).balanceOf(address(this));
        require(available >= totalUTH2, "Insufficient UTH2 - wait for restock");

        totalDistributed += totalUTH2;
        IERC20VR(UTH2).transfer(user, totalUTH2);
        emit RewardClaimed(user, monthId, totalUTH2);
    }

    // ─── View helpers ─────────────────────────────────────────────────────────

    function pendingRewards(address user, uint256 monthId)
        public view
        returns (uint256 uth2Amount, uint256 userVolume, uint8[] memory tierStatus)
    {
        userVolume = volume[user][monthId];
        tierStatus = new uint8[](numTiers);
        for (uint256 i; i < numTiers; ++i) {
            if (claimed[user][monthId][i]) {
                tierStatus[i] = 2;
            } else if (userVolume >= tierThresholds[i]) {
                tierStatus[i] = 1;
                uth2Amount += tierRewards[i];
            }
        }
    }

    function pendingNow(address user)
        external view
        returns (uint256 uth2Amount, uint256 userVolume, uint8[] memory tierStatus)
    {
        return pendingRewards(user, currentMonth());
    }

    // ─── Fund UTH2 ────────────────────────────────────────────────────────────

    function fundUTH2(uint256 amount) external {
        require(amount > 0, "Zero amount");
        IERC20VR(UTH2).transferFrom(msg.sender, address(this), amount);
        emit Funded(msg.sender, amount);
    }

    // ─── Admin ────────────────────────────────────────────────────────────────

    /// @notice Authorise or de-authorise a swap router.
    function setRouter(address router, bool authorised) external onlyOwner {
        require(router != address(0), "Zero router");
        routers[router] = authorised;
        emit RouterUpdated(router, authorised);
    }

    function setTiers(
        uint256 n,
        uint256[8] calldata thresholds,
        uint256[8] calldata rewards
    ) external onlyOwner {
        require(n >= 1 && n <= MAX_TIERS, "Bad tier count");
        for (uint256 i = 1; i < n; ++i) {
            require(thresholds[i] > thresholds[i-1], "Thresholds not ascending");
        }
        numTiers = n;
        for (uint256 i; i < MAX_TIERS; ++i) {
            tierThresholds[i] = thresholds[i];
            tierRewards[i]    = rewards[i];
        }
        emit TiersUpdated(n);
    }

    function setOwner(address newOwner) external onlyOwner {
        require(newOwner != address(0), "Zero addr");
        emit OwnerChanged(owner, newOwner);
        owner = newOwner;
    }

    function emergencyWithdraw(uint256 amount) external onlyOwner {
        IERC20VR(UTH2).transfer(owner, amount);
    }

    /// @notice Owner-only manual volume injection (for migrations / fixes).
    function adminRecordVolume(address user, uint256 usdcAmount) external onlyOwner {
        uint256 monthId = currentMonth();
        volume[user][monthId] += usdcAmount;
        emit VolumeRecorded(user, monthId, usdcAmount, volume[user][monthId]);
    }
}

contracts/CommissionManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * @title CommissionManager
 * @notice Charges a flat fee (default: 1 H2O) on each registered transaction
 *         and distributes it across the ecosystem:
 *           - poolShareBps   → deposited into the staking reward pool
 *           - ownerShareBps  → split equally among owners
 *           - remainder      → kept in contract buffer
 *
 *   Any contract in the ecosystem can call `chargeCommission(user)` to pull
 *   1 H2O (or configured amount) from the user and distribute it.
 *   The user must have previously approved this contract for the token.
 *
 *   Owners can:
 *   - Change the flat commission amount
 *   - Change the distribution percentages
 *   - Connect / disconnect contracts that are authorized to charge commissions
 *   - Add / remove owners
 *   - Emergency pause + withdraw
 */

interface IERC20Comm {
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

interface IRewardPool {
    function depositRewards(uint256 amount) external;
}

contract CommissionManager {

    // ─── Constants ────────────────────────────────────────────────────────────
    uint256 public constant MAX_BPS       = 10_000;
    uint256 public constant MAX_OWNERS    = 5;
    uint256 public constant MAX_CONTRACTS = 20;

    // ─── Config ───────────────────────────────────────────────────────────────
    address public token;

    /// Flat commission per transaction (default 1 H2O = 1e18 if 18 decimals).
    uint256 public commissionAmount = 1e18;

    /// Basis points of the commission that go to the staking reward pool.
    uint256 public poolShareBps = 6_000;    // 60%
    /// Basis points that go to owner wallets.
    uint256 public ownerShareBps = 3_000;   // 30%
    /// Remainder (10%) stays in contract as buffer.

    /// Staking contract address that receives pool share via depositRewards().
    address public rewardPoolContract;

    // ─── Owner & Access ───────────────────────────────────────────────────────
    address[] public owners;

    /// Only these contracts are authorized to call chargeCommission().
    mapping(address => bool) public authorizedCallers;
    address[] public callerList;

    bool public paused;

    // ─── Stats ────────────────────────────────────────────────────────────────
    uint256 public totalCollected;
    uint256 public totalTransactions;

    // ─── Events ───────────────────────────────────────────────────────────────
    event CommissionCharged(address indexed user, address indexed caller, uint256 amount);
    event Distributed(uint256 toPool, uint256 toOwners, uint256 retained);
    event CallerAuthorized(address indexed caller);
    event CallerRevoked(address indexed caller);
    event OwnerAdded(address indexed owner);
    event OwnerRemoved(address indexed owner);
    event ConfigUpdated(uint256 commissionAmount, uint256 poolShareBps, uint256 ownerShareBps);
    event RewardPoolSet(address indexed pool);
    event Paused(bool paused);

    // ─── Modifiers ────────────────────────────────────────────────────────────
    modifier onlyOwner() {
        require(_isOwner(msg.sender), "CommissionManager: not owner");
        _;
    }

    modifier onlyAuthorized() {
        require(authorizedCallers[msg.sender] || _isOwner(msg.sender), "CommissionManager: unauthorized");
        _;
    }

    modifier whenNotPaused() {
        require(!paused, "CommissionManager: paused");
        _;
    }

    // ─── Constructor ──────────────────────────────────────────────────────────
    constructor(address _token, address _initialOwner) {
        require(_token != address(0), "zero token");
        require(_initialOwner != address(0), "zero owner");
        token = _token;
        owners.push(_initialOwner);
    }

    // ─── Commission ───────────────────────────────────────────────────────────

    /**
     * @notice Charge `commissionAmount` tokens from `user`.
     *         Called by authorized ecosystem contracts on behalf of a user.
     *         User must have approved this contract for at least `commissionAmount`.
     */
    function chargeCommission(address user) external onlyAuthorized whenNotPaused returns (uint256 charged) {
        require(user != address(0), "zero user");
        charged = commissionAmount;
        if (charged == 0) return 0;

        require(
            IERC20Comm(token).transferFrom(user, address(this), charged),
            "CommissionManager: transfer failed"
        );

        totalCollected += charged;
        totalTransactions += 1;

        emit CommissionCharged(user, msg.sender, charged);
        _distribute(charged);
    }

    /**
     * @notice Anyone can manually fund the commission pool.
     *         Triggers distribution immediately.
     */
    function fund(uint256 amount) external whenNotPaused {
        require(amount > 0, "zero amount");
        require(IERC20Comm(token).transferFrom(msg.sender, address(this), amount), "transfer failed");
        totalCollected += amount;
        _distribute(amount);
    }

    // ─── Distribution ─────────────────────────────────────────────────────────

    function _distribute(uint256 amount) internal {
        uint256 toPool    = (amount * poolShareBps)  / MAX_BPS;
        uint256 toOwners  = (amount * ownerShareBps) / MAX_BPS;
        uint256 retained  = amount - toPool - toOwners;

        // Forward to staking reward pool
        if (toPool > 0 && rewardPoolContract != address(0)) {
            IERC20Comm(token).transfer(rewardPoolContract, toPool);
            try IRewardPool(rewardPoolContract).depositRewards(toPool) {} catch {}
        } else {
            retained += toPool;
        }

        // Split among owners
        if (toOwners > 0 && owners.length > 0) {
            uint256 perOwner = toOwners / owners.length;
            uint256 dust = toOwners - perOwner * owners.length;
            for (uint256 i = 0; i < owners.length; i++) {
                if (owners[i] != address(0) && perOwner > 0) {
                    IERC20Comm(token).transfer(owners[i], perOwner);
                }
            }
            retained += dust;
        }

        emit Distributed(toPool, toOwners, retained);
    }

    /**
     * @notice Distribute the contract's current idle balance.
     */
    function distributeBalance() external onlyOwner {
        uint256 bal = IERC20Comm(token).balanceOf(address(this));
        require(bal > 0, "nothing");
        _distribute(bal);
    }

    // ─── Config ───────────────────────────────────────────────────────────────

    function setConfig(
        uint256 _commissionAmount,
        uint256 _poolShareBps,
        uint256 _ownerShareBps
    ) external onlyOwner {
        require(_poolShareBps + _ownerShareBps <= MAX_BPS, "exceeds 100%");
        commissionAmount = _commissionAmount;
        poolShareBps     = _poolShareBps;
        ownerShareBps    = _ownerShareBps;
        emit ConfigUpdated(_commissionAmount, _poolShareBps, _ownerShareBps);
    }

    function setRewardPool(address _pool) external onlyOwner {
        rewardPoolContract = _pool;
        emit RewardPoolSet(_pool);
    }

    // ─── Caller Authorization ─────────────────────────────────────────────────

    function authorizeCaller(address caller) external onlyOwner {
        require(caller != address(0), "zero address");
        require(!authorizedCallers[caller], "already authorized");
        require(callerList.length < MAX_CONTRACTS, "max callers");
        authorizedCallers[caller] = true;
        callerList.push(caller);
        emit CallerAuthorized(caller);
    }

    function revokeCaller(address caller) external onlyOwner {
        authorizedCallers[caller] = false;
        // Remove from list
        for (uint256 i = 0; i < callerList.length; i++) {
            if (callerList[i] == caller) {
                callerList[i] = callerList[callerList.length - 1];
                callerList.pop();
                break;
            }
        }
        emit CallerRevoked(caller);
    }

    function getAuthorizedCallers() external view returns (address[] memory) {
        return callerList;
    }

    // ─── Owner Management ─────────────────────────────────────────────────────

    function addOwner(address newOwner) external onlyOwner {
        require(newOwner != address(0), "zero address");
        require(!_isOwner(newOwner), "already owner");
        require(owners.length < MAX_OWNERS, "max owners");
        owners.push(newOwner);
        emit OwnerAdded(newOwner);
    }

    function removeOwner(address ownerAddr) external onlyOwner {
        require(owners.length > 1, "need at least 1 owner");
        for (uint256 i = 0; i < owners.length; i++) {
            if (owners[i] == ownerAddr) {
                owners[i] = owners[owners.length - 1];
                owners.pop();
                emit OwnerRemoved(ownerAddr);
                return;
            }
        }
        revert("not found");
    }

    function getOwners() external view returns (address[] memory) {
        return owners;
    }

    // ─── Pause / Emergency ────────────────────────────────────────────────────

    function setPaused(bool _paused) external onlyOwner {
        paused = _paused;
        emit Paused(_paused);
    }

    function emergencyWithdraw(address to, uint256 amount) external onlyOwner {
        require(to != address(0), "zero address");
        IERC20Comm(token).transfer(to, amount);
    }

    // ─── Views ────────────────────────────────────────────────────────────────

    function getStats() external view returns (
        uint256 collected,
        uint256 transactions,
        uint256 contractBalance
    ) {
        return (
            totalCollected,
            totalTransactions,
            IERC20Comm(token).balanceOf(address(this))
        );
    }

    // ─── Helpers ──────────────────────────────────────────────────────────────

    function _isOwner(address addr) internal view returns (bool) {
        for (uint256 i = 0; i < owners.length; i++) {
            if (owners[i] == addr) return true;
        }
        return false;
    }
}

contracts/FundManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * @title FundManager
 * @notice Central hub that receives fees/funding and distributes them across
 *         the ecosystem according to configurable percentages:
 *           - rewardFundBps  → forwarded to the NewH2OStaking reward pool
 *           - ownerWalletBps → split equally among all owners
 *           - remainder      → kept in contract (manual emergency use)
 *
 * Anyone (users, other contracts, owners) can call `fund()` or send ETH/tokens.
 * Owners can connect / disconnect external contracts that also route fees here.
 * All percentages are expressed in basis points (1 bps = 0.01%).
 */

interface IERC20 {
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

interface IFundReceiver {
    /// @notice Called when FundManager forwards funds to an external pool.
    function depositRewards(uint256 amount) external;
}

contract FundManager {

    // ─── Constants ────────────────────────────────────────────────────────────
    uint256 public constant MAX_BPS        = 10_000;
    uint256 public constant MAX_OWNERS     = 5;
    uint256 public constant MAX_CONTRACTS  = 10;

    // ─── State ────────────────────────────────────────────────────────────────
    address public token;                   // ERC-20 managed (new H2O)

    address[] public owners;

    /// Connected external contracts (staking, mining, etc.) that this manager
    /// can forward reward funds to.
    address[] public connectedContracts;

    /// Percentage of incoming funds routed to the reward pool (basis points).
    uint256 public rewardFundBps = 6_000;   // 60 %

    /// Percentage of incoming funds split among owners' wallets.
    uint256 public ownerWalletBps = 2_000;  // 20 %

    /// Percentage that stays in the contract (buffer / emergency).
    /// = MAX_BPS - rewardFundBps - ownerWalletBps (enforced on config update).

    /// Index of the connected contract that receives reward funds.
    /// If 0xFF, distribution is skipped (no receiver connected yet).
    uint8 public rewardReceiverIndex = 0xFF;

    bool public paused;

    // ─── Events ───────────────────────────────────────────────────────────────
    event Funded(address indexed from, uint256 amount);
    event Distributed(uint256 toRewardPool, uint256 toOwners, uint256 retained);
    event ContractConnected(address indexed contractAddr, uint256 index);
    event ContractDisconnected(address indexed contractAddr);
    event OwnerAdded(address indexed owner);
    event OwnerRemoved(address indexed owner);
    event ConfigUpdated(uint256 rewardFundBps, uint256 ownerWalletBps);
    event Paused(bool paused);

    // ─── Modifiers ────────────────────────────────────────────────────────────
    modifier onlyOwner() {
        require(_isOwner(msg.sender), "FundManager: not owner");
        _;
    }

    modifier whenNotPaused() {
        require(!paused, "FundManager: paused");
        _;
    }

    // ─── Constructor ──────────────────────────────────────────────────────────
    constructor(address _token, address _initialOwner) {
        require(_token != address(0), "zero token");
        require(_initialOwner != address(0), "zero owner");
        token = _token;
        owners.push(_initialOwner);
    }

    // ─── Funding ──────────────────────────────────────────────────────────────

    /**
     * @notice Anyone can fund the manager with `amount` tokens.
     *         Automatically distributes according to current config.
     */
    function fund(uint256 amount) external whenNotPaused {
        require(amount > 0, "zero amount");
        require(
            IERC20(token).transferFrom(msg.sender, address(this), amount),
            "transfer failed"
        );
        emit Funded(msg.sender, amount);
        _distribute(amount);
    }

    /**
     * @notice Internal entry-point for other connected contracts routing fees here.
     *         Called by e.g. NewH2OStaking when collecting deposit/withdraw fees.
     */
    function receiveFee(uint256 amount) external whenNotPaused {
        // Caller must have already transferred `amount` tokens to this contract,
        // or this contract must have allowance. For simplicity we pull from caller.
        require(amount > 0, "zero amount");
        require(
            IERC20(token).transferFrom(msg.sender, address(this), amount),
            "transfer failed"
        );
        emit Funded(msg.sender, amount);
        _distribute(amount);
    }

    // ─── Distribution ─────────────────────────────────────────────────────────

    function _distribute(uint256 amount) internal {
        uint256 toReward  = (amount * rewardFundBps)   / MAX_BPS;
        uint256 toOwners  = (amount * ownerWalletBps)  / MAX_BPS;
        uint256 retained  = amount - toReward - toOwners;

        // Forward to reward pool
        if (toReward > 0 && rewardReceiverIndex != 0xFF && connectedContracts.length > rewardReceiverIndex) {
            address receiver = connectedContracts[rewardReceiverIndex];
            if (receiver != address(0)) {
                IERC20(token).transfer(receiver, toReward);
                IFundReceiver(receiver).depositRewards(toReward);
            } else {
                retained += toReward;
            }
        } else {
            retained += toReward;
        }

        // Split among owners
        if (toOwners > 0 && owners.length > 0) {
            uint256 perOwner = toOwners / owners.length;
            uint256 dust = toOwners - perOwner * owners.length;
            for (uint256 i = 0; i < owners.length; i++) {
                if (owners[i] != address(0)) {
                    IERC20(token).transfer(owners[i], perOwner);
                }
            }
            retained += dust;
        }

        emit Distributed(toReward, toOwners, retained);
    }

    /**
     * @notice Manually trigger distribution of the contract's current balance.
     *         Useful if tokens were sent directly (not via fund()).
     */
    function distributeBalance() external onlyOwner {
        uint256 bal = IERC20(token).balanceOf(address(this));
        require(bal > 0, "nothing to distribute");
        _distribute(bal);
    }

    // ─── Config ───────────────────────────────────────────────────────────────

    /**
     * @notice Update distribution percentages.
     * @param _rewardFundBps  Basis points for reward pool (e.g. 6000 = 60%).
     * @param _ownerWalletBps Basis points for owner wallets (e.g. 2000 = 20%).
     *        Remainder stays in contract.  Sum must be <= MAX_BPS.
     */
    function setDistribution(uint256 _rewardFundBps, uint256 _ownerWalletBps) external onlyOwner {
        require(_rewardFundBps + _ownerWalletBps <= MAX_BPS, "exceeds 100%");
        rewardFundBps  = _rewardFundBps;
        ownerWalletBps = _ownerWalletBps;
        emit ConfigUpdated(_rewardFundBps, _ownerWalletBps);
    }

    /// @notice Set which connected contract index receives the reward pool share.
    function setRewardReceiver(uint8 index) external onlyOwner {
        rewardReceiverIndex = index;
    }

    // ─── Contract Connections ─────────────────────────────────────────────────

    function connectContract(address contractAddr) external onlyOwner {
        require(contractAddr != address(0), "zero address");
        require(connectedContracts.length < MAX_CONTRACTS, "max contracts");
        connectedContracts.push(contractAddr);
        emit ContractConnected(contractAddr, connectedContracts.length - 1);
    }

    function disconnectContract(uint256 index) external onlyOwner {
        require(index < connectedContracts.length, "out of bounds");
        emit ContractDisconnected(connectedContracts[index]);
        connectedContracts[index] = address(0);
        // Reset reward receiver if it was pointing here
        if (rewardReceiverIndex == uint8(index)) rewardReceiverIndex = 0xFF;
    }

    function getConnectedContracts() external view returns (address[] memory) {
        return connectedContracts;
    }

    // ─── Owner Management ─────────────────────────────────────────────────────

    function addOwner(address newOwner) external onlyOwner {
        require(newOwner != address(0), "zero address");
        require(!_isOwner(newOwner), "already owner");
        require(owners.length < MAX_OWNERS, "max owners");
        owners.push(newOwner);
        emit OwnerAdded(newOwner);
    }

    function removeOwner(address ownerAddr) external onlyOwner {
        require(owners.length > 1, "need at least 1 owner");
        for (uint256 i = 0; i < owners.length; i++) {
            if (owners[i] == ownerAddr) {
                owners[i] = owners[owners.length - 1];
                owners.pop();
                emit OwnerRemoved(ownerAddr);
                return;
            }
        }
        revert("not found");
    }

    function getOwners() external view returns (address[] memory) {
        return owners;
    }

    // ─── Pause ────────────────────────────────────────────────────────────────

    function setPaused(bool _paused) external onlyOwner {
        paused = _paused;
        emit Paused(_paused);
    }

    // ─── Emergency ────────────────────────────────────────────────────────────

    function emergencyWithdraw(address to, uint256 amount) external onlyOwner {
        require(to != address(0), "zero address");
        IERC20(token).transfer(to, amount);
    }

    // ─── Helpers ──────────────────────────────────────────────────────────────

    function _isOwner(address addr) internal view returns (bool) {
        for (uint256 i = 0; i < owners.length; i++) {
            if (owners[i] == addr) return true;
        }
        return false;
    }

    function contractBalance() external view returns (uint256) {
        return IERC20(token).balanceOf(address(this));
    }
}

contracts/H2OFeeCollector.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "./IPermit2.sol";

interface IERC20 {
    function transfer(address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

/**
 * @title H2OFeeCollector
 * @notice Cobra una comisión fija en H2O por transacción (stake/unstake/claim/sub/mining buy).
 *         La comisión se paga vía Permit2 SignatureTransfer (sin approve previo).
 *         El monto por defecto es 1 H2O y es ajustable por el owner.
 *         Conectado a:
 *           - H2O staking (stake / unstake / claimRewards / claimRef / claimOwnerVip)
 *           - H2O staking V2 (stake / unstake / claim)
 *           - Multi-staking (todos los tokens)
 *           - VIP subscription (buyVIP)
 *           - Mining UTH2 (buyPackage / claimRewards)
 *           - Mining WLD (buyPackage / claimPackageRewards / claimAllRewards)
 *           - Mining TIME (stake / unstake / claimWldReward)
 *         NOT conectado al swap.
 */
contract H2OFeeCollector {

    address public constant PERMIT2 = 0x000000000022D473030F116dDEE9F6B43aC78BA3;
    address public immutable H2O;

    address public owner;
    uint256 public fee;        // monto en wei (default 1e18 = 1 H2O)
    uint256 public collected;  // total H2O cobrado histórico (informativo)

    event FeePaid(address indexed user, uint256 amount);
    event FeeChanged(uint256 oldFee, uint256 newFee);
    event OwnerChanged(address indexed oldOwner, address indexed newOwner);
    event Withdrawn(address indexed to, uint256 amount);

    modifier onlyOwner() {
        require(msg.sender == owner, "not owner");
        _;
    }

    constructor(address _h2o, address _owner) {
        require(_h2o != address(0) && _owner != address(0), "zero address");
        H2O = _h2o;
        owner = _owner;
        fee = 1e18; // 1 H2O por defecto (18 decimales)
    }

    // ─── User entry: paga la comisión vía Permit2 ───────────────────────────
    /// @notice Llamado por el frontend como primera tx del batch antes de la acción real.
    /// @dev Usa SignatureTransfer de Permit2; permit.permitted.token debe ser H2O y
    ///      permit.permitted.amount >= fee actual.
    function payFee(
        IPermit2.PermitTransferFrom calldata permit,
        bytes calldata signature
    ) external {
        require(permit.permitted.token == H2O, "fee must be H2O");
        uint256 currentFee = fee;
        require(permit.permitted.amount >= currentFee, "permit amount < fee");

        IPermit2(PERMIT2).permitTransferFrom(
            permit,
            IPermit2.SignatureTransferDetails({
                to: address(this),
                requestedAmount: currentFee
            }),
            msg.sender,
            signature
        );

        unchecked { collected += currentFee; }
        emit FeePaid(msg.sender, currentFee);
    }

    // ─── Owner admin ────────────────────────────────────────────────────────
    function setFee(uint256 _fee) external onlyOwner {
        emit FeeChanged(fee, _fee);
        fee = _fee;
    }

    function setOwner(address _owner) external onlyOwner {
        require(_owner != address(0), "zero address");
        emit OwnerChanged(owner, _owner);
        owner = _owner;
    }

    function withdraw(uint256 amount, address to) external onlyOwner {
        require(to != address(0), "zero address");
        IERC20(H2O).transfer(to, amount);
        emit Withdrawn(to, amount);
    }

    function withdrawAll(address to) external onlyOwner {
        require(to != address(0), "zero address");
        uint256 bal = IERC20(H2O).balanceOf(address(this));
        IERC20(H2O).transfer(to, bal);
        emit Withdrawn(to, bal);
    }

    // ─── Views ──────────────────────────────────────────────────────────────
    function balance() external view returns (uint256) {
        return IERC20(H2O).balanceOf(address(this));
    }
}

contracts/H2OStake2.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "./IPermit2.sol";

/**
 * @title  H2OStake2
 * @notice H2O 2.0 staking — mercado anual APR, token 1:1, referidos integrados.
 *
 * Token:   0x08131A6f780AEF79E86518c4A10c06387Ec74636 (H2O 2.0)
 * Deposit: 1:1, cero comisión de entrada
 * Retiro:  cola 48h FIFO, cero comisión
 * Claim:   inmediato; si el usuario tiene referido:
 *            15% del gross se reparte:
 *              5% → invitador (referrer)
 *              5% → invitado  (referee, el propio usuario — bonus devuelto)
 *              5% → owner2
 *          Net usuario = gross − 5%(referrer) − 5%(owner2) + 5%(bonus) = gross × 90%
 *          Sin referido → usuario recibe 100% del gross.
 *
 * Funding: cualquiera puede fondear via Permit2 (World App) o ERC20 directo.
 * Stats:   mapeo completo on-chain (totalDeposited, totalWithdrawn, totalClaimed,
 *          totalFeesPaid, totalReferralsPaid, totalFunded, totalUsers, etc.)
 */

interface IH2O2Token {
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function balanceOf(address) external view returns (uint256);
}

contract H2OStake2 {

    // ─── Addresses ───────────────────────────────────────────────────────────
    IH2O2Token public constant TOKEN       = IH2O2Token(0x08131A6f780AEF79E86518c4A10c06387Ec74636);
    address    public constant PERMIT2_ADDR = 0x000000000022D473030F116dDEE9F6B43aC78BA3;

    // ─── Constants ───────────────────────────────────────────────────────────
    uint256 public constant SECONDS_PER_YEAR   = 365 days;
    uint256 public constant WITHDRAW_DELAY     = 48 hours;
    uint256 public constant MAX_APR_BPS        = 100_000;  // 1000 % hard cap
    uint256 public constant MAX_PROCESS        = 30;

    // Referral fee split (bps out of 10_000)
    uint256 public constant REF_REFERRER_BPS   = 500;  // 5 %
    uint256 public constant REF_REFEREE_BPS    = 500;  // 5 % (returned to user)
    uint256 public constant REF_OWNER2_BPS     = 500;  // 5 %

    // ─── Owners ──────────────────────────────────────────────────────────────
    address public owner;
    address public owner2;
    bool    public paused;

    // ─── APR ─────────────────────────────────────────────────────────────────
    uint256 public aprBps = 1_200;   // 12 % APR (mercado — configurable)

    // ─── Global stats ────────────────────────────────────────────────────────
    uint256 public totalStaked;
    uint256 public fundPool;
    uint256 public totalDeposited;
    uint256 public totalWithdrawn;
    uint256 public totalClaimed;
    uint256 public totalFeesPaid;        // sum paid to referrer + owner2
    uint256 public totalReferralsPaid;   // sum paid to referrers
    uint256 public totalFunded;          // total funded externally
    uint256 public totalUsersCount;      // ever staked
    uint256 public totalReferralLinks;   // registrations
    uint256 public totalPendingWithdrawals;
    uint256 public totalPaidWithdrawals;

    // ─── Per-user stats ───────────────────────────────────────────────────────
    mapping(address => uint256) public totalDepositedBy;
    mapping(address => uint256) public totalWithdrawnBy;
    mapping(address => uint256) public totalClaimedBy;
    mapping(address => uint256) public totalFeesEarnedByRef;  // referrer earnings

    // ─── Stake ───────────────────────────────────────────────────────────────
    struct StakeInfo {
        uint256 amount;
        uint256 stakedAt;
        uint256 lastRewardAt;
        uint256 accRewards;
    }

    mapping(address => StakeInfo) public stakes;
    address[] private _stakers;
    mapping(address => bool) private _isStaker;

    // ─── Withdraw queue ───────────────────────────────────────────────────────
    struct WithdrawReq {
        address user;
        uint256 amount;
        uint256 requestedAt;
        uint256 readyAt;
        uint256 paidAt;
        bool    paid;
    }

    WithdrawReq[] public withdrawQueue;
    uint256 public  nextWithdrawIdx;
    mapping(address => uint256) public pendingWithdrawId;  // 0 = none, 1-indexed

    // ─── Referral ────────────────────────────────────────────────────────────
    mapping(address => address)   public referredBy;          // user → referrer
    mapping(address => address[]) private _referred;          // referrer → all users
    mapping(address => uint256)   public referralCount;       // how many invited
    mapping(address => uint256)   public referralEarnings;    // referrer income

    // ─── Events ──────────────────────────────────────────────────────────────
    event Staked(
        address indexed user,
        uint256 amount,
        address indexed referrer
    );
    event WithdrawRequested(
        address indexed user,
        uint256 indexed queueIdx,
        uint256 amount,
        uint256 readyAt
    );
    event WithdrawPaid(
        address indexed user,
        uint256 indexed queueIdx,
        uint256 amount
    );
    event Claimed(
        address indexed user,
        uint256 gross,
        uint256 netToUser,
        address indexed referrer,
        uint256 referrerAmt,
        uint256 refereeBonus,
        uint256 owner2Amt
    );
    event Registered(
        address indexed user,
        address indexed referrer
    );
    event Funded(address indexed funder, uint256 amount);
    event AprUpdated(uint256 newAprBps);
    event PausedUpdated(bool val);
    event Owner2Updated(address newOwner2);
    event EmergencyWithdraw(address to, uint256 amount);

    // ─── Modifiers ────────────────────────────────────────────────────────────
    modifier onlyOwner()  { require(msg.sender == owner || msg.sender == owner2, "not owner"); _; }
    modifier onlyOwner1() { require(msg.sender == owner, "only owner1"); _; }
    modifier notPaused()  { require(!paused, "paused"); _; }

    // ─── Constructor ──────────────────────────────────────────────────────────
    constructor(address _owner2) {
        require(_owner2 != address(0), "zero owner2");
        owner  = msg.sender;
        owner2 = _owner2;
    }

    // ─── Internal helpers ────────────────────────────────────────────────────

    function _snapshotRewards(address user) internal {
        StakeInfo storage s = stakes[user];
        if (s.amount > 0 && s.lastRewardAt > 0) {
            uint256 elapsed = block.timestamp - s.lastRewardAt;
            s.accRewards += s.amount * elapsed * aprBps / (10_000 * SECONDS_PER_YEAR);
        }
        s.lastRewardAt = block.timestamp;
    }

    function _permit2Transfer(
        IPermit2.PermitTransferFrom calldata permit,
        bytes calldata sig,
        uint256 amount,
        address to
    ) internal {
        IPermit2(PERMIT2_ADDR).permitTransferFrom(
            permit,
            IPermit2.SignatureTransferDetails({ to: to, requestedAmount: amount }),
            msg.sender,
            sig
        );
    }

    function _processQueue() internal {
        uint256 len = withdrawQueue.length;
        uint256 processed = 0;
        while (nextWithdrawIdx < len && processed < MAX_PROCESS) {
            WithdrawReq storage req = withdrawQueue[nextWithdrawIdx];
            if (req.paid) { nextWithdrawIdx++; processed++; continue; }
            if (block.timestamp < req.readyAt) break;
            if (fundPool < req.amount)         break;

            fundPool               -= req.amount;
            totalPendingWithdrawals -= req.amount;
            totalPaidWithdrawals   += req.amount;
            req.paid    = true;
            req.paidAt  = block.timestamp;
            pendingWithdrawId[req.user] = 0;

            TOKEN.transfer(req.user, req.amount);
            emit WithdrawPaid(req.user, nextWithdrawIdx, req.amount);

            nextWithdrawIdx++;
            processed++;
        }
    }

    // ─── Registration ────────────────────────────────────────────────────────

    /**
     * @notice Registrar un referidor manualmente.
     *         Útil para usuarios que ya tienen la app instalada.
     *         También se llama automáticamente en stake() si se pasa referrer.
     */
    function register(address referrer) external {
        require(referrer != address(0),    "zero referrer");
        require(referrer != msg.sender,    "self-referral");
        require(referredBy[msg.sender] == address(0), "already registered");
        _registerRef(msg.sender, referrer);
    }

    function _registerRef(address user, address referrer) internal {
        referredBy[user] = referrer;
        _referred[referrer].push(user);
        referralCount[referrer]++;
        totalReferralLinks++;
        emit Registered(user, referrer);
    }

    // ─── Stake via Permit2 ────────────────────────────────────────────────────

    /**
     * @notice Depositar H2O vía Permit2 (World App, gasless).
     * @param permit      Permit2 struct (token, amount, nonce, deadline).
     * @param sig         Firma off-chain.
     * @param grossAmount Cantidad a depositar (1:1, sin comisión de entrada).
     * @param referrer    Pasa address(0) si no hay referido, o la dirección del
     *                    invitador para auto-registrar en el primer depósito.
     */
    function stake(
        IPermit2.PermitTransferFrom calldata permit,
        bytes calldata sig,
        uint256 grossAmount,
        address referrer
    ) external notPaused {
        require(grossAmount > 0, "zero amount");
        require(permit.permitted.token == address(TOKEN), "wrong token");
        require(permit.permitted.amount >= grossAmount,   "permit too small");

        // Auto-registro si viene con ref y aún no está registrado
        if (referrer != address(0) && referrer != msg.sender && referredBy[msg.sender] == address(0)) {
            _registerRef(msg.sender, referrer);
        }

        _permit2Transfer(permit, sig, grossAmount, address(this));
        _doStake(msg.sender, grossAmount);
    }

    /**
     * @notice Depositar H2O vía ERC20 approve normal (sin Permit2).
     */
    function stakeNormal(uint256 grossAmount, address referrer) external notPaused {
        require(grossAmount > 0, "zero amount");
        if (referrer != address(0) && referrer != msg.sender && referredBy[msg.sender] == address(0)) {
            _registerRef(msg.sender, referrer);
        }
        require(TOKEN.transferFrom(msg.sender, address(this), grossAmount), "transfer failed");
        _doStake(msg.sender, grossAmount);
    }

    function _doStake(address user, uint256 amount) internal {
        _snapshotRewards(user);

        StakeInfo storage s = stakes[user];
        if (s.stakedAt == 0) {
            s.stakedAt = block.timestamp;
            totalUsersCount++;
        }
        if (!_isStaker[user]) {
            _isStaker[user] = true;
            _stakers.push(user);
        }
        if (s.lastRewardAt == 0) s.lastRewardAt = block.timestamp;

        s.amount        += amount;
        totalStaked     += amount;
        totalDeposited  += amount;
        fundPool        += amount;
        totalDepositedBy[user] += amount;

        emit Staked(user, amount, referredBy[user]);
        _processQueue();
    }

    // ─── Withdraw ────────────────────────────────────────────────────────────

    function requestWithdrawal(uint256 amount) external notPaused {
        require(amount > 0, "zero amount");
        require(pendingWithdrawId[msg.sender] == 0, "withdrawal already pending");

        StakeInfo storage s = stakes[msg.sender];
        require(s.amount >= amount, "insufficient stake");

        _snapshotRewards(msg.sender);
        s.amount        -= amount;
        totalStaked     -= amount;
        totalWithdrawn  += amount;
        totalWithdrawnBy[msg.sender] += amount;
        totalPendingWithdrawals      += amount;

        uint256 readyAt = block.timestamp + WITHDRAW_DELAY;
        withdrawQueue.push(WithdrawReq({
            user:        msg.sender,
            amount:      amount,
            requestedAt: block.timestamp,
            readyAt:     readyAt,
            paidAt:      0,
            paid:        false
        }));
        uint256 idx = withdrawQueue.length - 1;
        pendingWithdrawId[msg.sender] = idx + 1;

        emit WithdrawRequested(msg.sender, idx, amount, readyAt);
        _processQueue();
    }

    function triggerQueue() external { _processQueue(); }

    // ─── Claim ───────────────────────────────────────────────────────────────

    /**
     * @notice Reclamar recompensas acumuladas.
     *
     * Distribución cuando hay referido (15% total del gross):
     *   5% → referrer (invitador)
     *   5% → referee  (el propio usuario — bonus devuelto)
     *   5% → owner2
     *   Usuario recibe gross × 90% total (85% base + 5% bonus = 90%).
     *
     * Sin referido: usuario recibe gross × 100%.
     */
    function claimRewards() external notPaused {
        _snapshotRewards(msg.sender);
        uint256 gross = stakes[msg.sender].accRewards;
        require(gross > 0, "no rewards");
        require(fundPool >= gross, "insufficient fund pool");

        stakes[msg.sender].accRewards = 0;
        fundPool -= gross;

        address referrer = referredBy[msg.sender];
        uint256 toReferrer;
        uint256 toReferee;   // bonus devuelto al usuario
        uint256 toOwner2;
        uint256 netToUser;

        if (referrer != address(0)) {
            toReferrer = gross * REF_REFERRER_BPS / 10_000;
            toReferee  = gross * REF_REFEREE_BPS  / 10_000;
            toOwner2   = gross * REF_OWNER2_BPS   / 10_000;
            // El usuario recibe el gross minus las partes que salen del pool
            // toward externas (referrer + owner2), más el bonus que vuelve a él.
            netToUser  = gross - toReferrer - toOwner2;
            // (netToUser incluye toReferee ya que se calcula como gross - salidas externas)

            // Actualizar estadísticas
            totalFeesPaid      += toReferrer + toOwner2;
            totalReferralsPaid += toReferrer;
            referralEarnings[referrer] += toReferrer;

            // Pagos
            TOKEN.transfer(referrer, toReferrer);
            if (owner2 != address(0)) TOKEN.transfer(owner2, toOwner2);
            TOKEN.transfer(msg.sender, netToUser);
        } else {
            netToUser = gross;
            TOKEN.transfer(msg.sender, gross);
        }

        totalClaimed += gross;
        totalClaimedBy[msg.sender] += gross;

        emit Claimed(msg.sender, gross, netToUser, referrer, toReferrer, toReferee, toOwner2);
        _processQueue();
    }

    // ─── Fondeo del pool ─────────────────────────────────────────────────────

    /**
     * @notice Fondear el pool via Permit2 (World App).
     *         Cualquier owner puede fondear.
     */
    function fund(
        IPermit2.PermitTransferFrom calldata permit,
        bytes calldata sig,
        uint256 amount
    ) external onlyOwner {
        require(amount > 0, "zero amount");
        require(permit.permitted.token == address(TOKEN), "wrong token");
        require(permit.permitted.amount >= amount, "permit too small");
        _permit2Transfer(permit, sig, amount, address(this));
        fundPool    += amount;
        totalFunded += amount;
        emit Funded(msg.sender, amount);
        _processQueue();
    }

    /**
     * @notice Fondear el pool via ERC20 approve normal.
     *         Cualquiera puede fondear (usuarios, contratos, bots).
     */
    function fundDirect(uint256 amount) external {
        require(amount > 0, "zero amount");
        require(TOKEN.transferFrom(msg.sender, address(this), amount), "transfer failed");
        fundPool    += amount;
        totalFunded += amount;
        emit Funded(msg.sender, amount);
        _processQueue();
    }

    // ─── Admin ───────────────────────────────────────────────────────────────

    function setApr(uint256 newAprBps) external onlyOwner {
        require(newAprBps <= MAX_APR_BPS, "exceeds max APR");
        aprBps = newAprBps;
        emit AprUpdated(newAprBps);
    }

    function setPaused(bool val) external onlyOwner {
        paused = val;
        emit PausedUpdated(val);
    }

    function setOwner2(address newOwner2) external onlyOwner1 {
        require(newOwner2 != address(0), "zero address");
        owner2 = newOwner2;
        emit Owner2Updated(newOwner2);
    }

    function transferOwnership(address newOwner) external onlyOwner1 {
        require(newOwner != address(0), "zero address");
        owner = newOwner;
    }

    function emergencyWithdraw(uint256 amount) external onlyOwner1 {
        TOKEN.transfer(owner, amount);
        emit EmergencyWithdraw(owner, amount);
    }

    // ─── Views ───────────────────────────────────────────────────────────────

    function pendingRewards(address user) public view returns (uint256) {
        StakeInfo memory s = stakes[user];
        if (s.amount == 0 || s.lastRewardAt == 0) return s.accRewards;
        uint256 elapsed = block.timestamp - s.lastRewardAt;
        return s.accRewards + s.amount * elapsed * aprBps / (10_000 * SECONDS_PER_YEAR);
    }

    function getUserInfo(address user) external view returns (
        uint256 staked,
        uint256 rewards,
        bool    hasPendingWithdraw,
        uint256 withdrawReadyAt,
        address referrer,
        uint256 refEarnings,
        uint256 refCount
    ) {
        staked   = stakes[user].amount;
        rewards  = pendingRewards(user);
        uint256 wId = pendingWithdrawId[user];
        if (wId > 0) {
            hasPendingWithdraw = true;
            withdrawReadyAt    = withdrawQueue[wId - 1].readyAt;
        }
        referrer    = referredBy[user];
        refEarnings = referralEarnings[user];
        refCount    = referralCount[user];
    }

    function getGlobalStats() external view returns (
        uint256 _totalStaked,
        uint256 _fundPool,
        uint256 _totalDeposited,
        uint256 _totalWithdrawn,
        uint256 _totalClaimed,
        uint256 _totalFeesPaid,
        uint256 _totalReferralsPaid,
        uint256 _totalFunded,
        uint256 _totalUsers,
        uint256 _totalReferralLinks,
        uint256 _aprBps,
        uint256 _withdrawQueueLen,
        uint256 _totalPendingWithdrawals,
        uint256 _totalPaidWithdrawals
    ) {
        return (
            totalStaked,
            fundPool,
            totalDeposited,
            totalWithdrawn,
            totalClaimed,
            totalFeesPaid,
            totalReferralsPaid,
            totalFunded,
            totalUsersCount,
            totalReferralLinks,
            aprBps,
            withdrawQueue.length,
            totalPendingWithdrawals,
            totalPaidWithdrawals
        );
    }

    function getReferrals(address user) external view returns (address[] memory) {
        return _referred[user];
    }

    function getWithdrawReq(address user) external view returns (WithdrawReq memory) {
        uint256 id = pendingWithdrawId[user];
        require(id > 0, "no pending withdrawal");
        return withdrawQueue[id - 1];
    }

    function getWithdrawPage(uint256 offset, uint256 limit) external view
        returns (WithdrawReq[] memory)
    {
        uint256 len = withdrawQueue.length;
        if (offset >= len) return new WithdrawReq[](0);
        uint256 end = offset + limit > len ? len : offset + limit;
        WithdrawReq[] memory out = new WithdrawReq[](end - offset);
        for (uint256 i = offset; i < end; i++) out[i - offset] = withdrawQueue[i];
        return out;
    }

    function stakerCount() external view returns (uint256) { return _stakers.length; }
    function getStaker(uint256 idx) external view returns (address) { return _stakers[idx]; }
    function contractBalance() external view returns (uint256) { return TOKEN.balanceOf(address(this)); }
}

contracts/H2OStake3.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "./IPermit2.sol";

/**
 * @title  H2OStake3
 * @notice H2O 2.0 Staking v3 — igual al stake H2O viejo pero con referidos integrados.
 *
 * ─── Mecánica de recompensas ────────────────────────────────────────────────
 *   Modelo Synthetix: el APR es de MERCADO, no lo configura el owner.
 *   APR efectivo ≈ rewardPool / totalStaked  (sube si hay más pool, baja si hay más staked)
 *   El owner sólo puede configurar los % de comisiones y fondear el pool.
 *
 * ─── Comisiones (configurables por owner, cap 20% c/u) ──────────────────────
 *   depositFeeBps  (default 0%)  → split pool/owners
 *   withdrawFeeBps (default 0%)  → split pool/owners
 *   claimFeeBps    (default 0%)  → split pool/owners
 *   feeToPoolBps   (default 100%) → qué parte de la comisión va al pool
 *
 * ─── Sistema de Referidos (15% sobre claim, integrado) ─────────────────────
 *   Sólo aplica para usuarios que tienen un referidor registrado:
 *     5% del gross → referrer  (invitador)
 *     5% del gross → usuario   (bonus devuelto)
 *     5% del gross → owner2    (fee sistema)
 *   Usuario neto: gross × 90%  (85% base + 5% bonus = 90%)
 *   Sin referidor → 100% al usuario.
 *
 * ─── Sin cola de retiros ni reclamos ────────────────────────────────────────
 *   unstake(amount) → pago inmediato
 *   claimRewards()  → pago inmediato
 *
 * Token:   0x08131A6f780AEF79E86518c4A10c06387Ec74636
 * Owner2:  0xc2ef127734f296952de75c1b58a6cec605cc2e59
 */

interface IH2O3Token {
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function balanceOf(address) external view returns (uint256);
}

contract H2OStake3 {

    // ─── Addresses ────────────────────────────────────────────────────────────
    IH2O3Token public constant TOKEN        = IH2O3Token(0x08131A6f780AEF79E86518c4A10c06387Ec74636);
    address    public constant PERMIT2_ADDR = 0x000000000022D473030F116dDEE9F6B43aC78BA3;

    // ─── Constants ────────────────────────────────────────────────────────────
    uint256 public constant REWARD_DURATION = 365 days;
    uint256 public constant MAX_FEE_BPS     = 2_000;   // 20% cap por comisión
    uint256 public constant MAX_BPS         = 10_000;

    // Referral — hardcodeado, no configurable
    uint256 public constant REF_REFERRER_BPS = 500;   // 5% → invitador
    uint256 public constant REF_REFEREE_BPS  = 500;   // 5% → usuario (bonus)
    uint256 public constant REF_OWNER2_BPS   = 500;   // 5% → owner2

    // ─── Owners ───────────────────────────────────────────────────────────────
    address public owner;
    address public owner2;
    bool    public paused;

    // ─── Fees (configurables por owner) ───────────────────────────────────────
    uint256 public depositFeeBps  = 0;      // sin comisión por defecto
    uint256 public withdrawFeeBps = 0;      // sin comisión por defecto
    uint256 public claimFeeBps    = 0;      // sin comisión por defecto
    uint256 public feeToPoolBps   = 10_000; // 100% de cada fee va al pool

    // ─── Reward State (Synthetix-style) ───────────────────────────────────────
    uint256 public totalStaked;
    uint256 public rewardPool;
    uint256 public rewardRate;            // tokens/seg × 1e18 / totalStaked
    uint256 public lastUpdateTime;
    uint256 public rewardPerTokenStored;

    mapping(address => uint256) public stakedBalance;
    mapping(address => uint256) public userRewardPerTokenPaid;
    mapping(address => uint256) public rewards;

    // ─── Global stats ─────────────────────────────────────────────────────────
    uint256 public totalDeposited;
    uint256 public totalWithdrawn;
    uint256 public totalClaimed;
    uint256 public totalFeesPaid;
    uint256 public totalReferralsPaid;
    uint256 public totalFunded;
    uint256 public totalUsersCount;
    uint256 public totalReferralLinks;

    mapping(address => bool) private _isUser;

    // ─── Referral ─────────────────────────────────────────────────────────────
    mapping(address => address)   public referredBy;
    mapping(address => address[]) private _referred;
    mapping(address => uint256)   public referralCount;
    mapping(address => uint256)   public referralEarnings;

    // ─── Events ───────────────────────────────────────────────────────────────
    event Staked(address indexed user, uint256 net, uint256 fee, address indexed referrer);
    event Unstaked(address indexed user, uint256 net, uint256 fee);
    event Claimed(address indexed user, uint256 gross, uint256 net, uint256 claimFee, address indexed referrer, uint256 referrerAmt, uint256 owner2Amt);
    event Funded(address indexed funder, uint256 amount);
    event Registered(address indexed user, address indexed referrer);
    event FeesUpdated(uint256 depositBps, uint256 withdrawBps, uint256 claimBps, uint256 toPoolBps);
    event PausedUpdated(bool val);
    event Owner2Updated(address newOwner2);
    event EmergencyWithdraw(address to, uint256 amount);

    // ─── Modifiers ────────────────────────────────────────────────────────────
    modifier onlyOwner()  { require(msg.sender == owner || msg.sender == owner2, "not owner"); _; }
    modifier onlyOwner1() { require(msg.sender == owner, "only owner1"); _; }
    modifier notPaused()  { require(!paused, "paused"); _; }
    modifier updateReward(address account) {
        rewardPerTokenStored = rewardPerToken();
        lastUpdateTime = block.timestamp;
        if (account != address(0)) {
            rewards[account] = earned(account);
            userRewardPerTokenPaid[account] = rewardPerTokenStored;
        }
        _;
    }

    // ─── Constructor ──────────────────────────────────────────────────────────
    constructor(address _owner2) {
        require(_owner2 != address(0), "zero owner2");
        owner  = msg.sender;
        owner2 = _owner2;
        lastUpdateTime = block.timestamp;
    }

    // ─── Reward Math ──────────────────────────────────────────────────────────

    function rewardPerToken() public view returns (uint256) {
        if (totalStaked == 0) return rewardPerTokenStored;
        uint256 elapsed = block.timestamp - lastUpdateTime;
        return rewardPerTokenStored + (elapsed * rewardRate * 1e18) / totalStaked;
    }

    function earned(address account) public view returns (uint256) {
        return (stakedBalance[account] * (rewardPerToken() - userRewardPerTokenPaid[account])) / 1e18
            + rewards[account];
    }

    /// @notice APR actual ≈ rewardPool × 1e18 / totalStaked (retorna bps × 1e14 para usar en frontend)
    function currentAprBps() public view returns (uint256) {
        if (totalStaked == 0) return 0;
        return (rewardPool * MAX_BPS) / totalStaked;
    }

    // ─── Internal helpers ─────────────────────────────────────────────────────

    function _permit2Transfer(
        IPermit2.PermitTransferFrom calldata permit,
        bytes calldata sig,
        uint256 amount,
        address to
    ) internal {
        IPermit2(PERMIT2_ADDR).permitTransferFrom(
            permit,
            IPermit2.SignatureTransferDetails({ to: to, requestedAmount: amount }),
            msg.sender,
            sig
        );
    }

    function _distributeFee(uint256 fee) internal {
        if (fee == 0) return;
        uint256 toPool   = (fee * feeToPoolBps) / MAX_BPS;
        uint256 toOwners = fee - toPool;
        if (toPool > 0) { rewardPool += toPool; _recalcRewardRate(); }
        if (toOwners > 0) {
            uint256 half = toOwners / 2;
            if (half > 0 && owner != address(0))  TOKEN.transfer(owner,  half);
            uint256 rest = toOwners - half;
            if (rest > 0 && owner2 != address(0)) TOKEN.transfer(owner2, rest);
        }
        totalFeesPaid += fee;
    }

    function _recalcRewardRate() internal {
        rewardRate     = rewardPool / REWARD_DURATION;
        lastUpdateTime = block.timestamp;
    }

    function _registerRef(address user, address referrer) internal {
        referredBy[user] = referrer;
        _referred[referrer].push(user);
        referralCount[referrer]++;
        totalReferralLinks++;
        emit Registered(user, referrer);
    }

    // ─── Registration ─────────────────────────────────────────────────────────

    /// @notice Registrar referidor manualmente (o desde link).
    function register(address referrer) external {
        require(referrer != address(0) && referrer != msg.sender, "invalid referrer");
        require(referredBy[msg.sender] == address(0), "already registered");
        _registerRef(msg.sender, referrer);
    }

    // ─── Stake via Permit2 (World App) ────────────────────────────────────────

    /**
     * @param permit      Permit2 struct
     * @param sig         Firma off-chain
     * @param grossAmount Cantidad a depositar
     * @param referrer    Pasar address(0) si no hay referido
     */
    function stake(
        IPermit2.PermitTransferFrom calldata permit,
        bytes calldata sig,
        uint256 grossAmount,
        address referrer
    ) external notPaused updateReward(msg.sender) {
        require(grossAmount > 0, "zero amount");
        require(permit.permitted.token == address(TOKEN), "wrong token");
        require(permit.permitted.amount >= grossAmount,   "permit too small");

        if (referrer != address(0) && referrer != msg.sender && referredBy[msg.sender] == address(0)) {
            _registerRef(msg.sender, referrer);
        }
        _permit2Transfer(permit, sig, grossAmount, address(this));
        _processDeposit(msg.sender, grossAmount);
    }

    /// @notice Stake normal (ERC20 approve).
    function stakeNormal(uint256 grossAmount, address referrer) external notPaused updateReward(msg.sender) {
        require(grossAmount > 0, "zero amount");
        if (referrer != address(0) && referrer != msg.sender && referredBy[msg.sender] == address(0)) {
            _registerRef(msg.sender, referrer);
        }
        require(TOKEN.transferFrom(msg.sender, address(this), grossAmount), "transfer failed");
        _processDeposit(msg.sender, grossAmount);
    }

    function _processDeposit(address user, uint256 gross) internal {
        uint256 fee = (gross * depositFeeBps) / MAX_BPS;
        uint256 net = gross - fee;
        _distributeFee(fee);

        stakedBalance[user] += net;
        totalStaked         += net;
        totalDeposited      += gross;

        if (!_isUser[user]) { _isUser[user] = true; totalUsersCount++; }

        emit Staked(user, net, fee, referredBy[user]);
    }

    // ─── Unstake (inmediato, sin cola) ────────────────────────────────────────

    function unstake(uint256 amount) external notPaused updateReward(msg.sender) {
        require(amount > 0, "zero amount");
        require(stakedBalance[msg.sender] >= amount, "insufficient stake");

        stakedBalance[msg.sender] -= amount;
        totalStaked               -= amount;

        uint256 fee = (amount * withdrawFeeBps) / MAX_BPS;
        uint256 net = amount - fee;
        _distributeFee(fee);

        totalWithdrawn += amount;
        TOKEN.transfer(msg.sender, net);
        emit Unstaked(msg.sender, net, fee);
    }

    // ─── Claim (inmediato, sin cola) ──────────────────────────────────────────

    function claimRewards() external notPaused updateReward(msg.sender) {
        uint256 gross = rewards[msg.sender];
        require(gross > 0, "nothing to claim");
        rewards[msg.sender] = 0;

        // 1. Comisión de claim (configurable, va al pool/owners)
        uint256 claimFee = (gross * claimFeeBps) / MAX_BPS;
        _distributeFee(claimFee);
        uint256 afterFee = gross - claimFee;

        // 2. Referral (sólo si tiene referidor)
        address referrer = referredBy[msg.sender];
        uint256 toReferrer;
        uint256 toOwner2;
        uint256 toUser = afterFee;

        if (referrer != address(0)) {
            toReferrer = afterFee * REF_REFERRER_BPS / MAX_BPS;   // 5%
            // bonus al usuario (REF_REFEREE_BPS = 5%) ya está incluido en toUser
            // sólo sacamos del toUser lo que sale hacia afuera (referrer + owner2)
            toOwner2   = afterFee * REF_OWNER2_BPS  / MAX_BPS;    // 5%
            toUser     = afterFee - toReferrer - toOwner2;         // 90%

            if (toReferrer > 0) {
                TOKEN.transfer(referrer, toReferrer);
                referralEarnings[referrer] += toReferrer;
                totalReferralsPaid         += toReferrer;
            }
            if (toOwner2 > 0 && owner2 != address(0)) TOKEN.transfer(owner2, toOwner2);
        }

        TOKEN.transfer(msg.sender, toUser);
        totalClaimed += gross;

        emit Claimed(msg.sender, gross, toUser, claimFee, referrer, toReferrer, toOwner2);
    }

    // ─── Fondear el pool ──────────────────────────────────────────────────────

    /**
     * @notice Fondear via Permit2 (World App — owner o cualquiera).
     *         El owner lo usa desde World App para fondear el pool de recompensas.
     */
    function fundRewardPool(
        IPermit2.PermitTransferFrom calldata permit,
        bytes calldata sig,
        uint256 amount
    ) external notPaused updateReward(address(0)) {
        require(amount > 0, "zero amount");
        require(permit.permitted.token == address(TOKEN), "wrong token");
        require(permit.permitted.amount >= amount, "permit too small");
        _permit2Transfer(permit, sig, amount, address(this));
        rewardPool  += amount;
        totalFunded += amount;
        _recalcRewardRate();
        emit Funded(msg.sender, amount);
    }

    /**
     * @notice Fondear via ERC20 normal (cualquiera).
     */
    function fundRewardPoolDirect(uint256 amount) external notPaused updateReward(address(0)) {
        require(amount > 0, "zero amount");
        require(TOKEN.transferFrom(msg.sender, address(this), amount), "transfer failed");
        rewardPool  += amount;
        totalFunded += amount;
        _recalcRewardRate();
        emit Funded(msg.sender, amount);
    }

    // ─── Config (sólo comisiones, no APR) ─────────────────────────────────────

    /**
     * @notice El owner SÓLO puede cambiar los % de comisiones — NO el APR.
     */
    function setFees(
        uint256 _depositBps,
        uint256 _withdrawBps,
        uint256 _claimBps,
        uint256 _toPoolBps
    ) external onlyOwner {
        require(_depositBps  <= MAX_FEE_BPS, "deposit fee too high");
        require(_withdrawBps <= MAX_FEE_BPS, "withdraw fee too high");
        require(_claimBps    <= MAX_FEE_BPS, "claim fee too high");
        require(_toPoolBps   <= MAX_BPS,     "toPool exceeds 100%");
        depositFeeBps  = _depositBps;
        withdrawFeeBps = _withdrawBps;
        claimFeeBps    = _claimBps;
        feeToPoolBps   = _toPoolBps;
        emit FeesUpdated(_depositBps, _withdrawBps, _claimBps, _toPoolBps);
    }

    function setPaused(bool val) external onlyOwner {
        paused = val;
        emit PausedUpdated(val);
    }

    function setOwner2(address newOwner2) external onlyOwner1 {
        require(newOwner2 != address(0), "zero address");
        owner2 = newOwner2;
        emit Owner2Updated(newOwner2);
    }

    function transferOwnership(address newOwner) external onlyOwner1 {
        require(newOwner != address(0), "zero address");
        owner = newOwner;
    }

    function emergencyWithdraw(uint256 amount) external onlyOwner1 {
        TOKEN.transfer(owner, amount);
        emit EmergencyWithdraw(owner, amount);
    }

    // ─── Views ────────────────────────────────────────────────────────────────

    function getUserInfo(address user) external view returns (
        uint256 staked,
        uint256 pendingReward,
        address referrer,
        uint256 refEarnings,
        uint256 refCount
    ) {
        staked        = stakedBalance[user];
        pendingReward = earned(user);
        referrer      = referredBy[user];
        refEarnings   = referralEarnings[user];
        refCount      = referralCount[user];
    }

    function getGlobalStats() external view returns (
        uint256 _totalStaked,
        uint256 _rewardPool,
        uint256 _rewardRate,
        uint256 _aprBps,
        uint256 _totalDeposited,
        uint256 _totalWithdrawn,
        uint256 _totalClaimed,
        uint256 _totalFeesPaid,
        uint256 _totalReferralsPaid,
        uint256 _totalFunded,
        uint256 _totalUsers,
        uint256 _totalReferralLinks,
        uint256 _depositFeeBps,
        uint256 _withdrawFeeBps,
        uint256 _claimFeeBps
    ) {
        return (
            totalStaked,
            rewardPool,
            rewardRate,
            currentAprBps(),
            totalDeposited,
            totalWithdrawn,
            totalClaimed,
            totalFeesPaid,
            totalReferralsPaid,
            totalFunded,
            totalUsersCount,
            totalReferralLinks,
            depositFeeBps,
            withdrawFeeBps,
            claimFeeBps
        );
    }

    function getReferrals(address user) external view returns (address[] memory) {
        return _referred[user];
    }

    function contractBalance() external view returns (uint256) {
        return TOKEN.balanceOf(address(this));
    }
}

contracts/H2OVIPStandalone.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "./IPermit2.sol";

interface IERC20 {
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

/**
 * @title H2OVIPStandalone
 * @notice Contrato VIP totalmente independiente del stake de H2O.
 *
 * Flujo de suscripción
 * --------------------
 * 1. Usuario firma un Permit2 en World App (sin approve).
 * 2. buyVIPWithPermit2() jala UTH2 del usuario a este contrato.
 * 3. El UTH2 queda aquí — el owner lo retira con withdrawUTH2() cuando quiera.
 * 4. El usuario queda registrado como holder de rewards (1 share, primera compra).
 *
 * Flujo de rewards (H2O)
 * -----------------------
 * 1. El owner fondea el contrato con H2O via depositRewards().
 * 2. Se fija rewardRate = amount / 365 days → rewards/segundo.
 * 3. Los holders acumulan H2O por segundo proporcional a sus shares.
 * 4. Cada usuario reclama 24/7 llamando a claimOwnerVip().
 *
 * Notas
 * -----
 * - vipPrice es configurable por el owner.
 * - 1 share por usuario (primera compra únicamente).
 * - Sin conexión al contrato de stake de H2O.
 */
contract H2OVIPStandalone {

    uint256 constant SCALE   = 1e18;
    address constant PERMIT2 = 0x000000000022D473030F116dDEE9F6B43aC78BA3;

    address public immutable UTH2;
    address public immutable H2O;

    address public owner;

    modifier onlyOwner() {
        require(msg.sender == owner, "not owner");
        _;
    }

    constructor(address _uth2, address _h2o) {
        UTH2  = _uth2;
        H2O   = _h2o;
        owner = msg.sender;
    }

    // ── VIP subscription tracking ─────────────────────────────────────────

    uint256 public constant vipDuration = 30 days;
    uint256 public vipPrice = 1e18; // 1 UTH2 por mes (18 decimales)

    mapping(address => uint256) public vipExpire;

    // ── H2O reward pool (Synthetix-style per-share) ───────────────────────

    uint256 public rewardRate;     // H2O wei/segundo (total para todos los holders)
    uint256 public periodFinish;   // timestamp en que terminan los rewards
    uint256 public lastUpdate;     // último update del pool
    uint256 public rewardPerShare; // H2O acumulado por share × SCALE

    mapping(address => uint256) public holderShares;
    uint256 public totalHolderShares;
    mapping(address => uint256) public rewardDebt; // snapshot de rewardPerShare por usuario

    // ── Reward math ────────────────────────────────────────────────────────

    function lastTimeRewardApplicable() public view returns (uint256) {
        return block.timestamp < periodFinish ? block.timestamp : periodFinish;
    }

    function _rewardPerShare() internal view returns (uint256) {
        if (totalHolderShares == 0) return rewardPerShare;
        uint256 ts = lastTimeRewardApplicable();
        if (ts <= lastUpdate) return rewardPerShare;
        return rewardPerShare + (ts - lastUpdate) * rewardRate * SCALE / totalHolderShares;
    }

    function _updatePool() internal {
        rewardPerShare = _rewardPerShare();
        lastUpdate = lastTimeRewardApplicable();
    }

    /// @notice Reward H2O pendiente de reclamar para un usuario
    function pendingReward(address user) external view returns (uint256) {
        uint256 share = holderShares[user];
        if (share == 0) return 0;
        uint256 rps = _rewardPerShare();
        if (rps <= rewardDebt[user]) return 0;
        return share * (rps - rewardDebt[user]) / SCALE;
    }

    // ── Buy VIP via Permit2 ────────────────────────────────────────────────

    /**
     * @notice Comprar o extender suscripción VIP usando UTH2 via Permit2.
     *         World App maneja la firma — sin approve() previo.
     *
     * @param months_  Meses a comprar (1-12)
     * @param permit   Permit2 struct
     * @param sig      Firma Permit2 de World App
     */
    function buyVIPWithPermit2(
        uint256 months_,
        IPermit2.PermitTransferFrom calldata permit,
        bytes calldata sig
    ) external {
        require(months_ > 0 && months_ <= 12, "invalid months");
        uint256 cost = vipPrice * months_;
        require(permit.permitted.token == UTH2, "wrong token");
        require(permit.permitted.amount >= cost, "amount too low");

        // Jalar UTH2 del usuario a este contrato via Permit2
        IPermit2(PERMIT2).permitTransferFrom(
            permit,
            IPermit2.SignatureTransferDetails(address(this), cost),
            msg.sender,
            sig
        );
        // UTH2 queda aquí — owner lo retira con withdrawUTH2()

        // Actualizar expiración VIP
        uint256 start = vipExpire[msg.sender] > block.timestamp
            ? vipExpire[msg.sender]
            : block.timestamp;
        vipExpire[msg.sender] = start + vipDuration * months_;

        // Registrar como holder de rewards (solo en la primera compra)
        if (holderShares[msg.sender] == 0) {
            _updatePool();
            holderShares[msg.sender] = 1;
            totalHolderShares += 1;
            rewardDebt[msg.sender] = rewardPerShare;
        }
    }

    // ── Claim H2O rewards ─────────────────────────────────────────────────

    /**
     * @notice Reclamar H2O acumulado del pool de rewards VIP.
     *         Las recompensas se acumulan por segundo — se puede reclamar 24/7.
     */
    function claimOwnerVip() external {
        _updatePool();

        uint256 share = holderShares[msg.sender];
        require(share > 0, "not a VIP holder");

        uint256 pending = share * (rewardPerShare - rewardDebt[msg.sender]) / SCALE;
        require(pending > 0, "nothing to claim");

        rewardDebt[msg.sender] = rewardPerShare;
        IERC20(H2O).transfer(msg.sender, pending);
    }

    // ── View helpers ──────────────────────────────────────────────────────

    function isVIP(address user) external view returns (bool) {
        return vipExpire[user] > block.timestamp;
    }

    // ── Admin ─────────────────────────────────────────────────────────────

    /**
     * @notice Fondear el contrato con H2O para pagar rewards VIP.
     *         Los H2O se distribuyen linealmente en 365 días.
     *         Solo el owner puede llamar esto.
     * @param amount  Cantidad de H2O (18 decimales) a depositar
     */
    function depositRewards(uint256 amount) external onlyOwner {
        IERC20(H2O).transferFrom(msg.sender, address(this), amount);
        _updatePool();
        rewardRate    = amount / 365 days;
        lastUpdate    = block.timestamp;
        periodFinish  = block.timestamp + 365 days;
    }

    /**
     * @notice Retirar UTH2 acumulado de las suscripciones VIP.
     * @param amount  Cantidad a retirar (0 = retirar todo)
     */
    function withdrawUTH2(uint256 amount) external onlyOwner {
        if (amount == 0) {
            amount = IERC20(UTH2).balanceOf(address(this));
        }
        require(amount > 0, "no UTH2");
        IERC20(UTH2).transfer(owner, amount);
    }

    /**
     * @notice Cambiar el precio de la suscripción VIP en UTH2.
     * @param newPrice  Precio por mes en UTH2 (18 decimales)
     */
    function setVipPrice(uint256 newPrice) external onlyOwner {
        require(newPrice > 0, "price > 0");
        vipPrice = newPrice;
    }

    function setOwner(address newOwner) external onlyOwner {
        require(newOwner != address(0), "zero address");
        owner = newOwner;
    }

    /// @notice Recuperar cualquier token enviado al contrato por error.
    function rescueToken(address token, uint256 amount) external onlyOwner {
        IERC20(token).transfer(owner, amount);
    }
}

contracts/H2OVIPSubscription.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "./IPermit2.sol";

interface IERC20 {
    function transfer(address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
}

interface IH2OStaking {
    function buyVIP(uint256 months_) external;
    function claimOwnerVip() external;
    function vipPrice() external view returns (uint256);
    function ownerShares(address) external view returns (uint256);
}

/**
 * @title H2OVIPSubscription
 * @notice Permit2 connector for the H2O staking VIP subscription.
 *
 * Problem it solves
 * -----------------
 * The staking contract's buyVIP() uses ERC20.transferFrom, which requires a
 * prior approve() call. In World App, approve() is unreliable and causes tx
 * failures. This contract bridges the gap:
 *   1. User signs ONE Permit2 message in World App (no approve needed).
 *   2. This contract receives the UTH2 from the user via Permit2.
 *   3. This contract calls staking.buyVIP() using its own pre-approved UTH2
 *      allowance → staking contract gets the UTH2 and gives this contract
 *      an ownerShare in its VIP fee pool.
 *   4. This contract records the subscription for the actual user.
 *
 * Rewards flow (no owner deposits required)
 * ------------------------------------------
 * Every time staking users claim rewards, 5% of the claim fee accumulates in
 * the staking contract's ownerVipPool. This contract has ownerShares there.
 * When a user calls claimOwnerVip() here, this contract:
 *   a) Calls staking.claimOwnerVip() to pull its earned H2O from the pool.
 *   b) Distributes the collected H2O proportionally to VIP holders.
 */
contract H2OVIPSubscription {

    uint256 constant SCALE   = 1e18;
    address constant PERMIT2 = 0x000000000022D473030F116dDEE9F6B43aC78BA3;

    address public immutable UTH2;
    address public immutable H2O;
    address public immutable STAKING;

    address public owner;

    modifier onlyOwner() {
        require(msg.sender == owner, "not owner");
        _;
    }

    constructor(address _uth2, address _h2o, address _staking) {
        UTH2    = _uth2;
        H2O     = _h2o;
        STAKING = _staking;
        owner   = msg.sender;
        // Pre-approve: allow the staking contract to pull UTH2 from this contract.
        // This is what makes staking.buyVIP() work without a user approve().
        IERC20(_uth2).approve(_staking, type(uint256).max);
    }

    // ── VIP subscription tracking ─────────────────────────────────────────

    uint256 public constant vipDuration = 30 days;
    mapping(address => uint256) public vipExpire;

    // ── H2O reward pool for VIP holders ───────────────────────────────────

    mapping(address => uint256) public holderShares;
    uint256 public totalHolderShares;
    uint256 public rewardPerShare;
    mapping(address => uint256) public rewardDebt;

    // ── Read vipPrice from staking (single source of truth) ───────────────

    function vipPrice() public view returns (uint256) {
        return IH2OStaking(STAKING).vipPrice();
    }

    // ── Buy VIP with Permit2 ───────────────────────────────────────────────

    /**
     * @notice Buy or extend VIP subscription using UTH2 via Permit2.
     *         World App handles the signature — NO prior approve() needed.
     *
     * @param months_  Months to purchase (1-12)
     * @param permit   Permit2 struct: { permitted:{token,amount}, nonce, deadline }
     * @param sig      Permit2 signature from World App
     */
    function buyVIPWithPermit2(
        uint256 months_,
        IPermit2.PermitTransferFrom calldata permit,
        bytes calldata sig
    ) external {
        require(months_ > 0 && months_ <= 12, "invalid months");
        uint256 cost = vipPrice() * months_;
        require(permit.permitted.token == UTH2, "wrong token");
        require(permit.permitted.amount >= cost, "amount too low");

        // 1. Pull UTH2 from user to this contract via Permit2 (no approve needed)
        IPermit2(PERMIT2).permitTransferFrom(
            permit,
            IPermit2.SignatureTransferDetails(address(this), cost),
            msg.sender,
            sig
        );

        // 2. Forward UTH2 to the staking contract by calling buyVIP.
        //    The staking contract pulls UTH2 from this contract using the
        //    pre-approved allowance set in the constructor.
        //    As a result, this contract gains +1 ownerShare in staking's VIP pool.
        IH2OStaking(STAKING).buyVIP(months_);

        // 3. Record the actual user's subscription expiry in this contract.
        uint256 start = vipExpire[msg.sender] > block.timestamp
            ? vipExpire[msg.sender]
            : block.timestamp;
        vipExpire[msg.sender] = start + vipDuration * months_;

        // 4. Register user as a reward holder (first purchase only).
        //    Pull any pending H2O from staking first so current holders get it,
        //    then snapshot rewardPerShare for the new holder.
        if (holderShares[msg.sender] == 0) {
            _pullFromStaking();
            holderShares[msg.sender] = 1;
            totalHolderShares += 1;
            rewardDebt[msg.sender] = rewardPerShare;
        }
    }

    // ── Collect H2O from staking and distribute to VIP holders ───────────

    /**
     * @dev Calls claimOwnerVip on the staking contract to collect this
     *      contract's share of the H2O fee pool, then updates rewardPerShare.
     */
    function _pullFromStaking() internal {
        if (IH2OStaking(STAKING).ownerShares(address(this)) == 0) return;
        uint256 before = IERC20(H2O).balanceOf(address(this));
        // claimOwnerVip may revert if pending == 0, so we use try/catch
        try IH2OStaking(STAKING).claimOwnerVip() {} catch {}
        uint256 gained = IERC20(H2O).balanceOf(address(this));
        if (gained > before && totalHolderShares > 0) {
            rewardPerShare += (gained - before) * SCALE / totalHolderShares;
        }
    }

    /**
     * @notice Public trigger — anyone can call to push the latest staking
     *         rewards into the VIP pool (e.g. before checking pendingReward).
     */
    function pullFromStaking() external {
        _pullFromStaking();
    }

    // ── Claim H2O rewards ─────────────────────────────────────────────────

    /**
     * @notice Claim your accumulated H2O rewards from the VIP pool.
     *         Commissions accumulate automatically as staking users claim;
     *         you can claim here whenever you want.
     */
    function claimOwnerVip() external {
        _pullFromStaking();

        uint256 share = holderShares[msg.sender];
        require(share > 0, "not a VIP holder");

        uint256 pending = share * (rewardPerShare - rewardDebt[msg.sender]) / SCALE;
        require(pending > 0, "nothing to claim");

        rewardDebt[msg.sender] = rewardPerShare;
        IERC20(H2O).transfer(msg.sender, pending);
    }

    // ── View helpers ──────────────────────────────────────────────────────

    function pendingReward(address user) external view returns (uint256) {
        uint256 share = holderShares[user];
        if (share == 0) return 0;
        return share * (rewardPerShare - rewardDebt[user]) / SCALE;
    }

    function isVIP(address user) external view returns (bool) {
        return vipExpire[user] > block.timestamp;
    }

    // ── Admin ─────────────────────────────────────────────────────────────

    function setOwner(address newOwner) external onlyOwner {
        owner = newOwner;
    }

    /// @notice Safety: recover any tokens sent to this contract by mistake.
    function rescueToken(address token, uint256 amount) external onlyOwner {
        IERC20(token).transfer(owner, amount);
    }
}

