contracts/MiningUTH2.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "./IPermit2.sol";

interface IERC20 {
    function transfer(address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

/**
 * @title MiningUTH2
 * @notice H2O mining contract — users buy packages (priced in UTH2) to permanently mine H2O.
 *         - 7 packages, each with a UTH2 price and H2O daily yield
 *         - Permanent mining: buy once, mine forever
 *         - Stack packages to increase mining power
 *         - Package payments go equally to 2 owners
 *         - Permit2 for World App compatibility
 *         - 2 configurable owners
 *         - Pause and emergency withdraw
 */
contract MiningUTH2 {
    // ── Constants ───────────────────────────────────────────────────────────────
    address public constant PERMIT2 = 0x000000000022D473030F116dDEE9F6B43aC78BA3;
    uint256 public constant MAX_PACKAGES = 7;
    uint256 public constant SECONDS_PER_DAY = 86400;

    // ── Tokens ───────────────────────────────────────────────────────────────────
    address public immutable UTH2_TOKEN;  // payment token
    address public immutable H2O_TOKEN;   // reward token

    // ── Owners ───────────────────────────────────────────────────────────────────
    address[2] public owners;

    // ── Packages ─────────────────────────────────────────────────────────────────
    struct Package {
        uint256 priceUTH2;        // cost in UTH2 (18 decimals)
        uint256 dailyH2OYield;    // H2O earned per day per unit (18 decimals)
        bool active;
    }
    Package[7] public packages;

    // ── User Mining State ────────────────────────────────────────────────────────
    struct UserPackage {
        uint256 units;            // number of times this package was purchased
        uint256 lastClaimTime;    // last time rewards were claimed
        uint256 pendingRewards;   // unclaimed rewards
    }
    mapping(address => UserPackage[7]) public userPackages;

    // ── State ────────────────────────────────────────────────────────────────────
    bool public paused;

    // ── Events ───────────────────────────────────────────────────────────────────
    event PackagePurchased(address indexed user, uint256 indexed packageId, uint256 units, uint256 totalPaid);
    event RewardsClaimed(address indexed user, uint256 amount);
    event PackageConfigured(uint256 indexed packageId, uint256 price, uint256 dailyYield);
    event OwnerChanged(uint256 indexed index, address indexed newOwner);
    event Paused(address indexed by);
    event Unpaused(address indexed by);
    event EmergencyWithdraw(address indexed token, address indexed to, uint256 amount);

    // ── Modifiers ─────────────────────────────────────────────────────────────────
    modifier onlyOwner() {
        require(msg.sender == owners[0] || msg.sender == owners[1], "Not owner");
        _;
    }

    modifier whenNotPaused() {
        require(!paused, "Paused");
        _;
    }

    // ── Constructor ───────────────────────────────────────────────────────────────
    constructor(address uth2Token, address h2oToken, address owner1, address owner2) {
        require(uth2Token != address(0) && h2oToken != address(0), "Zero token");
        require(owner1 != address(0), "Zero owner");
        UTH2_TOKEN = uth2Token;
        H2O_TOKEN = h2oToken;
        owners[0] = owner1;
        owners[1] = owner2 != address(0) ? owner2 : owner1;

        // Default packages (owner can update)
        _initPackage(0, 10e18,  10e18);   // 10 UTH2 → 10 H2O/day
        _initPackage(1, 25e18,  28e18);   // 25 UTH2 → 28 H2O/day
        _initPackage(2, 50e18,  60e18);   // 50 UTH2 → 60 H2O/day
        _initPackage(3, 100e18, 130e18);  // 100 UTH2 → 130 H2O/day
        _initPackage(4, 250e18, 350e18);  // 250 UTH2 → 350 H2O/day
        _initPackage(5, 500e18, 750e18);  // 500 UTH2 → 750 H2O/day
        _initPackage(6, 1000e18,1600e18); // 1000 UTH2 → 1600 H2O/day
    }

    function _initPackage(uint256 id, uint256 price, uint256 daily) internal {
        packages[id] = Package({ priceUTH2: price, dailyH2OYield: daily, active: true });
    }

    // ── Internal helpers ──────────────────────────────────────────────────────────

    function _pendingForPackage(address user, uint256 pkgId) internal view returns (uint256) {
        UserPackage storage up = userPackages[user][pkgId];
        if (up.units == 0) return up.pendingRewards;
        uint256 elapsed = block.timestamp - up.lastClaimTime;
        uint256 earned = up.units * packages[pkgId].dailyH2OYield * elapsed / SECONDS_PER_DAY;
        return up.pendingRewards + earned;
    }

    function _totalPending(address user) internal view returns (uint256 total) {
        for (uint256 i = 0; i < MAX_PACKAGES; i++) {
            total += _pendingForPackage(user, i);
        }
    }

    function _updateUserPackage(address user, uint256 pkgId) internal {
        UserPackage storage up = userPackages[user][pkgId];
        if (up.lastClaimTime > 0 && up.units > 0) {
            up.pendingRewards = _pendingForPackage(user, pkgId);
        }
        up.lastClaimTime = block.timestamp;
    }

    function _receiveViaPermit2(
        IPermit2.PermitTransferFrom calldata permit,
        bytes calldata signature,
        uint256 amount,
        address expectedToken
    ) internal {
        require(permit.permitted.token == expectedToken, "Wrong token");
        IPermit2(PERMIT2).permitTransferFrom(
            permit,
            IPermit2.SignatureTransferDetails({ to: address(this), requestedAmount: amount }),
            msg.sender,
            signature
        );
    }

    // ── User Functions ────────────────────────────────────────────────────────────

    /// @notice Buy mining package(s) via Permit2 (UTH2 payment)
    function buyPackage(
        uint256 packageId,
        uint256 units,
        IPermit2.PermitTransferFrom calldata permit,
        bytes calldata signature
    ) external whenNotPaused {
        require(packageId < MAX_PACKAGES, "Invalid package");
        require(units > 0, "Zero units");
        Package storage pkg = packages[packageId];
        require(pkg.active, "Package inactive");

        uint256 totalCost = pkg.priceUTH2 * units;
        require(permit.permitted.amount >= totalCost, "Insufficient permit amount");

        _receiveViaPermit2(permit, signature, totalCost, UTH2_TOKEN);

        // Split payment equally to owners
        uint256 half = totalCost / 2;
        IERC20(UTH2_TOKEN).transfer(owners[0], half);
        IERC20(UTH2_TOKEN).transfer(owners[1], totalCost - half);

        // Update user mining state (checkpoint rewards before adding units)
        _updateUserPackage(msg.sender, packageId);
        userPackages[msg.sender][packageId].units += units;
        if (userPackages[msg.sender][packageId].lastClaimTime == 0) {
            userPackages[msg.sender][packageId].lastClaimTime = block.timestamp;
        }

        emit PackagePurchased(msg.sender, packageId, units, totalCost);
    }

    /// @notice Claim all accumulated H2O rewards
    function claimRewards() external whenNotPaused {
        uint256 total = 0;
        for (uint256 i = 0; i < MAX_PACKAGES; i++) {
            UserPackage storage up = userPackages[msg.sender][i];
            if (up.units > 0 || up.pendingRewards > 0) {
                uint256 earned = _pendingForPackage(msg.sender, i);
                up.pendingRewards = 0;
                up.lastClaimTime = block.timestamp;
                total += earned;
            }
        }
        require(total > 0, "No rewards");
        require(IERC20(H2O_TOKEN).balanceOf(address(this)) >= total, "Insufficient H2O reserve");
        IERC20(H2O_TOKEN).transfer(msg.sender, total);
        emit RewardsClaimed(msg.sender, total);
    }

    // ── Views ──────────────────────────────────────────────────────────────────────

    function pendingRewards(address user) external view returns (uint256) {
        return _totalPending(user);
    }

    function pendingPerPackage(address user) external view returns (uint256[7] memory result) {
        for (uint256 i = 0; i < MAX_PACKAGES; i++) {
            result[i] = _pendingForPackage(user, i);
        }
    }

    function getUserPackages(address user) external view returns (UserPackage[7] memory) {
        return userPackages[user];
    }

    function getAllPackages() external view returns (Package[7] memory) {
        return packages;
    }

    /// @notice Daily yield for user across all packages
    function userDailyYield(address user) external view returns (uint256 daily) {
        for (uint256 i = 0; i < MAX_PACKAGES; i++) {
            daily += userPackages[user][i].units * packages[i].dailyH2OYield;
        }
    }

    // ── Owner Functions ────────────────────────────────────────────────────────────

    function setPackage(uint256 id, uint256 priceUTH2, uint256 dailyYield, bool active) external onlyOwner {
        require(id < MAX_PACKAGES, "Invalid id");
        packages[id] = Package({ priceUTH2: priceUTH2, dailyH2OYield: dailyYield, active: active });
        emit PackageConfigured(id, priceUTH2, dailyYield);
    }

    function setOwner(uint256 index, address addr) external onlyOwner {
        require(index < 2, "Invalid index");
        require(addr != address(0), "Zero address");
        owners[index] = addr;
        emit OwnerChanged(index, addr);
    }

    function pause() external onlyOwner { paused = true; emit Paused(msg.sender); }
    function unpause() external onlyOwner { paused = false; emit Unpaused(msg.sender); }

    function emergencyWithdraw(address token, uint256 amount, address to) external onlyOwner {
        require(to != address(0), "Zero to");
        IERC20(token).transfer(to, amount);
        emit EmergencyWithdraw(token, to, amount);
    }
}

contracts/MiningWLD.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "./IPermit2.sol";

interface IERC20 {
    function transfer(address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

/**
 * @title MiningWLD
 * @notice Multi-reward mining contract — users buy packages (priced in WLD).
 *         Each package has a different reward token:
 *           0 → H2O   1 → FIRE   2 → BTCH2O   3 → WLD   4 → wARS   5 → wCOP   6 → UTH2
 *         - Permanent mining: buy once, mine forever
 *         - Stack packages to increase power
 *         - Package payments go equally to 2 owners
 *         - Permit2 for World App compatibility
 *         - 2 configurable owners
 *         - Pause and emergency withdraw
 */
contract MiningWLD {
    // ── Constants ───────────────────────────────────────────────────────────────
    address public constant PERMIT2 = 0x000000000022D473030F116dDEE9F6B43aC78BA3;
    uint256 public constant MAX_PACKAGES = 7;
    uint256 public constant SECONDS_PER_DAY = 86400;

    // ── Tokens ───────────────────────────────────────────────────────────────────
    address public immutable WLD_TOKEN;   // payment token
    address[7] public rewardTokens;       // one reward token per package

    // ── Owners ───────────────────────────────────────────────────────────────────
    address[2] public owners;

    // ── Packages ─────────────────────────────────────────────────────────────────
    struct Package {
        uint256 priceWLD;          // cost in WLD (18 decimals)
        uint256 dailyRewardYield;  // reward token earned per day per unit (18 decimals)
        bool active;
    }
    Package[7] public packages;

    // ── User Mining State ────────────────────────────────────────────────────────
    struct UserPackage {
        uint256 units;
        uint256 lastClaimTime;
        uint256 pendingRewards;
    }
    mapping(address => UserPackage[7]) public userPackages;

    // ── State ────────────────────────────────────────────────────────────────────
    bool public paused;

    // ── Events ───────────────────────────────────────────────────────────────────
    event PackagePurchased(address indexed user, uint256 indexed packageId, uint256 units, uint256 totalPaid);
    event RewardsClaimed(address indexed user, uint256 indexed packageId, uint256 amount, address rewardToken);
    event PackageConfigured(uint256 indexed packageId, uint256 price, uint256 dailyYield);
    event OwnerChanged(uint256 indexed index, address indexed newOwner);
    event Paused(address indexed by);
    event Unpaused(address indexed by);
    event EmergencyWithdraw(address indexed token, address indexed to, uint256 amount);

    // ── Modifiers ─────────────────────────────────────────────────────────────────
    modifier onlyOwner() {
        require(msg.sender == owners[0] || msg.sender == owners[1], "Not owner");
        _;
    }

    modifier whenNotPaused() {
        require(!paused, "Paused");
        _;
    }

    // ── Constructor ───────────────────────────────────────────────────────────────
    constructor(
        address wldToken,
        address h2oToken,
        address fireToken,
        address btch2oToken,
        address warsToken,
        address wcopToken,
        address uth2Token,
        address owner1,
        address owner2
    ) {
        require(wldToken != address(0), "Zero WLD");
        require(owner1 != address(0), "Zero owner");
        WLD_TOKEN = wldToken;

        // Reward tokens per package
        rewardTokens[0] = h2oToken;
        rewardTokens[1] = fireToken;
        rewardTokens[2] = btch2oToken;
        rewardTokens[3] = wldToken;   // Package 4 rewards in WLD
        rewardTokens[4] = warsToken;
        rewardTokens[5] = wcopToken;
        rewardTokens[6] = uth2Token;

        owners[0] = owner1;
        owners[1] = owner2 != address(0) ? owner2 : owner1;

        // Default packages
        _initPackage(0, 5e18,   10e18);   // 5 WLD  → 10 H2O/day
        _initPackage(1, 10e18,  8e18);    // 10 WLD → 8 FIRE/day
        _initPackage(2, 15e18,  5e18);    // 15 WLD → 5 BTCH2O/day
        _initPackage(3, 20e18,  6e18);    // 20 WLD → 6 WLD/day
        _initPackage(4, 30e18,  100e18);  // 30 WLD → 100 wARS/day
        _initPackage(5, 25e18,  80e18);   // 25 WLD → 80 wCOP/day
        _initPackage(6, 50e18,  12e18);   // 50 WLD → 12 UTH2/day
    }

    function _initPackage(uint256 id, uint256 price, uint256 daily) internal {
        packages[id] = Package({ priceWLD: price, dailyRewardYield: daily, active: true });
    }

    // ── Internal helpers ──────────────────────────────────────────────────────────

    function _pendingForPackage(address user, uint256 pkgId) internal view returns (uint256) {
        UserPackage storage up = userPackages[user][pkgId];
        if (up.units == 0) return up.pendingRewards;
        uint256 elapsed = block.timestamp - up.lastClaimTime;
        uint256 earned = up.units * packages[pkgId].dailyRewardYield * elapsed / SECONDS_PER_DAY;
        return up.pendingRewards + earned;
    }

    function _receiveViaPermit2(
        IPermit2.PermitTransferFrom calldata permit,
        bytes calldata signature,
        uint256 amount
    ) internal {
        require(permit.permitted.token == WLD_TOKEN, "Wrong token");
        IPermit2(PERMIT2).permitTransferFrom(
            permit,
            IPermit2.SignatureTransferDetails({ to: address(this), requestedAmount: amount }),
            msg.sender,
            signature
        );
    }

    // ── User Functions ────────────────────────────────────────────────────────────

    /// @notice Buy mining package(s) via Permit2 (WLD payment)
    function buyPackage(
        uint256 packageId,
        uint256 units,
        IPermit2.PermitTransferFrom calldata permit,
        bytes calldata signature
    ) external whenNotPaused {
        require(packageId < MAX_PACKAGES, "Invalid package");
        require(units > 0, "Zero units");
        Package storage pkg = packages[packageId];
        require(pkg.active, "Package inactive");

        uint256 totalCost = pkg.priceWLD * units;
        require(permit.permitted.amount >= totalCost, "Insufficient permit amount");

        _receiveViaPermit2(permit, signature, totalCost);

        // Split payment equally to owners
        uint256 half = totalCost / 2;
        IERC20(WLD_TOKEN).transfer(owners[0], half);
        IERC20(WLD_TOKEN).transfer(owners[1], totalCost - half);

        // Checkpoint rewards before adding units
        UserPackage storage up = userPackages[msg.sender][packageId];
        if (up.lastClaimTime > 0 && up.units > 0) {
            up.pendingRewards = _pendingForPackage(msg.sender, packageId);
        }
        up.lastClaimTime = block.timestamp;
        up.units += units;

        emit PackagePurchased(msg.sender, packageId, units, totalCost);
    }

    /// @notice Claim rewards for a specific package
    function claimPackageRewards(uint256 packageId) external whenNotPaused {
        require(packageId < MAX_PACKAGES, "Invalid package");
        UserPackage storage up = userPackages[msg.sender][packageId];
        require(up.units > 0 || up.pendingRewards > 0, "No mining power");

        uint256 earned = _pendingForPackage(msg.sender, packageId);
        require(earned > 0, "No rewards");

        up.pendingRewards = 0;
        up.lastClaimTime = block.timestamp;

        address rewardToken = rewardTokens[packageId];
        require(IERC20(rewardToken).balanceOf(address(this)) >= earned, "Insufficient reserve");
        IERC20(rewardToken).transfer(msg.sender, earned);

        emit RewardsClaimed(msg.sender, packageId, earned, rewardToken);
    }

    /// @notice Claim all rewards across all packages
    function claimAllRewards() external whenNotPaused {
        for (uint256 i = 0; i < MAX_PACKAGES; i++) {
            UserPackage storage up = userPackages[msg.sender][i];
            if (up.units == 0 && up.pendingRewards == 0) continue;

            uint256 earned = _pendingForPackage(msg.sender, i);
            if (earned == 0) continue;

            up.pendingRewards = 0;
            up.lastClaimTime = block.timestamp;

            address rewardToken = rewardTokens[i];
            if (IERC20(rewardToken).balanceOf(address(this)) >= earned) {
                IERC20(rewardToken).transfer(msg.sender, earned);
                emit RewardsClaimed(msg.sender, i, earned, rewardToken);
            }
        }
    }

    // ── Views ──────────────────────────────────────────────────────────────────────

    function pendingPerPackage(address user) external view returns (uint256[7] memory result) {
        for (uint256 i = 0; i < MAX_PACKAGES; i++) {
            result[i] = _pendingForPackage(user, i);
        }
    }

    function getUserPackages(address user) external view returns (UserPackage[7] memory) {
        return userPackages[user];
    }

    function getAllPackages() external view returns (Package[7] memory) {
        return packages;
    }

    function getRewardTokens() external view returns (address[7] memory) {
        return rewardTokens;
    }

    /// @notice Daily yield per package for user
    function userDailyYield(address user) external view returns (uint256[7] memory daily) {
        for (uint256 i = 0; i < MAX_PACKAGES; i++) {
            daily[i] = userPackages[user][i].units * packages[i].dailyRewardYield;
        }
    }

    // ── Owner Functions ────────────────────────────────────────────────────────────

    function setPackage(uint256 id, uint256 priceWLD, uint256 dailyYield, bool active) external onlyOwner {
        require(id < MAX_PACKAGES, "Invalid id");
        packages[id] = Package({ priceWLD: priceWLD, dailyRewardYield: dailyYield, active: active });
        emit PackageConfigured(id, priceWLD, dailyYield);
    }

    function setOwner(uint256 index, address addr) external onlyOwner {
        require(index < 2, "Invalid index");
        require(addr != address(0), "Zero address");
        owners[index] = addr;
        emit OwnerChanged(index, addr);
    }

    function pause() external onlyOwner { paused = true; emit Paused(msg.sender); }
    function unpause() external onlyOwner { paused = false; emit Unpaused(msg.sender); }

    function emergencyWithdraw(address token, uint256 amount, address to) external onlyOwner {
        require(to != address(0), "Zero to");
        IERC20(token).transfer(to, amount);
        emit EmergencyWithdraw(token, to, amount);
    }
}

contracts/NewAcuaSwapRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * @title NewAcuaSwapRouter
 * @notice Universal swap router for Acua 2.0 that aggregates Uniswap v2, v3, and v4.
 *
 * Features:
 *   - No swap amount limits
 *   - Configurable protocol fee (bps) per route, forwarded to FundManager
 *   - Supports Permit2 for input token approval (World App compatible)
 *   - Owner-configurable router addresses (upgradeable without redeployment)
 *   - Multi-hop via v3 encoded path or v2 path array
 *   - V4 swap via PoolManager (Uniswap v4) with custom hook support
 *   - Connect / disconnect contracts (fee collector, referral, etc.)
 *   - Add / remove owners
 *   - Emergency pause
 */

interface IERC20Swap {
    function approve(address spender, uint256 amount) external returns (bool);
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

interface IPermit2Swap {
    struct TokenPermissions { address token; uint256 amount; }
    struct PermitTransferFrom { TokenPermissions permitted; uint256 nonce; uint256 deadline; }
    struct SignatureTransferDetails { address to; uint256 requestedAmount; }
    function permitTransferFrom(
        PermitTransferFrom calldata permit,
        SignatureTransferDetails calldata transferDetails,
        address owner,
        bytes calldata signature
    ) external;
}

// ─── Uniswap V2 ───────────────────────────────────────────────────────────────
interface IUniswapV2Router {
    function swapExactTokensForTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external returns (uint256[] memory amounts);

    function getAmountsOut(uint256 amountIn, address[] calldata path)
        external view returns (uint256[] memory amounts);
}

// ─── Uniswap V3 ───────────────────────────────────────────────────────────────
interface ISwapRouter03 {
    struct ExactInputParams {
        bytes   path;
        address recipient;
        uint256 amountIn;
        uint256 amountOutMinimum;
    }
    function exactInput(ExactInputParams calldata params) external payable returns (uint256 amountOut);

    struct ExactInputSingleParams {
        address tokenIn;
        address tokenOut;
        uint24  fee;
        address recipient;
        uint256 amountIn;
        uint256 amountOutMinimum;
        uint160 sqrtPriceLimitX96;
    }
    function exactInputSingle(ExactInputSingleParams calldata params) external payable returns (uint256 amountOut);
}

// ─── Uniswap V4 (PoolManager) ─────────────────────────────────────────────────
interface IPoolManager {
    struct PoolKey {
        address currency0;
        address currency1;
        uint24  fee;
        int24   tickSpacing;
        address hooks;
    }
    struct SwapParams {
        bool    zeroForOne;
        int256  amountSpecified;
        uint160 sqrtPriceLimitX96;
    }
    function swap(PoolKey calldata key, SwapParams calldata params, bytes calldata hookData)
        external returns (int256 delta0, int256 delta1);
}

contract NewAcuaSwapRouter {

    // ─── Constants ────────────────────────────────────────────────────────────
    uint256 public constant MAX_BPS       = 10_000;
    uint256 public constant MAX_FEE_BPS   = 500;     // 5% hard cap on protocol fee
    uint256 public constant MAX_OWNERS    = 5;
    uint256 public constant MAX_CONTRACTS = 10;

    address public constant PERMIT2 = 0x000000000022D473030F116dDEE9F6B43aC78BA3;

    // ─── Routers (configurable) ───────────────────────────────────────────────
    address public routerV2;    // Uniswap V2 (or SushiSwap / compatible)
    address public routerV3;    // Uniswap V3 SwapRouter02
    address public poolManagerV4; // Uniswap V4 PoolManager

    // ─── Protocol fee ─────────────────────────────────────────────────────────
    /// Basis points charged on every swap, forwarded to feeReceiver.
    uint256 public protocolFeeBps = 30;  // 0.3% default

    /// Where protocol fees are sent (FundManager or direct wallet).
    address public feeReceiver;

    // ─── Owner & Contract management ─────────────────────────────────────────
    address[] public owners;
    address[] public connectedContracts;
    bool public paused;

    // ─── Events ───────────────────────────────────────────────────────────────
    event SwapV2Executed(address indexed user, address indexed tokenIn, address indexed tokenOut, uint256 amountIn, uint256 amountOut, uint256 fee);
    event SwapV3Executed(address indexed user, uint256 amountIn, uint256 amountOut, uint256 fee);
    event SwapV4Executed(address indexed user, address tokenIn, address tokenOut, int256 delta0, int256 delta1);
    event RoutersUpdated(address v2, address v3, address v4);
    event FeeUpdated(uint256 bps, address receiver);
    event ContractConnected(address indexed addr);
    event ContractDisconnected(address indexed addr);
    event OwnerAdded(address indexed owner);
    event OwnerRemoved(address indexed owner);
    event Paused(bool paused);

    // ─── Modifiers ────────────────────────────────────────────────────────────
    modifier onlyOwner() {
        require(_isOwner(msg.sender), "AcuaSwap: not owner");
        _;
    }
    modifier whenNotPaused() {
        require(!paused, "AcuaSwap: paused");
        _;
    }

    // ─── Constructor ──────────────────────────────────────────────────────────
    constructor(
        address _initialOwner,
        address _routerV2,
        address _routerV3,
        address _poolManagerV4,
        address _feeReceiver
    ) {
        require(_initialOwner != address(0), "zero owner");
        owners.push(_initialOwner);
        routerV2       = _routerV2;
        routerV3       = _routerV3;
        poolManagerV4  = _poolManagerV4;
        feeReceiver    = _feeReceiver != address(0) ? _feeReceiver : _initialOwner;
    }

    // ─── V2 Swap ──────────────────────────────────────────────────────────────

    /**
     * @notice Swap exact tokens via Uniswap V2 (any V2-compatible DEX).
     * @param amountIn     Gross input amount (before protocol fee).
     * @param amountOutMin Minimum output (slippage protection, caller sets).
     * @param path         Token path [tokenIn, ..., tokenOut].
     * @param deadline     Unix timestamp deadline.
     */
    function swapV2(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        uint256 deadline
    ) external whenNotPaused returns (uint256 amountOut) {
        require(routerV2 != address(0), "V2 router not set");
        require(path.length >= 2, "invalid path");
        require(amountIn > 0, "zero amount");

        address tokenIn  = path[0];
        address tokenOut = path[path.length - 1];

        IERC20Swap(tokenIn).transferFrom(msg.sender, address(this), amountIn);

        uint256 fee = _collectFee(tokenIn, amountIn);
        uint256 netIn = amountIn - fee;

        IERC20Swap(tokenIn).approve(routerV2, netIn);

        uint256[] memory amounts = IUniswapV2Router(routerV2).swapExactTokensForTokens(
            netIn, amountOutMin, path, msg.sender, deadline
        );
        amountOut = amounts[amounts.length - 1];

        emit SwapV2Executed(msg.sender, tokenIn, tokenOut, amountIn, amountOut, fee);
    }

    /// @notice V2 swap with Permit2 input approval.
    function swapV2Permit2(
        IPermit2Swap.PermitTransferFrom calldata permit,
        bytes calldata signature,
        uint256 amountOutMin,
        address[] calldata path,
        uint256 deadline
    ) external whenNotPaused returns (uint256 amountOut) {
        require(routerV2 != address(0), "V2 router not set");
        require(path.length >= 2, "invalid path");

        uint256 amountIn = permit.permitted.amount;
        address tokenIn  = permit.permitted.token;
        address tokenOut = path[path.length - 1];

        IPermit2Swap(PERMIT2).permitTransferFrom(
            permit,
            IPermit2Swap.SignatureTransferDetails({ to: address(this), requestedAmount: amountIn }),
            msg.sender,
            signature
        );

        uint256 fee = _collectFee(tokenIn, amountIn);
        uint256 netIn = amountIn - fee;

        IERC20Swap(tokenIn).approve(routerV2, netIn);
        uint256[] memory amounts = IUniswapV2Router(routerV2).swapExactTokensForTokens(
            netIn, amountOutMin, path, msg.sender, deadline
        );
        amountOut = amounts[amounts.length - 1];

        emit SwapV2Executed(msg.sender, tokenIn, tokenOut, amountIn, amountOut, fee);
    }

    // ─── V3 Swap ──────────────────────────────────────────────────────────────

    /**
     * @notice Swap via Uniswap V3 using an encoded multi-hop path.
     * @param tokenIn     Input token.
     * @param encodedPath ABI-encoded V3 path (tokenIn · fee · tokenMid · fee · tokenOut …).
     * @param amountIn    Gross input amount.
     * @param amountOutMin Slippage protection.
     */
    function swapV3(
        address tokenIn,
        bytes calldata encodedPath,
        uint256 amountIn,
        uint256 amountOutMin
    ) external whenNotPaused returns (uint256 amountOut) {
        require(routerV3 != address(0), "V3 router not set");
        require(amountIn > 0, "zero amount");

        IERC20Swap(tokenIn).transferFrom(msg.sender, address(this), amountIn);

        uint256 fee = _collectFee(tokenIn, amountIn);
        uint256 netIn = amountIn - fee;

        IERC20Swap(tokenIn).approve(routerV3, netIn);
        amountOut = ISwapRouter03(routerV3).exactInput(
            ISwapRouter03.ExactInputParams({
                path:             encodedPath,
                recipient:        msg.sender,
                amountIn:         netIn,
                amountOutMinimum: amountOutMin
            })
        );

        emit SwapV3Executed(msg.sender, amountIn, amountOut, fee);
    }

    /// @notice Single-hop V3 swap (simpler interface).
    function swapV3Single(
        address tokenIn,
        address tokenOut,
        uint24  poolFee,
        uint256 amountIn,
        uint256 amountOutMin
    ) external whenNotPaused returns (uint256 amountOut) {
        require(routerV3 != address(0), "V3 router not set");
        require(amountIn > 0, "zero amount");

        IERC20Swap(tokenIn).transferFrom(msg.sender, address(this), amountIn);
        uint256 fee = _collectFee(tokenIn, amountIn);
        uint256 netIn = amountIn - fee;

        IERC20Swap(tokenIn).approve(routerV3, netIn);
        amountOut = ISwapRouter03(routerV3).exactInputSingle(
            ISwapRouter03.ExactInputSingleParams({
                tokenIn:           tokenIn,
                tokenOut:          tokenOut,
                fee:               poolFee,
                recipient:         msg.sender,
                amountIn:          netIn,
                amountOutMinimum:  amountOutMin,
                sqrtPriceLimitX96: 0
            })
        );

        emit SwapV3Executed(msg.sender, amountIn, amountOut, fee);
    }

    // ─── V4 Swap ──────────────────────────────────────────────────────────────

    /**
     * @notice Swap via Uniswap V4 PoolManager.
     * @dev Caller provides a fully-formed PoolKey and SwapParams.
     *      The actual settlement / currency router wrapping is handled by the
     *      Universal Router or a custom unlock callback (not included here —
     *      integrate via a separate UnlockCallback contract if needed).
     *      This is the raw hook into the V4 pool.
     */
    function swapV4(
        IPoolManager.PoolKey calldata key,
        IPoolManager.SwapParams calldata params,
        bytes calldata hookData,
        uint256 amountIn
    ) external whenNotPaused returns (int256 delta0, int256 delta1) {
        require(poolManagerV4 != address(0), "V4 pool manager not set");
        require(amountIn > 0, "zero amount");

        address tokenIn = params.zeroForOne ? key.currency0 : key.currency1;
        IERC20Swap(tokenIn).transferFrom(msg.sender, address(this), amountIn);
        uint256 fee = _collectFee(tokenIn, amountIn);

        // Approve pool manager
        IERC20Swap(tokenIn).approve(poolManagerV4, amountIn - fee);

        (delta0, delta1) = IPoolManager(poolManagerV4).swap(key, params, hookData);

        emit SwapV4Executed(msg.sender, tokenIn, params.zeroForOne ? key.currency1 : key.currency0, delta0, delta1);
    }

    // ─── Fee ──────────────────────────────────────────────────────────────────

    function _collectFee(address tokenIn, uint256 amountIn) internal returns (uint256 fee) {
        if (protocolFeeBps == 0 || feeReceiver == address(0)) return 0;
        fee = (amountIn * protocolFeeBps) / MAX_BPS;
        if (fee > 0) {
            IERC20Swap(tokenIn).transfer(feeReceiver, fee);
        }
    }

    // ─── Config ───────────────────────────────────────────────────────────────

    function setRouters(address _v2, address _v3, address _v4) external onlyOwner {
        routerV2      = _v2;
        routerV3      = _v3;
        poolManagerV4 = _v4;
        emit RoutersUpdated(_v2, _v3, _v4);
    }

    function setProtocolFee(uint256 _bps, address _receiver) external onlyOwner {
        require(_bps <= MAX_FEE_BPS, "fee too high");
        protocolFeeBps = _bps;
        feeReceiver    = _receiver;
        emit FeeUpdated(_bps, _receiver);
    }

    // ─── Contract Connections ─────────────────────────────────────────────────

    function connectContract(address contractAddr) external onlyOwner {
        require(contractAddr != address(0), "zero address");
        require(connectedContracts.length < MAX_CONTRACTS, "max contracts");
        connectedContracts.push(contractAddr);
        emit ContractConnected(contractAddr);
    }

    function disconnectContract(uint256 index) external onlyOwner {
        require(index < connectedContracts.length, "out of bounds");
        emit ContractDisconnected(connectedContracts[index]);
        connectedContracts[index] = address(0);
    }

    function getConnectedContracts() external view returns (address[] memory) {
        return connectedContracts;
    }

    // ─── Owner Management ─────────────────────────────────────────────────────

    function addOwner(address newOwner) external onlyOwner {
        require(newOwner != address(0), "zero address");
        require(!_isOwner(newOwner), "already owner");
        require(owners.length < MAX_OWNERS, "max owners");
        owners.push(newOwner);
        emit OwnerAdded(newOwner);
    }

    function removeOwner(address ownerAddr) external onlyOwner {
        require(owners.length > 1, "need at least 1 owner");
        for (uint256 i = 0; i < owners.length; i++) {
            if (owners[i] == ownerAddr) {
                owners[i] = owners[owners.length - 1];
                owners.pop();
                emit OwnerRemoved(ownerAddr);
                return;
            }
        }
        revert("not found");
    }

    function getOwners() external view returns (address[] memory) {
        return owners;
    }

    // ─── Pause / Emergency ────────────────────────────────────────────────────

    function setPaused(bool _paused) external onlyOwner {
        paused = _paused;
        emit Paused(_paused);
    }

    function rescueToken(address _token, address to, uint256 amount) external onlyOwner {
        IERC20Swap(_token).transfer(to, amount);
    }

    // ─── Quote helpers (view) ─────────────────────────────────────────────────

    function quoteV2(uint256 amountIn, address[] calldata path)
        external view returns (uint256 amountOut)
    {
        require(routerV2 != address(0), "V2 router not set");
        uint256 fee = (amountIn * protocolFeeBps) / MAX_BPS;
        uint256[] memory amounts = IUniswapV2Router(routerV2).getAmountsOut(amountIn - fee, path);
        return amounts[amounts.length - 1];
    }

    // ─── Helpers ──────────────────────────────────────────────────────────────

    function _isOwner(address addr) internal view returns (bool) {
        for (uint256 i = 0; i < owners.length; i++) {
            if (owners[i] == addr) return true;
        }
        return false;
    }
}

contracts/NewH2OStaking.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * @title NewH2OStaking v2
 * @notice H2O 2.0 staking con sistema de referidos integrado.
 *
 * Fee de claim: SIEMPRE 15% del bruto
 *   - Con referido:    5% → referrer | 5% → owner | 5% bonus devuelto al usuario → usuario neto 90%
 *   - Sin referido:    15% → owner                                                → usuario neto 85%
 *
 * Fee de depósito: 5% (configurable, cap 20%) → owners
 * Fee de retiro:   5% (configurable, cap 20%) → owners
 *
 * Referidos ilimitados: cada dirección puede referir a N personas sin límite.
 * Cada usuario tiene un solo referrer (se asigna una vez, inmutable).
 */

interface IERC20New {
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

interface IPermit2New {
    struct TokenPermissions { address token; uint256 amount; }
    struct PermitTransferFrom { TokenPermissions permitted; uint256 nonce; uint256 deadline; }
    struct SignatureTransferDetails { address to; uint256 requestedAmount; }
    function permitTransferFrom(
        PermitTransferFrom calldata permit,
        SignatureTransferDetails calldata transferDetails,
        address owner,
        bytes calldata signature
    ) external;
}

contract NewH2OStaking {

    // ─── Global Constants ─────────────────────────────────────────────────
    uint256 public constant MAX_BPS           = 10_000;
    uint256 public constant MAX_FEE_BPS       = 2_000;   // 20% hard cap
    uint256 public constant MAX_OWNERS        = 5;
    uint256 public constant REWARD_DURATION   = 365 days;

    address public constant PERMIT2 = 0x000000000022D473030F116dDEE9F6B43aC78BA3;

    // ─── Referral Constants (hardcoded, not configurable) ─────────────────
    // Claim fee = 15% always
    //   With referrer:    5% referrer + 5% owner + 5% bonus to user → user nets 90%
    //   Without referrer: 15% to owner → user nets 85%
    uint256 public constant claimFeeBps      = 1_500;  // 15% total (for UI compatibility)
    uint256 public constant REF_REFERRER_BPS =   500;  // 5%  → referrer
    uint256 public constant REF_OWNER_BPS    =   500;  // 5%  → owner  (with referrer)
    uint256 public constant REF_BONUS_BPS    =   500;  // 5%  → bonus returned to user
    // Without referrer: full claimFeeBps (15%) → owner

    // ─── Config ───────────────────────────────────────────────────────────
    address public token;

    uint256 public depositFeeBps  = 500;  // 5%
    uint256 public withdrawFeeBps = 500;  // 5%
    uint256 public feeToPoolBps   = 0;    // 0% to pool, 100% to owners (deposit/withdraw fees)

    // ─── Owner Management ─────────────────────────────────────────────────
    address[] public owners;
    bool public paused;

    // ─── Staking State ────────────────────────────────────────────────────
    uint256 public totalStaked;
    uint256 public rewardPool;
    uint256 public rewardRate;
    uint256 public lastUpdateTime;
    uint256 public rewardPerTokenStored;

    mapping(address => uint256) public stakedBalance;
    mapping(address => uint256) public userRewardPerTokenPaid;
    mapping(address => uint256) public rewards;

    // ─── Referral State ───────────────────────────────────────────────────
    mapping(address => address)   public referredBy;       // user → their referrer
    mapping(address => uint256)   public referralCount;    // referrer → # of people they referred
    mapping(address => uint256)   public referralEarnings; // referrer → total H2O earned from refs

    uint256 public totalReferralsPaid;

    // ─── Events ───────────────────────────────────────────────────────────
    event Staked(address indexed user, uint256 net, uint256 fee);
    event Unstaked(address indexed user, uint256 net, uint256 fee);
    event RewardClaimed(address indexed user, uint256 toUser, uint256 toReferrer, uint256 toOwner, address referrer);
    event RewardPoolFunded(address indexed from, uint256 amount);
    event FeeDistributed(uint256 toPool, uint256 toOwners);
    event ReferralRegistered(address indexed user, address indexed referrer);
    event OwnerAdded(address indexed owner);
    event OwnerRemoved(address indexed owner);
    event FeeConfigUpdated(uint256 depositBps, uint256 withdrawBps);
    event Paused(bool paused);

    // ─── Modifiers ────────────────────────────────────────────────────────
    modifier onlyOwner() {
        require(_isOwner(msg.sender), "not owner");
        _;
    }
    modifier whenNotPaused() {
        require(!paused, "paused");
        _;
    }
    modifier updateReward(address account) {
        rewardPerTokenStored = rewardPerToken();
        lastUpdateTime = block.timestamp;
        if (account != address(0)) {
            rewards[account] = earned(account);
            userRewardPerTokenPaid[account] = rewardPerTokenStored;
        }
        _;
    }

    // ─── Constructor ──────────────────────────────────────────────────────
    constructor(address _token, address _initialOwner) {
        require(_token != address(0) && _initialOwner != address(0), "zero address");
        token = _token;
        owners.push(_initialOwner);
        lastUpdateTime = block.timestamp;
    }

    // ─── Reward Math ──────────────────────────────────────────────────────
    function rewardPerToken() public view returns (uint256) {
        if (totalStaked == 0) return rewardPerTokenStored;
        uint256 elapsed = block.timestamp - lastUpdateTime;
        return rewardPerTokenStored + (elapsed * rewardRate * 1e18) / totalStaked;
    }

    function earned(address account) public view returns (uint256) {
        return (stakedBalance[account] * (rewardPerToken() - userRewardPerTokenPaid[account])) / 1e18
            + rewards[account];
    }

    // ─── Referral Registration ─────────────────────────────────────────────
    /**
     * @notice Registra un referrer. Solo se puede hacer UNA VEZ (inmutable).
     * @param referrer La dirección que te invitó. No puede ser cero ni uno mismo.
     */
    function register(address referrer) external {
        require(referredBy[msg.sender] == address(0), "already registered");
        require(referrer != address(0) && referrer != msg.sender, "invalid referrer");
        _registerRef(msg.sender, referrer);
    }

    function _registerRef(address user, address referrer) internal {
        referredBy[user] = referrer;
        referralCount[referrer]++;
        emit ReferralRegistered(user, referrer);
    }

    // ─── Stake via Permit2 (World App) ────────────────────────────────────
    function stake(
        IPermit2New.PermitTransferFrom calldata permit,
        bytes calldata signature
    ) external whenNotPaused updateReward(msg.sender) {
        uint256 amount = permit.permitted.amount;
        require(amount > 0, "zero amount");
        IPermit2New(PERMIT2).permitTransferFrom(
            permit,
            IPermit2New.SignatureTransferDetails({ to: address(this), requestedAmount: amount }),
            msg.sender,
            signature
        );
        _processDeposit(msg.sender, amount);
    }

    /// @notice Stake via Permit2 + registrar referrer en el mismo TX.
    function stake(
        IPermit2New.PermitTransferFrom calldata permit,
        bytes calldata signature,
        address referrer
    ) external whenNotPaused updateReward(msg.sender) {
        uint256 amount = permit.permitted.amount;
        require(amount > 0, "zero amount");
        IPermit2New(PERMIT2).permitTransferFrom(
            permit,
            IPermit2New.SignatureTransferDetails({ to: address(this), requestedAmount: amount }),
            msg.sender,
            signature
        );
        if (referrer != address(0) && referrer != msg.sender && referredBy[msg.sender] == address(0)) {
            _registerRef(msg.sender, referrer);
        }
        _processDeposit(msg.sender, amount);
    }

    /// @notice Stake estándar (aprobación ERC20 directa, sin Permit2).
    function stakeNormal(uint256 amount) external whenNotPaused updateReward(msg.sender) {
        require(amount > 0, "zero amount");
        require(IERC20New(token).transferFrom(msg.sender, address(this), amount), "transfer failed");
        _processDeposit(msg.sender, amount);
    }

    /// @notice Stake estándar + registrar referrer en el mismo TX.
    function stakeNormal(uint256 amount, address referrer) external whenNotPaused updateReward(msg.sender) {
        require(amount > 0, "zero amount");
        require(IERC20New(token).transferFrom(msg.sender, address(this), amount), "transfer failed");
        if (referrer != address(0) && referrer != msg.sender && referredBy[msg.sender] == address(0)) {
            _registerRef(msg.sender, referrer);
        }
        _processDeposit(msg.sender, amount);
    }

    function _processDeposit(address user, uint256 gross) internal {
        uint256 fee = (gross * depositFeeBps) / MAX_BPS;
        uint256 net = gross - fee;
        stakedBalance[user] += net;
        totalStaked += net;
        _distributeDepositWithdrawFee(fee);
        emit Staked(user, net, fee);
    }

    // ─── Unstake ──────────────────────────────────────────────────────────
    function unstake(uint256 amount) external whenNotPaused updateReward(msg.sender) {
        require(amount > 0, "zero amount");
        require(stakedBalance[msg.sender] >= amount, "insufficient stake");

        stakedBalance[msg.sender] -= amount;
        totalStaked -= amount;

        uint256 fee = (amount * withdrawFeeBps) / MAX_BPS;
        uint256 net = amount - fee;
        _distributeDepositWithdrawFee(fee);

        // Auto-claim pending rewards
        uint256 pending = rewards[msg.sender];
        if (pending > 0) {
            rewards[msg.sender] = 0;
            _sendClaimRewards(msg.sender, pending);
        }

        require(IERC20New(token).transfer(msg.sender, net), "transfer failed");
        emit Unstaked(msg.sender, net, fee);
    }

    // ─── Claim ────────────────────────────────────────────────────────────
    /**
     * @notice Reclama recompensas con lógica de referidos integrada.
     *
     * SIEMPRE se descuenta 15% del bruto (claimFeeBps = 1500):
     *   Con referrer:    5% → referrer | 5% → owner | 5% bonus → usuario  → usuario neto 90%
     *   Sin referrer:    15% → owner                                       → usuario neto 85%
     */
    function claimRewards() external whenNotPaused updateReward(msg.sender) {
        uint256 gross = rewards[msg.sender];
        require(gross > 0, "nothing to claim");
        rewards[msg.sender] = 0;
        _sendClaimRewards(msg.sender, gross);
    }

    function _sendClaimRewards(address user, uint256 gross) internal {
        uint256 totalFee = (gross * claimFeeBps) / MAX_BPS; // 15% siempre
        address ref      = referredBy[user];

        uint256 toUser;
        uint256 toOwner;
        uint256 toRef;

        if (ref != address(0)) {
            toRef   = (gross * REF_REFERRER_BPS) / MAX_BPS; // 5% → referrer
            uint256 bonus = (gross * REF_BONUS_BPS) / MAX_BPS; // 5% bonus → usuario
            toOwner = totalFee - toRef - bonus;               // 5% → owner
            toUser  = gross - totalFee + bonus;               // 90%

            if (toRef > 0) {
                IERC20New(token).transfer(ref, toRef);
                referralEarnings[ref] += toRef;
                totalReferralsPaid   += toRef;
            }
        } else {
            toOwner = totalFee;       // 15% → owner
            toUser  = gross - totalFee; // 85%
        }

        // Distribuye la parte del owner entre todos los owners
        if (toOwner > 0 && owners.length > 0) {
            uint256 perOwner = toOwner / owners.length;
            uint256 dust     = toOwner - (perOwner * owners.length);
            for (uint256 i = 0; i < owners.length; i++) {
                if (owners[i] != address(0) && perOwner > 0) {
                    IERC20New(token).transfer(owners[i], perOwner);
                }
            }
            if (dust > 0) { rewardPool += dust; _recalcRewardRate(); }
        }

        if (toUser > 0) IERC20New(token).transfer(user, toUser);
        emit RewardClaimed(user, toUser, toRef, toOwner, ref);
    }

    // ─── Fee Distribution (deposit / withdraw) ────────────────────────────
    function _distributeDepositWithdrawFee(uint256 fee) internal {
        if (fee == 0) return;
        uint256 toPool   = (fee * feeToPoolBps) / MAX_BPS;
        uint256 toOwners = fee - toPool;

        if (toPool > 0) { rewardPool += toPool; _recalcRewardRate(); }

        if (toOwners > 0 && owners.length > 0) {
            uint256 perOwner = toOwners / owners.length;
            uint256 dust     = toOwners - (perOwner * owners.length);
            for (uint256 i = 0; i < owners.length; i++) {
                if (owners[i] != address(0) && perOwner > 0) {
                    IERC20New(token).transfer(owners[i], perOwner);
                }
            }
            if (dust > 0) { rewardPool += dust; _recalcRewardRate(); }
        }

        emit FeeDistributed(toPool, toOwners);
    }

    // ─── Fund Reward Pool ─────────────────────────────────────────────────
    function fundRewardPool(uint256 amount) external whenNotPaused {
        require(amount > 0, "zero amount");
        require(IERC20New(token).transferFrom(msg.sender, address(this), amount), "transfer failed");
        rewardPool += amount;
        _recalcRewardRate();
        emit RewardPoolFunded(msg.sender, amount);
    }

    function fundRewardPoolPermit2(
        IPermit2New.PermitTransferFrom calldata permit,
        bytes calldata signature
    ) external whenNotPaused {
        uint256 amount = permit.permitted.amount;
        require(amount > 0, "zero amount");
        IPermit2New(PERMIT2).permitTransferFrom(
            permit,
            IPermit2New.SignatureTransferDetails({ to: address(this), requestedAmount: amount }),
            msg.sender,
            signature
        );
        rewardPool += amount;
        _recalcRewardRate();
        emit RewardPoolFunded(msg.sender, amount);
    }

    function depositRewards(uint256 amount) external {
        require(amount > 0, "zero amount");
        require(IERC20New(token).transferFrom(msg.sender, address(this), amount), "transfer failed");
        rewardPool += amount;
        _recalcRewardRate();
        emit RewardPoolFunded(msg.sender, amount);
    }

    function _recalcRewardRate() internal updateReward(address(0)) {
        rewardRate = rewardPool / REWARD_DURATION;
        lastUpdateTime = block.timestamp;
    }

    // ─── Fee Config (solo deposit/withdraw) ───────────────────────────────
    function setFees(uint256 _depositBps, uint256 _withdrawBps) external onlyOwner {
        require(_depositBps <= MAX_FEE_BPS && _withdrawBps <= MAX_FEE_BPS, "fee too high");
        depositFeeBps  = _depositBps;
        withdrawFeeBps = _withdrawBps;
        emit FeeConfigUpdated(_depositBps, _withdrawBps);
    }

    function setFeeDistribution(uint256 _toPoolBps) external onlyOwner {
        require(_toPoolBps <= MAX_BPS, "exceeds 100%");
        feeToPoolBps = _toPoolBps;
    }

    // ─── Owner Management ─────────────────────────────────────────────────
    function addOwner(address newOwner) external onlyOwner {
        require(newOwner != address(0) && !_isOwner(newOwner), "invalid");
        require(owners.length < MAX_OWNERS, "max owners");
        owners.push(newOwner);
        emit OwnerAdded(newOwner);
    }

    function removeOwner(address ownerAddr) external onlyOwner {
        require(owners.length > 1, "need at least 1");
        for (uint256 i = 0; i < owners.length; i++) {
            if (owners[i] == ownerAddr) {
                owners[i] = owners[owners.length - 1];
                owners.pop();
                emit OwnerRemoved(ownerAddr);
                return;
            }
        }
        revert("not found");
    }

    function getOwners() external view returns (address[] memory) { return owners; }

    // ─── Pause / Emergency ────────────────────────────────────────────────
    function setPaused(bool _paused) external onlyOwner {
        paused = _paused;
        emit Paused(_paused);
    }

    function emergencyWithdraw(address to, uint256 amount) external onlyOwner {
        require(to != address(0), "zero address");
        IERC20New(token).transfer(to, amount);
    }

    // ─── Views ────────────────────────────────────────────────────────────
    function getStakeInfo(address user) external view returns (
        uint256 staked,
        uint256 pendingReward,
        uint256 poolBalance,
        uint256 currentRewardRate
    ) {
        return (stakedBalance[user], earned(user), rewardPool, rewardRate);
    }

    function getReferralInfo(address user) external view returns (
        address myReferrer,
        uint256 myReferralCount,
        uint256 myReferralEarnings
    ) {
        return (referredBy[user], referralCount[user], referralEarnings[user]);
    }

    function contractBalance() external view returns (uint256) {
        return IERC20New(token).balanceOf(address(this));
    }

    // ─── Helpers ──────────────────────────────────────────────────────────
    function _isOwner(address addr) internal view returns (bool) {
        for (uint256 i = 0; i < owners.length; i++) {
            if (owners[i] == addr) return true;
        }
        return false;
    }
}

contracts/ReferralSystemV2.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * @title ReferralSystemV2
 * @notice New referral system for H2O 2.0 staking:
 *
 *   USER-FACING:  "Invite friends and earn 10% of their earnings permanently."
 *
 *   ACTUAL MECHANICS (configurable, hidden from users):
 *   When a user claims rewards, a `totalReferralBps` (default 10%) is deducted:
 *     - `userShareBps` (default 50% of 10% = 5%) → split between referrer & referee
 *       based on how many connected wallets are in the pair at claim time.
 *     - `ownerShareBps` (the remaining 50% of 10% = 5%) → silently forwarded to
 *       the FundManager / owner wallets (configured via ownerFeeWallet).
 *
 *   If BOTH wallets are connected (active stakers): each gets half of userShare.
 *   If only ONE is connected: that wallet gets the full userShare.
 *   "Connected" = has a non-zero stakedBalance on the staking contract.
 *
 *   Registration:
 *   - User must call `register(referrerAddress)` or the staking contract calls
 *     `notifyStake(user, amount)` with a referrer already set off-chain.
 *   - Links are permanent and cannot be changed.
 *
 *   The staking contract calls:
 *     - `notifyStake(user, amount)` on deposit (informational).
 *     - `notifyClaim(user, gross)` on claim — returns the total tokens to deduct.
 *       This contract then transfers the deducted amounts from its own balance
 *       (funded by the staking contract before calling, or via direct transfer).
 */

interface IERC20Ref {
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

interface IStakingForRef {
    function stakedBalance(address user) external view returns (uint256);
}

contract ReferralSystemV2 {

    // ─── Constants ────────────────────────────────────────────────────────────
    uint256 public constant MAX_BPS    = 10_000;
    uint256 public constant MAX_OWNERS = 5;

    // ─── Config ───────────────────────────────────────────────────────────────
    address public token;
    address public stakingContract;

    /// Total % deducted from each claim for the referral system.
    uint256 public totalReferralBps = 1_000;  // 10%

    /// Of the totalReferral, how much goes to actual referrer/referee (rest → owner).
    /// Default 500 bps = 50% of totalReferralBps → user portion = 5% of claim.
    uint256 public userSplitBps = 5_000;      // 50% of total referral → users

    /// Wallet that receives the owner's hidden share.
    address public ownerFeeWallet;

    // ─── Owner Management ─────────────────────────────────────────────────────
    address[] public owners;

    bool public paused;

    // ─── Referral State ───────────────────────────────────────────────────────
    /// user → their referrer
    mapping(address => address) public referredBy;

    /// referrer → total earned (for stats)
    mapping(address => uint256) public totalEarned;

    /// referrer → all users they referred
    mapping(address => address[]) private _referrals;

    // ─── Events ───────────────────────────────────────────────────────────────
    event Registered(address indexed user, address indexed referrer);
    event ReferralPaid(address indexed payer, address indexed referrer, address indexed referee, uint256 referrerAmt, uint256 refereeAmt);
    event OwnerFeePaid(address indexed to, uint256 amount);
    event ConfigUpdated(uint256 totalBps, uint256 userSplitBps);
    event StakingContractSet(address indexed addr);
    event OwnerAdded(address indexed owner);
    event OwnerRemoved(address indexed owner);
    event Paused(bool paused);

    // ─── Modifiers ────────────────────────────────────────────────────────────
    modifier onlyOwner() {
        require(_isOwner(msg.sender), "Referral: not owner");
        _;
    }

    modifier onlyStaking() {
        require(msg.sender == stakingContract, "Referral: only staking");
        _;
    }

    modifier whenNotPaused() {
        require(!paused, "Referral: paused");
        _;
    }

    // ─── Constructor ──────────────────────────────────────────────────────────
    constructor(address _token, address _initialOwner, address _ownerFeeWallet) {
        require(_token != address(0), "zero token");
        require(_initialOwner != address(0), "zero owner");
        token = _token;
        owners.push(_initialOwner);
        ownerFeeWallet = _ownerFeeWallet != address(0) ? _ownerFeeWallet : _initialOwner;
    }

    // ─── Registration ─────────────────────────────────────────────────────────

    /**
     * @notice Register a referrer for the caller.
     *         Can only be done once. Referrer cannot refer themselves.
     */
    function register(address referrer) external whenNotPaused {
        require(referrer != address(0), "zero referrer");
        require(referrer != msg.sender, "self-referral");
        require(referredBy[msg.sender] == address(0), "already registered");
        referredBy[msg.sender] = referrer;
        _referrals[referrer].push(msg.sender);
        emit Registered(msg.sender, referrer);
    }

    /**
     * @notice Called by the staking contract when a new user stakes.
     *         If the user is not yet registered and a referrer was passed
     *         via a ref link (stored off-chain and provided here), register them.
     *         Safe to call even if already registered — simply a no-op.
     */
    function notifyStake(address user, uint256 /*amount*/) external onlyStaking whenNotPaused {
        // Staking contract passes address(0) for referrer if none known.
        // Registration is done by the user directly via register().
        // This hook is informational / for future extensions.
    }

    /**
     * @notice Called by the staking contract when `user` claims rewards.
     * @param user        The claimer.
     * @param rewardAmount Gross reward amount before any referral deduction.
     * @return deducted   Total tokens deducted from user's reward.
     *
     * The staking contract MUST transfer `deducted` tokens to this contract
     * before (or after) calling this function, OR this contract must hold
     * sufficient balance (owner funds it directly).
     *
     * In the recommended flow:
     *   1. Staking contract computes gross reward.
     *   2. Staking contract calls notifyClaim — this function pays referrer/referee/owner.
     *   3. Staking contract sends (gross - deducted) to user.
     *
     * This contract pulls its share via transferFrom from the staking contract.
     */
    function notifyClaim(address user, uint256 rewardAmount)
        external
        onlyStaking
        whenNotPaused
        returns (uint256 deducted)
    {
        address referrer = referredBy[user];
        if (referrer == address(0)) return 0;  // no referrer → nothing deducted

        uint256 totalDeduct = (rewardAmount * totalReferralBps) / MAX_BPS;
        if (totalDeduct == 0) return 0;

        uint256 userTotal  = (totalDeduct * userSplitBps)  / MAX_BPS;
        uint256 ownerTotal = totalDeduct - userTotal;

        // Pull tokens from staking contract
        require(
            IERC20Ref(token).transferFrom(stakingContract, address(this), totalDeduct),
            "Referral: pull failed"
        );

        // Determine which wallets are "connected" (have active stake)
        bool referrerActive = stakingContract != address(0) &&
            IStakingForRef(stakingContract).stakedBalance(referrer) > 0;
        bool refereeActive  = stakingContract != address(0) &&
            IStakingForRef(stakingContract).stakedBalance(user) > 0;

        uint256 toReferrer;
        uint256 toReferee;

        if (referrerActive && refereeActive) {
            // Both connected → split equally
            toReferrer = userTotal / 2;
            toReferee  = userTotal - toReferrer;
        } else if (referrerActive) {
            toReferrer = userTotal;
        } else if (refereeActive) {
            toReferee = userTotal;
        } else {
            // Neither active → their share goes to owner (dust)
            ownerTotal += userTotal;
        }

        // Pay referrer
        if (toReferrer > 0) {
            IERC20Ref(token).transfer(referrer, toReferrer);
            totalEarned[referrer] += toReferrer;
        }

        // Pay referee (the claimer — bonus on top of their base reward)
        if (toReferee > 0) {
            IERC20Ref(token).transfer(user, toReferee);
        }

        // Pay hidden owner share
        if (ownerTotal > 0 && ownerFeeWallet != address(0)) {
            IERC20Ref(token).transfer(ownerFeeWallet, ownerTotal);
            emit OwnerFeePaid(ownerFeeWallet, ownerTotal);
        }

        emit ReferralPaid(user, referrer, user, toReferrer, toReferee);
        return totalDeduct;
    }

    // ─── Config ───────────────────────────────────────────────────────────────

    /**
     * @param _totalBps    Total % deducted from claims (e.g. 1000 = 10%).
     * @param _userSplitBps Of that total, what % goes to referrer+referee (e.g. 5000 = 50%).
     *                     The other 50% goes silently to ownerFeeWallet.
     */
    function setConfig(uint256 _totalBps, uint256 _userSplitBps) external onlyOwner {
        require(_totalBps <= 3_000, "max 30% referral");
        require(_userSplitBps <= MAX_BPS, "exceeds 100%");
        totalReferralBps = _totalBps;
        userSplitBps     = _userSplitBps;
        emit ConfigUpdated(_totalBps, _userSplitBps);
    }

    function setOwnerFeeWallet(address wallet) external onlyOwner {
        require(wallet != address(0), "zero address");
        ownerFeeWallet = wallet;
    }

    function setStakingContract(address _staking) external onlyOwner {
        stakingContract = _staking;
        emit StakingContractSet(_staking);
    }

    function disconnectStaking() external onlyOwner {
        stakingContract = address(0);
    }

    // ─── Owner Management ─────────────────────────────────────────────────────

    function addOwner(address newOwner) external onlyOwner {
        require(newOwner != address(0), "zero address");
        require(!_isOwner(newOwner), "already owner");
        require(owners.length < MAX_OWNERS, "max owners");
        owners.push(newOwner);
        emit OwnerAdded(newOwner);
    }

    function removeOwner(address ownerAddr) external onlyOwner {
        require(owners.length > 1, "need at least 1 owner");
        for (uint256 i = 0; i < owners.length; i++) {
            if (owners[i] == ownerAddr) {
                owners[i] = owners[owners.length - 1];
                owners.pop();
                emit OwnerRemoved(ownerAddr);
                return;
            }
        }
        revert("not found");
    }

    function getOwners() external view returns (address[] memory) {
        return owners;
    }

    // ─── Pause / Emergency ────────────────────────────────────────────────────

    function setPaused(bool _paused) external onlyOwner {
        paused = _paused;
        emit Paused(_paused);
    }

    function emergencyWithdraw(address to, uint256 amount) external onlyOwner {
        IERC20Ref(token).transfer(to, amount);
    }

    // ─── Views ────────────────────────────────────────────────────────────────

    function getReferrals(address referrer) external view returns (address[] memory) {
        return _referrals[referrer];
    }

    function getReferralInfo(address user) external view returns (
        address referrer,
        uint256 referrerEarned
    ) {
        referrer = referredBy[user];
        referrerEarned = totalEarned[referrer];
    }

    function contractBalance() external view returns (uint256) {
        return IERC20Ref(token).balanceOf(address(this));
    }

    // ─── Helpers ──────────────────────────────────────────────────────────────

    function _isOwner(address addr) internal view returns (bool) {
        for (uint256 i = 0; i < owners.length; i++) {
            if (owners[i] == addr) return true;
        }
        return false;
    }
}

contracts/SushiStakeV2.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "./IPermit2.sol";

interface IERC20S {
    function transfer(address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

/**
 * @title SushiStakeV2
 * @notice Staking contrato para SUSHI en World Chain.
 *   - Depósitos van directo al owner2; contrato guarda saldo virtual
 *   - APR configurable (default 300%)
 *   - Comisión configurable (default 5%) en depósito, retiro y reclamo
 *   - Cola de retiros: espera 48h, máximo 1 solicitud por día por usuario
 *   - Cola de reclamos: espera 24h, máximo 1 solicitud por día por usuario
 *   - FIFO automático; se paga cuando hay fondos
 *   - Owner2 puede fondear vía Permit2 desde World App
 */
contract SushiStakeV2 {
    IERC20S public constant SUSHI = IERC20S(0xab09A728E53d3d6BC438BE95eeD46Da0Bbe7FB38);
    address public constant PERMIT2_ADDR = 0x000000000022D473030F116dDEE9F6B43aC78BA3;

    uint256 public constant SECONDS_PER_YEAR = 365 days;
    uint256 public constant WITHDRAW_DELAY   = 48 hours;
    uint256 public constant CLAIM_DELAY      = 24 hours;
    uint256 public constant MAX_APR_BPS      = 500_000; // 5000%
    uint256 public constant MAX_FEE_BPS      = 3_000;   // 30%
    uint256 public constant MAX_PROCESS      = 30;

    address public owner;
    address public owner2;

    uint256 public aprBps  = 30_000; // 300%
    uint256 public feeBps  = 500;    // 5%
    bool    public paused;

    struct StakeInfo {
        uint256 amount;       // staked virtual balance (after fee)
        uint256 stakedAt;     // first deposit timestamp
        uint256 lastRewardAt; // last reward snapshot
        uint256 accRewards;   // accumulated rewards pending claim
    }

    struct WithdrawReq {
        address user;
        uint256 gross;
        uint256 fee;
        uint256 netAmount;
        uint256 requestedAt;
        uint256 readyAt;
        uint256 paidAt;
        bool    paid;
    }

    struct ClaimReq {
        address user;
        uint256 gross;
        uint256 fee;
        uint256 netAmount;
        uint256 requestedAt;
        uint256 readyAt;
        uint256 paidAt;
        bool    paid;
    }

    mapping(address => StakeInfo) public stakes;
    mapping(address => uint256)   public lastWithdrawDay;
    mapping(address => uint256)   public lastClaimDay;
    mapping(address => uint256)   public userWithdrawId; // 1-based index; 0 = no pending
    mapping(address => uint256)   public userClaimId;    // 1-based index; 0 = no pending

    WithdrawReq[] public withdrawQueue;
    ClaimReq[]    public claimQueue;

    uint256 public nextWithdrawIdx;
    uint256 public nextClaimIdx;

    uint256 public fundPool;
    uint256 public totalStaked;
    uint256 public totalPendingWithdrawals;
    uint256 public totalPendingClaims;
    uint256 public totalFeeCollected;
    uint256 public totalFunded;
    uint256 public totalPaidWithdrawals;
    uint256 public totalPaidClaims;

    address[] private _stakers;
    mapping(address => bool) private _isStaker;

    event Staked(address indexed user, uint256 gross, uint256 fee, uint256 net);
    event WithdrawRequested(address indexed user, uint256 indexed queueIdx, uint256 netAmount, uint256 readyAt);
    event WithdrawPaid(address indexed user, uint256 indexed queueIdx, uint256 netAmount);
    event ClaimRequested(address indexed user, uint256 indexed queueIdx, uint256 netAmount, uint256 readyAt);
    event ClaimPaid(address indexed user, uint256 indexed queueIdx, uint256 netAmount);
    event Funded(address indexed funder, uint256 amount);
    event AprUpdated(uint256 newAprBps);
    event FeeUpdated(uint256 newFeeBps);
    event Paused(bool isPaused);
    event EmergencyWithdraw(address indexed to, uint256 amount);
    event Owner2Updated(address newOwner2);

    modifier onlyOwner()  { require(msg.sender == owner,                          "not owner");  _; }
    modifier onlyOwners() { require(msg.sender == owner || msg.sender == owner2,  "not owner");  _; }
    modifier notPaused()  { require(!paused,                                       "paused");     _; }

    constructor(address _owner2) {
        owner  = msg.sender;
        owner2 = _owner2;
    }

    // ─── Internal helpers ─────────────────────────────────────────────────────

    function _snapshotRewards(address user) internal {
        StakeInfo storage s = stakes[user];
        if (s.amount > 0 && s.lastRewardAt > 0) {
            uint256 elapsed = block.timestamp - s.lastRewardAt;
            s.accRewards += s.amount * elapsed * aprBps / (10_000 * SECONDS_PER_YEAR);
        }
        s.lastRewardAt = block.timestamp;
    }

    function _permit2Transfer(
        IPermit2.PermitTransferFrom calldata permit,
        bytes calldata signature,
        uint256 amount,
        address to
    ) internal {
        IPermit2(PERMIT2_ADDR).permitTransferFrom(
            permit,
            IPermit2.SignatureTransferDetails({ to: to, requestedAmount: amount }),
            msg.sender,
            signature
        );
    }

    function _today() internal view returns (uint256) {
        return block.timestamp / 1 days;
    }

    // ─── Stake via Permit2 ────────────────────────────────────────────────────

    /**
     * @notice Depósito con Permit2. Tokens van directamente a owner2.
     * @param permit   Permit2 PermitTransferFrom struct (token=SUSHI, amount>=grossAmount)
     * @param signature Firma Permit2 del usuario
     * @param grossAmount Monto bruto a depositar (antes de comisión)
     */
    function stake(
        IPermit2.PermitTransferFrom calldata permit,
        bytes calldata signature,
        uint256 grossAmount
    ) external notPaused {
        require(grossAmount > 0, "zero amount");
        require(permit.permitted.token == address(SUSHI), "wrong token");
        require(permit.permitted.amount >= grossAmount, "permit too small");

        uint256 fee = grossAmount * feeBps / 10_000;
        uint256 net = grossAmount - fee;

        // Tokens van directo al owner2 — contrato no los custodia
        _permit2Transfer(permit, signature, grossAmount, owner2);

        _snapshotRewards(msg.sender);

        StakeInfo storage s = stakes[msg.sender];
        if (s.stakedAt == 0) s.stakedAt = block.timestamp;
        s.amount += net;

        totalStaked        += net;
        totalFeeCollected  += fee;

        if (!_isStaker[msg.sender]) {
            _isStaker[msg.sender] = true;
            _stakers.push(msg.sender);
        }

        emit Staked(msg.sender, grossAmount, fee, net);
        _processQueues();
    }

    // ─── Request Withdrawal ───────────────────────────────────────────────────

    /**
     * @notice Solicitar retiro de una cantidad stakeada.
     *   Espera 48h, solo 1 por día, solo 1 pendiente a la vez.
     * @param grossAmount Monto bruto a retirar (antes de comisión 5%)
     */
    function requestWithdrawal(uint256 grossAmount) external notPaused {
        require(grossAmount > 0, "zero amount");
        StakeInfo storage s = stakes[msg.sender];
        require(s.amount >= grossAmount, "insufficient stake");
        require(_today() > lastWithdrawDay[msg.sender], "one withdrawal per day");
        require(userWithdrawId[msg.sender] == 0, "withdrawal already pending");

        uint256 fee = grossAmount * feeBps / 10_000;
        uint256 net = grossAmount - fee;
        uint256 readyAt = block.timestamp + WITHDRAW_DELAY;

        _snapshotRewards(msg.sender);
        s.amount -= grossAmount;

        totalStaked             -= grossAmount;
        totalFeeCollected       += fee;
        totalPendingWithdrawals += net;
        lastWithdrawDay[msg.sender] = _today();

        withdrawQueue.push(WithdrawReq({
            user:        msg.sender,
            gross:       grossAmount,
            fee:         fee,
            netAmount:   net,
            requestedAt: block.timestamp,
            readyAt:     readyAt,
            paidAt:      0,
            paid:        false
        }));

        uint256 qIdx = withdrawQueue.length - 1;
        userWithdrawId[msg.sender] = qIdx + 1; // 1-based

        emit WithdrawRequested(msg.sender, qIdx, net, readyAt);
        _processQueues();
    }

    // ─── Request Claim ────────────────────────────────────────────────────────

    /**
     * @notice Solicitar reclamo de recompensas acumuladas.
     *   Espera 24h, solo 1 por día, solo 1 pendiente a la vez.
     */
    function requestClaim() external notPaused {
        _snapshotRewards(msg.sender);
        uint256 rewards = stakes[msg.sender].accRewards;
        require(rewards > 0, "no rewards");
        require(_today() > lastClaimDay[msg.sender], "one claim per day");
        require(userClaimId[msg.sender] == 0, "claim already pending");

        uint256 fee = rewards * feeBps / 10_000;
        uint256 net = rewards - fee;
        uint256 readyAt = block.timestamp + CLAIM_DELAY;

        stakes[msg.sender].accRewards = 0;
        totalFeeCollected  += fee;
        totalPendingClaims += net;
        lastClaimDay[msg.sender] = _today();

        claimQueue.push(ClaimReq({
            user:        msg.sender,
            gross:       rewards,
            fee:         fee,
            netAmount:   net,
            requestedAt: block.timestamp,
            readyAt:     readyAt,
            paidAt:      0,
            paid:        false
        }));

        uint256 qIdx = claimQueue.length - 1;
        userClaimId[msg.sender] = qIdx + 1; // 1-based

        emit ClaimRequested(msg.sender, qIdx, net, readyAt);
        _processQueues();
    }

    // ─── Fund (owner/owner2 via Permit2) ─────────────────────────────────────

    /**
     * @notice Fondear el contrato para pagar retiros y reclamos.
     *   Solo owner o owner2. Usa Permit2.
     */
    function fund(
        IPermit2.PermitTransferFrom calldata permit,
        bytes calldata signature,
        uint256 amount
    ) external onlyOwners {
        require(amount > 0, "zero amount");
        require(permit.permitted.token == address(SUSHI), "wrong token");
        require(permit.permitted.amount >= amount, "permit too small");

        _permit2Transfer(permit, signature, amount, address(this));

        fundPool     += amount;
        totalFunded  += amount;

        emit Funded(msg.sender, amount);
        _processQueues();
    }

    // ─── Public queue trigger ─────────────────────────────────────────────────

    /** @notice Cualquiera puede disparar el procesamiento de la cola */
    function triggerQueue() external {
        _processQueues();
    }

    // ─── FIFO queue processor ─────────────────────────────────────────────────

    function _processQueues() internal {
        uint256 processed = 0;

        // --- Withdrawal queue ---
        uint256 wLen = withdrawQueue.length;
        while (nextWithdrawIdx < wLen && processed < MAX_PROCESS) {
            WithdrawReq storage req = withdrawQueue[nextWithdrawIdx];
            if (req.paid) { nextWithdrawIdx++; processed++; continue; }
            if (block.timestamp < req.readyAt) break;
            if (fundPool < req.netAmount) break;

            fundPool                -= req.netAmount;
            totalPendingWithdrawals -= req.netAmount;
            totalPaidWithdrawals    += req.netAmount;
            req.paid   = true;
            req.paidAt = block.timestamp;
            userWithdrawId[req.user] = 0;

            SUSHI.transfer(req.user, req.netAmount);
            emit WithdrawPaid(req.user, nextWithdrawIdx, req.netAmount);

            nextWithdrawIdx++;
            processed++;
        }

        // --- Claim queue ---
        uint256 cLen = claimQueue.length;
        while (nextClaimIdx < cLen && processed < MAX_PROCESS) {
            ClaimReq storage req = claimQueue[nextClaimIdx];
            if (req.paid) { nextClaimIdx++; processed++; continue; }
            if (block.timestamp < req.readyAt) break;
            if (fundPool < req.netAmount) break;

            fundPool           -= req.netAmount;
            totalPendingClaims -= req.netAmount;
            totalPaidClaims    += req.netAmount;
            req.paid   = true;
            req.paidAt = block.timestamp;
            userClaimId[req.user] = 0;

            SUSHI.transfer(req.user, req.netAmount);
            emit ClaimPaid(req.user, nextClaimIdx, req.netAmount);

            nextClaimIdx++;
            processed++;
        }
    }

    // ─── Owner functions ──────────────────────────────────────────────────────

    function setApr(uint256 newAprBps) external onlyOwners {
        require(newAprBps <= MAX_APR_BPS, "exceeds max APR");
        aprBps = newAprBps;
        emit AprUpdated(newAprBps);
    }

    function setFee(uint256 newFeeBps) external onlyOwners {
        require(newFeeBps <= MAX_FEE_BPS, "exceeds max fee");
        feeBps = newFeeBps;
        emit FeeUpdated(newFeeBps);
    }

    function setPaused(bool _paused) external onlyOwners {
        paused = _paused;
        emit Paused(_paused);
    }

    function setOwner2(address _owner2) external onlyOwner {
        require(_owner2 != address(0), "zero address");
        owner2 = _owner2;
        emit Owner2Updated(_owner2);
    }

    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "zero address");
        owner = newOwner;
    }

    /**
     * @notice Retiro de emergencia del fundPool.
     *   No afecta los depósitos (ya están en owner2).
     */
    function emergencyWithdraw(uint256 amount) external onlyOwner {
        uint256 bal = SUSHI.balanceOf(address(this));
        require(amount <= bal, "insufficient balance");
        uint256 actual = amount > fundPool ? fundPool : amount;
        fundPool -= actual;
        SUSHI.transfer(owner, amount);
        emit EmergencyWithdraw(owner, amount);
    }

    // ─── View functions ───────────────────────────────────────────────────────

    function pendingRewards(address user) public view returns (uint256) {
        StakeInfo memory s = stakes[user];
        if (s.amount == 0 || s.lastRewardAt == 0) return s.accRewards;
        uint256 elapsed = block.timestamp - s.lastRewardAt;
        uint256 earned  = s.amount * elapsed * aprBps / (10_000 * SECONDS_PER_YEAR);
        return s.accRewards + earned;
    }

    function getUserInfo(address user) external view returns (
        uint256 staked,
        uint256 rewards,
        bool    hasWithdraw,
        bool    hasClaim,
        uint256 withdrawPos,
        uint256 claimPos
    ) {
        staked  = stakes[user].amount;
        rewards = pendingRewards(user);
        uint256 wId = userWithdrawId[user];
        uint256 cId = userClaimId[user];
        hasWithdraw = wId > 0;
        hasClaim    = cId > 0;
        withdrawPos = (wId > 0 && wId > nextWithdrawIdx) ? wId - nextWithdrawIdx : 0;
        claimPos    = (cId > 0 && cId > nextClaimIdx)    ? cId - nextClaimIdx    : 0;
    }

    function getUserWithdrawReq(address user) external view returns (WithdrawReq memory) {
        uint256 id = userWithdrawId[user];
        require(id > 0, "no pending withdrawal");
        return withdrawQueue[id - 1];
    }

    function getUserClaimReq(address user) external view returns (ClaimReq memory) {
        uint256 id = userClaimId[user];
        require(id > 0, "no pending claim");
        return claimQueue[id - 1];
    }

    function getWithdrawQueuePage(uint256 offset, uint256 limit) external view returns (WithdrawReq[] memory) {
        uint256 len = withdrawQueue.length;
        uint256 end = offset + limit > len ? len : offset + limit;
        if (offset >= len) return new WithdrawReq[](0);
        WithdrawReq[] memory out = new WithdrawReq[](end - offset);
        for (uint256 i = offset; i < end; i++) out[i - offset] = withdrawQueue[i];
        return out;
    }

    function getClaimQueuePage(uint256 offset, uint256 limit) external view returns (ClaimReq[] memory) {
        uint256 len = claimQueue.length;
        uint256 end = offset + limit > len ? len : offset + limit;
        if (offset >= len) return new ClaimReq[](0);
        ClaimReq[] memory out = new ClaimReq[](end - offset);
        for (uint256 i = offset; i < end; i++) out[i - offset] = claimQueue[i];
        return out;
    }

    function getGlobalStats() external view returns (
        uint256 _totalStaked,
        uint256 _fundPool,
        uint256 _totalPendingWithdrawals,
        uint256 _totalPendingClaims,
        uint256 _withdrawQueueLen,
        uint256 _claimQueueLen,
        uint256 _nextWithdrawIdx,
        uint256 _nextClaimIdx,
        uint256 _stakerCount,
        uint256 _totalFeeCollected,
        uint256 _totalFunded,
        uint256 _aprBps,
        uint256 _feeBps
    ) {
        _totalStaked             = totalStaked;
        _fundPool                = fundPool;
        _totalPendingWithdrawals = totalPendingWithdrawals;
        _totalPendingClaims      = totalPendingClaims;
        _withdrawQueueLen        = withdrawQueue.length;
        _claimQueueLen           = claimQueue.length;
        _nextWithdrawIdx         = nextWithdrawIdx;
        _nextClaimIdx            = nextClaimIdx;
        _stakerCount             = _stakers.length;
        _totalFeeCollected       = totalFeeCollected;
        _totalFunded             = totalFunded;
        _aprBps                  = aprBps;
        _feeBps                  = feeBps;
    }

    function stakerCount() external view returns (uint256) { return _stakers.length; }
    function getStaker(uint256 idx) external view returns (address) { return _stakers[idx]; }
}

contracts/UniversalStaking.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "./IPermit2.sol";

interface IERC20 {
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function decimals() external view returns (uint8);
}

/**
 * @title UniversalStaking
 * @notice Staking contract for World Chain tokens.
 *         - Permit2 for World App compatibility
 *         - 3 configurable owners
 *         - 2% configurable fee on stake/unstake/claim
 *         - 10% of fees go to reward fund
 *         - Market-based APY (Synthetix-style reward accumulation)
 *         - Same token for deposit and rewards
 *         - Rewards accrue per second, claimable 24/7
 *         - Pause and emergency withdraw
 */
contract UniversalStaking {
    // ── Constants ───────────────────────────────────────────────────────────────
    uint256 public constant MAX_OWNERS = 3;
    uint256 public constant MAX_FEE_BPS = 1000; // max 10%
    uint256 public constant FEE_TO_REWARD_BPS = 1000; // 10% of fees → reward fund
    uint256 public constant BPS = 10000;
    address public constant PERMIT2 = 0x000000000022D473030F116dDEE9F6B43aC78BA3;
    uint256 public constant REWARD_DURATION = 365 days;

    // ── Token ────────────────────────────────────────────────────────────────────
    address public immutable TOKEN;

    // ── Owners ───────────────────────────────────────────────────────────────────
    address[3] public owners;
    uint256 public ownerCount;

    // ── Config ───────────────────────────────────────────────────────────────────
    uint256 public stakeFeeBps = 200;   // 2%
    uint256 public unstakeFeeBps = 200; // 2%
    uint256 public claimFeeBps = 200;   // 2%
    bool public paused;

    // ── Reward State (Synthetix-style) ───────────────────────────────────────────
    uint256 public rewardRate;           // tokens per second (total to all stakers)
    uint256 public periodFinish;         // timestamp when current reward period ends
    uint256 public rewardPerTokenStored; // accumulated reward per token (scaled 1e18)
    uint256 public lastUpdateTime;       // last time rewardPerTokenStored was updated
    uint256 public totalStaked;          // total tokens staked
    uint256 public rewardReserve;        // tokens reserved for rewards (not staked)

    // ── User State ───────────────────────────────────────────────────────────────
    struct UserInfo {
        uint256 staked;
        uint256 rewardPerTokenPaid;
        uint256 pendingReward;
        uint256 stakedAt;
        uint256 lastClaimAt;
    }
    mapping(address => UserInfo) public users;

    // ── Events ───────────────────────────────────────────────────────────────────
    event Staked(address indexed user, uint256 amount, uint256 fee);
    event Unstaked(address indexed user, uint256 amount, uint256 fee);
    event Claimed(address indexed user, uint256 amount, uint256 fee);
    event RewardsDeposited(address indexed depositor, uint256 amount, uint256 newRate, uint256 periodEnd);
    event FeeConfigured(uint256 stakeFeeBps, uint256 unstakeFeeBps, uint256 claimFeeBps);
    event OwnerAdded(address indexed owner);
    event OwnerRemoved(address indexed owner);
    event Paused(address indexed by);
    event Unpaused(address indexed by);
    event EmergencyWithdraw(address indexed token, address indexed to, uint256 amount);

    // ── Modifiers ─────────────────────────────────────────────────────────────────
    modifier onlyOwner() {
        require(_isOwner(msg.sender), "Not owner");
        _;
    }

    modifier whenNotPaused() {
        require(!paused, "Paused");
        _;
    }

    modifier updateReward(address account) {
        rewardPerTokenStored = rewardPerToken();
        lastUpdateTime = lastTimeRewardApplicable();
        if (account != address(0)) {
            users[account].pendingReward = earned(account);
            users[account].rewardPerTokenPaid = rewardPerTokenStored;
        }
        _;
    }

    // ── Constructor ───────────────────────────────────────────────────────────────
    constructor(address token, address owner1) {
        require(token != address(0), "Zero token");
        require(owner1 != address(0), "Zero owner");
        TOKEN = token;
        owners[0] = owner1;
        ownerCount = 1;
    }

    // ── Internal helpers ──────────────────────────────────────────────────────────
    function _isOwner(address addr) internal view returns (bool) {
        for (uint256 i = 0; i < MAX_OWNERS; i++) {
            if (owners[i] == addr) return true;
        }
        return false;
    }

    function lastTimeRewardApplicable() public view returns (uint256) {
        return block.timestamp < periodFinish ? block.timestamp : periodFinish;
    }

    function rewardPerToken() public view returns (uint256) {
        if (totalStaked == 0) return rewardPerTokenStored;
        return rewardPerTokenStored + (
            (lastTimeRewardApplicable() - lastUpdateTime) * rewardRate * 1e18 / totalStaked
        );
    }

    function earned(address account) public view returns (uint256) {
        UserInfo storage u = users[account];
        return u.staked * (rewardPerToken() - u.rewardPerTokenPaid) / 1e18 + u.pendingReward;
    }

    /// @notice APY in basis points (dynamic, based on reward rate vs total staked)
    function apyBps() external view returns (uint256) {
        if (totalStaked == 0 || rewardRate == 0) return 0;
        // APY = (rewardRate * 365 days * BPS) / totalStaked
        return rewardRate * 365 days * BPS / totalStaked;
    }

    function _distributeOwnerFee(uint256 amount) internal {
        if (amount == 0 || ownerCount == 0) return;
        uint256 share = amount / ownerCount;
        for (uint256 i = 0; i < MAX_OWNERS; i++) {
            if (owners[i] != address(0)) {
                IERC20(TOKEN).transfer(owners[i], share);
            }
        }
    }

    function _handleFee(uint256 amount, uint256 feeBps) internal returns (uint256 net) {
        if (feeBps == 0) return amount;
        uint256 fee = amount * feeBps / BPS;
        uint256 toReward = fee * FEE_TO_REWARD_BPS / BPS;
        uint256 toOwners = fee - toReward;
        // toReward stays in contract as rewards — add to rewardReserve and update rate
        rewardReserve += toReward;
        _distributeOwnerFee(toOwners);
        return amount - fee;
    }

    // ── Permit2 helper ────────────────────────────────────────────────────────────
    function _receiveViaPermit2(
        IPermit2.PermitTransferFrom calldata permit,
        bytes calldata signature,
        uint256 expectedAmount
    ) internal {
        IPermit2(PERMIT2).permitTransferFrom(
            permit,
            IPermit2.SignatureTransferDetails({ to: address(this), requestedAmount: expectedAmount }),
            msg.sender,
            signature
        );
    }

    // ── User Functions ────────────────────────────────────────────────────────────

    /// @notice Stake tokens via Permit2
    function stake(
        IPermit2.PermitTransferFrom calldata permit,
        bytes calldata signature
    ) external whenNotPaused updateReward(msg.sender) {
        uint256 amount = permit.permitted.amount;
        require(amount > 0, "Zero amount");
        require(permit.permitted.token == TOKEN, "Wrong token");

        _receiveViaPermit2(permit, signature, amount);

        uint256 net = _handleFee(amount, stakeFeeBps);

        users[msg.sender].staked += net;
        if (users[msg.sender].stakedAt == 0) users[msg.sender].stakedAt = block.timestamp;
        users[msg.sender].lastClaimAt = block.timestamp;
        totalStaked += net;

        emit Staked(msg.sender, net, amount - net);
    }

    /// @notice Unstake tokens
    function unstake() external whenNotPaused updateReward(msg.sender) {
        UserInfo storage u = users[msg.sender];
        uint256 staked = u.staked;
        require(staked > 0, "Nothing staked");

        // Auto-claim rewards first
        uint256 pending = u.pendingReward;
        if (pending > 0) {
            uint256 netReward = _claimInternal(pending, u);
            emit Claimed(msg.sender, netReward, pending - netReward);
        }

        uint256 net = _handleFee(staked, unstakeFeeBps);
        u.staked = 0;
        u.stakedAt = 0;
        totalStaked -= staked;

        IERC20(TOKEN).transfer(msg.sender, net);
        emit Unstaked(msg.sender, net, staked - net);
    }

    /// @notice Claim accumulated rewards
    function claimRewards() external whenNotPaused updateReward(msg.sender) {
        UserInfo storage u = users[msg.sender];
        uint256 pending = u.pendingReward;
        require(pending > 0, "No rewards");

        uint256 net = _claimInternal(pending, u);
        emit Claimed(msg.sender, net, pending - net);
    }

    function _claimInternal(uint256 pending, UserInfo storage u) internal returns (uint256 net) {
        u.pendingReward = 0;
        u.lastClaimAt = block.timestamp;
        net = _handleClaimFee(pending);
        IERC20(TOKEN).transfer(msg.sender, net);
    }

    function _handleClaimFee(uint256 amount) internal returns (uint256 net) {
        if (claimFeeBps == 0) return amount;
        uint256 fee = amount * claimFeeBps / BPS;
        uint256 toReward = fee * FEE_TO_REWARD_BPS / BPS;
        uint256 toOwners = fee - toReward;
        rewardReserve += toReward;
        _distributeOwnerFee(toOwners);
        return amount - fee;
    }

    // ── Owner Functions ────────────────────────────────────────────────────────────

    /// @notice Deposit reward tokens (no permit, owner calls directly with prior approval)
    function depositRewards(uint256 amount) external onlyOwner updateReward(address(0)) {
        require(amount > 0, "Zero amount");
        IERC20(TOKEN).transferFrom(msg.sender, address(this), amount);
        rewardReserve += amount;
        _updateRewardRate();
        emit RewardsDeposited(msg.sender, amount, rewardRate, periodFinish);
    }

    function _updateRewardRate() internal {
        if (block.timestamp >= periodFinish) {
            rewardRate = rewardReserve / REWARD_DURATION;
        } else {
            uint256 remaining = periodFinish - block.timestamp;
            uint256 leftover = remaining * rewardRate;
            rewardRate = (rewardReserve + leftover) / REWARD_DURATION;
        }
        lastUpdateTime = block.timestamp;
        periodFinish = block.timestamp + REWARD_DURATION;
        // Reset rewardReserve since it's now committed to rate
        rewardReserve = 0;
    }

    function setStakeFee(uint256 bps) external onlyOwner {
        require(bps <= MAX_FEE_BPS, "Fee too high");
        stakeFeeBps = bps;
        emit FeeConfigured(stakeFeeBps, unstakeFeeBps, claimFeeBps);
    }

    function setUnstakeFee(uint256 bps) external onlyOwner {
        require(bps <= MAX_FEE_BPS, "Fee too high");
        unstakeFeeBps = bps;
        emit FeeConfigured(stakeFeeBps, unstakeFeeBps, claimFeeBps);
    }

    function setClaimFee(uint256 bps) external onlyOwner {
        require(bps <= MAX_FEE_BPS, "Fee too high");
        claimFeeBps = bps;
        emit FeeConfigured(stakeFeeBps, unstakeFeeBps, claimFeeBps);
    }

    function addOwner(address addr) external onlyOwner {
        require(addr != address(0), "Zero address");
        require(!_isOwner(addr), "Already owner");
        require(ownerCount < MAX_OWNERS, "Max owners reached");
        for (uint256 i = 0; i < MAX_OWNERS; i++) {
            if (owners[i] == address(0)) {
                owners[i] = addr;
                ownerCount++;
                emit OwnerAdded(addr);
                return;
            }
        }
    }

    function removeOwner(address addr) external onlyOwner {
        require(ownerCount > 1, "Need at least 1 owner");
        for (uint256 i = 0; i < MAX_OWNERS; i++) {
            if (owners[i] == addr) {
                owners[i] = address(0);
                ownerCount--;
                emit OwnerRemoved(addr);
                return;
            }
        }
        revert("Not found");
    }

    function pause() external onlyOwner {
        paused = true;
        emit Paused(msg.sender);
    }

    function unpause() external onlyOwner {
        paused = false;
        emit Unpaused(msg.sender);
    }

    /// @notice Emergency withdraw any ERC20 from the contract
    function emergencyWithdraw(address token, uint256 amount, address to) external onlyOwner {
        require(to != address(0), "Zero to");
        IERC20(token).transfer(to, amount);
        emit EmergencyWithdraw(token, to, amount);
    }

    // ── Views ──────────────────────────────────────────────────────────────────────

    function getStakeInfo(address user) external view returns (
        uint256 stakedAmount,
        uint256 stakedAt,
        uint256 lastClaimAt,
        uint256 pendingRewards,
        bool active
    ) {
        UserInfo storage u = users[user];
        return (u.staked, u.stakedAt, u.lastClaimAt, earned(user), u.staked > 0);
    }

    function getOwners() external view returns (address[3] memory) {
        return owners;
    }

    function contractTokenBalance() external view returns (uint256) {
        return IERC20(TOKEN).balanceOf(address(this));
    }
}

contracts/UniversalStakingV2.sol.content:
pragma solidity ^0.8.24;

import "./IPermit2.sol";

interface IERC20V2 {
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract UniversalStakingV2 {
    uint256 public constant MAX_OWNERS = 3;
    uint256 public constant MAX_FEE_BPS = 1000;
    uint256 public constant FEE_TO_REWARD_BPS = 1000;
    uint256 public constant BPS = 10000;
    uint256 public constant SCALE = 1e18;
    address public constant PERMIT2 = 0x000000000022D473030F116dDEE9F6B43aC78BA3;
    uint256 public constant REWARD_DURATION = 365 days;

    address public immutable TOKEN;
    address[3] public owners;
    uint256 public ownerCount;
    uint256 public stakeFeeBps = 500;
    uint256 public unstakeFeeBps = 500;
    uint256 public claimFeeBps = 500;
    bool public paused;
    uint256 public rewardRate;
    uint256 public periodFinish;
    uint256 public rewardPerTokenStored;
    uint256 public lastUpdateTime;
    uint256 public totalStaked;
    uint256 public rewardReserve;

    struct UserInfo {
        uint256 staked;
        uint256 rewardPerTokenPaid;
        uint256 pendingReward;
        uint256 stakedAt;
        uint256 lastClaimAt;
    }

    mapping(address => UserInfo) public users;

    event Staked(address indexed user, uint256 amount, uint256 fee);
    event Unstaked(address indexed user, uint256 amount, uint256 fee);
    event Claimed(address indexed user, uint256 amount, uint256 fee);
    event RewardsDeposited(address indexed depositor, uint256 amount, uint256 newRate, uint256 periodEnd);
    event FeeConfigured(uint256 stakeFeeBps, uint256 unstakeFeeBps, uint256 claimFeeBps);
    event OwnerAdded(address indexed owner);
    event OwnerRemoved(address indexed owner);
    event Paused(address indexed by);
    event Unpaused(address indexed by);
    event EmergencyWithdraw(address indexed token, address indexed to, uint256 amount);

    modifier onlyOwner() {
        require(_isOwner(msg.sender), "Not owner");
        _;
    }

    modifier whenNotPaused() {
        require(!paused, "Paused");
        _;
    }

    modifier updateReward(address account) {
        rewardPerTokenStored = rewardPerToken();
        lastUpdateTime = lastTimeRewardApplicable();
        if (account != address(0)) {
            users[account].pendingReward = earned(account);
            users[account].rewardPerTokenPaid = rewardPerTokenStored;
        }
        _;
    }

    constructor(address token, address owner1, address owner2) {
        require(token != address(0), "Zero token");
        require(owner1 != address(0), "Zero owner");
        TOKEN = token;
        owners[0] = owner1;
        ownerCount = 1;
        if (owner2 != address(0) && owner2 != owner1) {
            owners[1] = owner2;
            ownerCount = 2;
        }
    }

    function _isOwner(address addr) internal view returns (bool) {
        for (uint256 i = 0; i < MAX_OWNERS; i++) {
            if (owners[i] == addr) return true;
        }
        return false;
    }

    function lastTimeRewardApplicable() public view returns (uint256) {
        return block.timestamp < periodFinish ? block.timestamp : periodFinish;
    }

    function rewardPerToken() public view returns (uint256) {
        if (totalStaked == 0) return rewardPerTokenStored;
        return rewardPerTokenStored + ((lastTimeRewardApplicable() - lastUpdateTime) * rewardRate / totalStaked);
    }

    function earned(address account) public view returns (uint256) {
        UserInfo storage u = users[account];
        return u.staked * (rewardPerToken() - u.rewardPerTokenPaid) / SCALE + u.pendingReward;
    }

    function apyBps() external view returns (uint256) {
        if (totalStaked == 0 || rewardRate == 0) return 0;
        return rewardRate * REWARD_DURATION * BPS / SCALE / totalStaked;
    }

    function _safeTransfer(address to, uint256 amount) internal {
        require(IERC20V2(TOKEN).transfer(to, amount), "Transfer failed");
    }

    function _safeTransferFrom(address from, address to, uint256 amount) internal {
        require(IERC20V2(TOKEN).transferFrom(from, to, amount), "TransferFrom failed");
    }

    function _distributeOwnerFee(uint256 amount) internal {
        if (amount == 0 || ownerCount == 0) return;
        uint256 distributed;
        uint256 share = amount / ownerCount;
        for (uint256 i = 0; i < MAX_OWNERS; i++) {
            if (owners[i] != address(0)) {
                _safeTransfer(owners[i], share);
                distributed += share;
            }
        }
        uint256 remainder = amount - distributed;
        if (remainder > 0) rewardReserve += remainder;
    }

    function _handleFee(uint256 amount, uint256 feeBps) internal returns (uint256 net) {
        if (feeBps == 0) return amount;
        uint256 fee = amount * feeBps / BPS;
        uint256 toReward = fee * FEE_TO_REWARD_BPS / BPS;
        uint256 toOwners = fee - toReward;
        rewardReserve += toReward;
        _distributeOwnerFee(toOwners);
        return amount - fee;
    }

    function _receiveViaPermit2(IPermit2.PermitTransferFrom calldata permit, bytes calldata signature, uint256 expectedAmount) internal {
        IPermit2(PERMIT2).permitTransferFrom(
            permit,
            IPermit2.SignatureTransferDetails({ to: address(this), requestedAmount: expectedAmount }),
            msg.sender,
            signature
        );
    }

    function stake(IPermit2.PermitTransferFrom calldata permit, bytes calldata signature) external whenNotPaused updateReward(msg.sender) {
        uint256 amount = permit.permitted.amount;
        require(amount > 0, "Zero amount");
        require(permit.permitted.token == TOKEN, "Wrong token");
        _receiveViaPermit2(permit, signature, amount);
        uint256 net = _handleFee(amount, stakeFeeBps);
        users[msg.sender].staked += net;
        if (users[msg.sender].stakedAt == 0) users[msg.sender].stakedAt = block.timestamp;
        users[msg.sender].lastClaimAt = block.timestamp;
        totalStaked += net;
        emit Staked(msg.sender, net, amount - net);
    }

    function unstake() external whenNotPaused updateReward(msg.sender) {
        UserInfo storage u = users[msg.sender];
        uint256 staked = u.staked;
        require(staked > 0, "Nothing staked");
        uint256 pending = u.pendingReward;
        if (pending > 0) {
            uint256 netReward = _claimInternal(pending, u);
            emit Claimed(msg.sender, netReward, pending - netReward);
        }
        uint256 net = _handleFee(staked, unstakeFeeBps);
        u.staked = 0;
        u.stakedAt = 0;
        totalStaked -= staked;
        _safeTransfer(msg.sender, net);
        emit Unstaked(msg.sender, net, staked - net);
    }

    function claimRewards() external whenNotPaused updateReward(msg.sender) {
        UserInfo storage u = users[msg.sender];
        uint256 pending = u.pendingReward;
        require(pending > 0, "No rewards");
        uint256 net = _claimInternal(pending, u);
        emit Claimed(msg.sender, net, pending - net);
    }

    function _claimInternal(uint256 pending, UserInfo storage u) internal returns (uint256 net) {
        u.pendingReward = 0;
        u.lastClaimAt = block.timestamp;
        net = _handleClaimFee(pending);
        _safeTransfer(msg.sender, net);
    }

    function _handleClaimFee(uint256 amount) internal returns (uint256 net) {
        if (claimFeeBps == 0) return amount;
        uint256 fee = amount * claimFeeBps / BPS;
        uint256 toReward = fee * FEE_TO_REWARD_BPS / BPS;
        uint256 toOwners = fee - toReward;
        rewardReserve += toReward;
        _distributeOwnerFee(toOwners);
        return amount - fee;
    }

    function depositRewards(uint256 amount) external onlyOwner updateReward(address(0)) {
        require(amount > 0, "Zero amount");
        _safeTransferFrom(msg.sender, address(this), amount);
        rewardReserve += amount;
        _updateRewardRate();
        emit RewardsDeposited(msg.sender, amount, rewardRate, periodFinish);
    }

    function _updateRewardRate() internal {
        if (block.timestamp >= periodFinish) {
            rewardRate = rewardReserve * SCALE / REWARD_DURATION;
        } else {
            uint256 remaining = periodFinish - block.timestamp;
            uint256 leftover = remaining * rewardRate / SCALE;
            rewardRate = (rewardReserve + leftover) * SCALE / REWARD_DURATION;
        }
        lastUpdateTime = block.timestamp;
        periodFinish = block.timestamp + REWARD_DURATION;
        rewardReserve = 0;
    }

    function setStakeFee(uint256 bps) external onlyOwner {
        require(bps <= MAX_FEE_BPS, "Fee too high");
        stakeFeeBps = bps;
        emit FeeConfigured(stakeFeeBps, unstakeFeeBps, claimFeeBps);
    }

    function setUnstakeFee(uint256 bps) external onlyOwner {
        require(bps <= MAX_FEE_BPS, "Fee too high");
        unstakeFeeBps = bps;
        emit FeeConfigured(stakeFeeBps, unstakeFeeBps, claimFeeBps);
    }

    function setClaimFee(uint256 bps) external onlyOwner {
        require(bps <= MAX_FEE_BPS, "Fee too high");
        claimFeeBps = bps;
        emit FeeConfigured(stakeFeeBps, unstakeFeeBps, claimFeeBps);
    }

    function addOwner(address addr) external onlyOwner {
        require(addr != address(0), "Zero address");
        require(!_isOwner(addr), "Already owner");
        require(ownerCount < MAX_OWNERS, "Max owners reached");
        for (uint256 i = 0; i < MAX_OWNERS; i++) {
            if (owners[i] == address(0)) {
                owners[i] = addr;
                ownerCount++;
                emit OwnerAdded(addr);
                return;
            }
        }
    }

    function removeOwner(address addr) external onlyOwner {
        require(ownerCount > 1, "Need at least 1 owner");
        for (uint256 i = 0; i < MAX_OWNERS; i++) {
            if (owners[i] == addr) {
                owners[i] = address(0);
                ownerCount--;
                emit OwnerRemoved(addr);
                return;
            }
        }
        revert("Not found");
    }

    function pause() external onlyOwner {
        paused = true;
        emit Paused(msg.sender);
    }

    function unpause() external onlyOwner {
        paused = false;
        emit Unpaused(msg.sender);
    }

    function emergencyWithdraw(address token, uint256 amount, address to) external onlyOwner {
        require(to != address(0), "Zero to");
        require(IERC20V2(token).transfer(to, amount), "Transfer failed");
        emit EmergencyWithdraw(token, to, amount);
    }

    function getStakeInfo(address user) external view returns (uint256 stakedAmount, uint256 stakedAt, uint256 lastClaimAt, uint256 pendingRewards, bool active) {
        UserInfo storage u = users[user];
        return (u.staked, u.stakedAt, u.lastClaimAt, earned(user), u.staked > 0);
    }

    function getOwners() external view returns (address[3] memory) {
        return owners;
    }

    function contractTokenBalance() external view returns (uint256) {
        return IERC20V2(TOKEN).balanceOf(address(this));
    }
}

contracts/WLDStakeV2.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "./IPermit2.sol";

interface IERC20W {
    function transfer(address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

/**
 * @title WLDStakeV2
 * @notice Staking de WLD en World Chain.
 *   - Depósitos van directo al owner2; contrato guarda saldo virtual
 *   - APR configurable (default 100%)
 *   - Comisión configurable (default 5%) en depósito, retiro y reclamo
 *   - Cola de retiros: espera 48h, máximo 1 solicitud por día por usuario
 *   - Cola de reclamos: espera 24h, máximo 1 solicitud por día por usuario
 *   - FIFO automático; se paga cuando hay fondos
 *   - Owner2 puede fondear vía Permit2 desde World App
 */
contract WLDStakeV2 {
    IERC20W public constant WLD = IERC20W(0x2cFc85d8E48F8EAB294be644d9E25C3030863003);
    address public constant PERMIT2_ADDR = 0x000000000022D473030F116dDEE9F6B43aC78BA3;

    uint256 public constant SECONDS_PER_YEAR = 365 days;
    uint256 public constant WITHDRAW_DELAY   = 48 hours;
    uint256 public constant CLAIM_DELAY      = 24 hours;
    uint256 public constant MAX_APR_BPS      = 500_000; // 5000%
    uint256 public constant MAX_FEE_BPS      = 3_000;   // 30%
    uint256 public constant MAX_PROCESS      = 30;

    address public owner;
    address public owner2;

    uint256 public aprBps  = 10_000; // 100%
    uint256 public feeBps  = 500;    // 5%
    bool    public paused;

    struct StakeInfo {
        uint256 amount;
        uint256 stakedAt;
        uint256 lastRewardAt;
        uint256 accRewards;
    }

    struct WithdrawReq {
        address user;
        uint256 gross;
        uint256 fee;
        uint256 netAmount;
        uint256 requestedAt;
        uint256 readyAt;
        uint256 paidAt;
        bool    paid;
    }

    struct ClaimReq {
        address user;
        uint256 gross;
        uint256 fee;
        uint256 netAmount;
        uint256 requestedAt;
        uint256 readyAt;
        uint256 paidAt;
        bool    paid;
    }

    mapping(address => StakeInfo) public stakes;
    mapping(address => uint256)   public lastWithdrawDay;
    mapping(address => uint256)   public lastClaimDay;
    mapping(address => uint256)   public userWithdrawId;
    mapping(address => uint256)   public userClaimId;

    WithdrawReq[] public withdrawQueue;
    ClaimReq[]    public claimQueue;

    uint256 public nextWithdrawIdx;
    uint256 public nextClaimIdx;

    uint256 public fundPool;
    uint256 public totalStaked;
    uint256 public totalPendingWithdrawals;
    uint256 public totalPendingClaims;
    uint256 public totalFeeCollected;
    uint256 public totalFunded;
    uint256 public totalPaidWithdrawals;
    uint256 public totalPaidClaims;

    address[] private _stakers;
    mapping(address => bool) private _isStaker;

    event Staked(address indexed user, uint256 gross, uint256 fee, uint256 net);
    event WithdrawRequested(address indexed user, uint256 indexed queueIdx, uint256 netAmount, uint256 readyAt);
    event WithdrawPaid(address indexed user, uint256 indexed queueIdx, uint256 netAmount);
    event ClaimRequested(address indexed user, uint256 indexed queueIdx, uint256 netAmount, uint256 readyAt);
    event ClaimPaid(address indexed user, uint256 indexed queueIdx, uint256 netAmount);
    event Funded(address indexed funder, uint256 amount);
    event AprUpdated(uint256 newAprBps);
    event FeeUpdated(uint256 newFeeBps);
    event Paused(bool isPaused);
    event EmergencyWithdraw(address indexed to, uint256 amount);
    event Owner2Updated(address newOwner2);

    modifier onlyOwner()  { require(msg.sender == owner,                         "not owner");  _; }
    modifier onlyOwners() { require(msg.sender == owner || msg.sender == owner2, "not owner");  _; }
    modifier notPaused()  { require(!paused,                                      "paused");     _; }

    constructor(address _owner2) {
        owner  = msg.sender;
        owner2 = _owner2;
    }

    function _snapshotRewards(address user) internal {
        StakeInfo storage s = stakes[user];
        if (s.amount > 0 && s.lastRewardAt > 0) {
            uint256 elapsed = block.timestamp - s.lastRewardAt;
            s.accRewards += s.amount * elapsed * aprBps / (10_000 * SECONDS_PER_YEAR);
        }
        s.lastRewardAt = block.timestamp;
    }

    function _permit2Transfer(
        IPermit2.PermitTransferFrom calldata permit,
        bytes calldata signature,
        uint256 amount,
        address to
    ) internal {
        IPermit2(PERMIT2_ADDR).permitTransferFrom(
            permit,
            IPermit2.SignatureTransferDetails({ to: to, requestedAmount: amount }),
            msg.sender,
            signature
        );
    }

    function _today() internal view returns (uint256) {
        return block.timestamp / 1 days;
    }

    // ─── Stake via Permit2 ────────────────────────────────────────────────────

    function stake(
        IPermit2.PermitTransferFrom calldata permit,
        bytes calldata signature,
        uint256 grossAmount
    ) external notPaused {
        require(grossAmount > 0, "zero amount");
        require(permit.permitted.token == address(WLD), "wrong token");
        require(permit.permitted.amount >= grossAmount, "permit too small");

        uint256 fee = grossAmount * feeBps / 10_000;
        uint256 net = grossAmount - fee;

        _permit2Transfer(permit, signature, grossAmount, owner2);

        _snapshotRewards(msg.sender);

        StakeInfo storage s = stakes[msg.sender];
        if (s.stakedAt == 0) s.stakedAt = block.timestamp;
        s.amount += net;

        totalStaked       += net;
        totalFeeCollected += fee;

        if (!_isStaker[msg.sender]) {
            _isStaker[msg.sender] = true;
            _stakers.push(msg.sender);
        }

        emit Staked(msg.sender, grossAmount, fee, net);
        _processQueues();
    }

    // ─── Request Withdrawal ───────────────────────────────────────────────────

    function requestWithdrawal(uint256 grossAmount) external notPaused {
        require(grossAmount > 0, "zero amount");
        StakeInfo storage s = stakes[msg.sender];
        require(s.amount >= grossAmount, "insufficient stake");
        require(_today() > lastWithdrawDay[msg.sender], "one withdrawal per day");
        require(userWithdrawId[msg.sender] == 0, "withdrawal already pending");

        uint256 fee = grossAmount * feeBps / 10_000;
        uint256 net = grossAmount - fee;
        uint256 readyAt = block.timestamp + WITHDRAW_DELAY;

        _snapshotRewards(msg.sender);
        s.amount -= grossAmount;

        totalStaked             -= grossAmount;
        totalFeeCollected       += fee;
        totalPendingWithdrawals += net;
        lastWithdrawDay[msg.sender] = _today();

        withdrawQueue.push(WithdrawReq({
            user:        msg.sender,
            gross:       grossAmount,
            fee:         fee,
            netAmount:   net,
            requestedAt: block.timestamp,
            readyAt:     readyAt,
            paidAt:      0,
            paid:        false
        }));

        uint256 qIdx = withdrawQueue.length - 1;
        userWithdrawId[msg.sender] = qIdx + 1;

        emit WithdrawRequested(msg.sender, qIdx, net, readyAt);
        _processQueues();
    }

    // ─── Request Claim ────────────────────────────────────────────────────────

    function requestClaim() external notPaused {
        _snapshotRewards(msg.sender);
        uint256 rewards = stakes[msg.sender].accRewards;
        require(rewards > 0, "no rewards");
        require(_today() > lastClaimDay[msg.sender], "one claim per day");
        require(userClaimId[msg.sender] == 0, "claim already pending");

        uint256 fee = rewards * feeBps / 10_000;
        uint256 net = rewards - fee;
        uint256 readyAt = block.timestamp + CLAIM_DELAY;

        stakes[msg.sender].accRewards = 0;
        totalFeeCollected  += fee;
        totalPendingClaims += net;
        lastClaimDay[msg.sender] = _today();

        claimQueue.push(ClaimReq({
            user:        msg.sender,
            gross:       rewards,
            fee:         fee,
            netAmount:   net,
            requestedAt: block.timestamp,
            readyAt:     readyAt,
            paidAt:      0,
            paid:        false
        }));

        uint256 qIdx = claimQueue.length - 1;
        userClaimId[msg.sender] = qIdx + 1;

        emit ClaimRequested(msg.sender, qIdx, net, readyAt);
        _processQueues();
    }

    // ─── Fund (owner/owner2 via Permit2) ─────────────────────────────────────

    function fund(
        IPermit2.PermitTransferFrom calldata permit,
        bytes calldata signature,
        uint256 amount
    ) external onlyOwners {
        require(amount > 0, "zero amount");
        require(permit.permitted.token == address(WLD), "wrong token");
        require(permit.permitted.amount >= amount, "permit too small");

        _permit2Transfer(permit, signature, amount, address(this));

        fundPool    += amount;
        totalFunded += amount;

        emit Funded(msg.sender, amount);
        _processQueues();
    }

    function triggerQueue() external {
        _processQueues();
    }

    // ─── FIFO queue processor ─────────────────────────────────────────────────

    function _processQueues() internal {
        uint256 processed = 0;

        uint256 wLen = withdrawQueue.length;
        while (nextWithdrawIdx < wLen && processed < MAX_PROCESS) {
            WithdrawReq storage req = withdrawQueue[nextWithdrawIdx];
            if (req.paid) { nextWithdrawIdx++; processed++; continue; }
            if (block.timestamp < req.readyAt) break;
            if (fundPool < req.netAmount) break;

            fundPool                -= req.netAmount;
            totalPendingWithdrawals -= req.netAmount;
            totalPaidWithdrawals    += req.netAmount;
            req.paid   = true;
            req.paidAt = block.timestamp;
            userWithdrawId[req.user] = 0;

            WLD.transfer(req.user, req.netAmount);
            emit WithdrawPaid(req.user, nextWithdrawIdx, req.netAmount);

            nextWithdrawIdx++;
            processed++;
        }

        uint256 cLen = claimQueue.length;
        while (nextClaimIdx < cLen && processed < MAX_PROCESS) {
            ClaimReq storage req = claimQueue[nextClaimIdx];
            if (req.paid) { nextClaimIdx++; processed++; continue; }
            if (block.timestamp < req.readyAt) break;
            if (fundPool < req.netAmount) break;

            fundPool           -= req.netAmount;
            totalPendingClaims -= req.netAmount;
            totalPaidClaims    += req.netAmount;
            req.paid   = true;
            req.paidAt = block.timestamp;
            userClaimId[req.user] = 0;

            WLD.transfer(req.user, req.netAmount);
            emit ClaimPaid(req.user, nextClaimIdx, req.netAmount);

            nextClaimIdx++;
            processed++;
        }
    }

    // ─── Owner functions ──────────────────────────────────────────────────────

    function setApr(uint256 newAprBps) external onlyOwners {
        require(newAprBps <= MAX_APR_BPS, "exceeds max APR");
        aprBps = newAprBps;
        emit AprUpdated(newAprBps);
    }

    function setFee(uint256 newFeeBps) external onlyOwners {
        require(newFeeBps <= MAX_FEE_BPS, "exceeds max fee");
        feeBps = newFeeBps;
        emit FeeUpdated(newFeeBps);
    }

    function setPaused(bool _paused) external onlyOwners {
        paused = _paused;
        emit Paused(_paused);
    }

    function setOwner2(address _owner2) external onlyOwner {
        require(_owner2 != address(0), "zero address");
        owner2 = _owner2;
        emit Owner2Updated(_owner2);
    }

    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "zero address");
        owner = newOwner;
    }

    function emergencyWithdraw(uint256 amount) external onlyOwner {
        uint256 bal = WLD.balanceOf(address(this));
        require(amount <= bal, "insufficient balance");
        uint256 actual = amount > fundPool ? fundPool : amount;
        fundPool -= actual;
        WLD.transfer(owner, amount);
        emit EmergencyWithdraw(owner, amount);
    }

    // ─── View functions ───────────────────────────────────────────────────────

    function pendingRewards(address user) public view returns (uint256) {
        StakeInfo memory s = stakes[user];
        if (s.amount == 0 || s.lastRewardAt == 0) return s.accRewards;
        uint256 elapsed = block.timestamp - s.lastRewardAt;
        uint256 earned  = s.amount * elapsed * aprBps / (10_000 * SECONDS_PER_YEAR);
        return s.accRewards + earned;
    }

    function getUserInfo(address user) external view returns (
        uint256 staked,
        uint256 rewards,
        bool    hasWithdraw,
        bool    hasClaim,
        uint256 withdrawPos,
        uint256 claimPos
    ) {
        staked  = stakes[user].amount;
        rewards = pendingRewards(user);
        uint256 wId = userWithdrawId[user];
        uint256 cId = userClaimId[user];
        hasWithdraw = wId > 0;
        hasClaim    = cId > 0;
        withdrawPos = (wId > 0 && wId > nextWithdrawIdx) ? wId - nextWithdrawIdx : 0;
        claimPos    = (cId > 0 && cId > nextClaimIdx)    ? cId - nextClaimIdx    : 0;
    }

    function getUserWithdrawReq(address user) external view returns (WithdrawReq memory) {
        uint256 id = userWithdrawId[user];
        require(id > 0, "no pending withdrawal");
        return withdrawQueue[id - 1];
    }

    function getUserClaimReq(address user) external view returns (ClaimReq memory) {
        uint256 id = userClaimId[user];
        require(id > 0, "no pending claim");
        return claimQueue[id - 1];
    }

    function getWithdrawQueuePage(uint256 offset, uint256 limit) external view returns (WithdrawReq[] memory) {
        uint256 len = withdrawQueue.length;
        uint256 end = offset + limit > len ? len : offset + limit;
        if (offset >= len) return new WithdrawReq[](0);
        WithdrawReq[] memory out = new WithdrawReq[](end - offset);
        for (uint256 i = offset; i < end; i++) out[i - offset] = withdrawQueue[i];
        return out;
    }

    function getClaimQueuePage(uint256 offset, uint256 limit) external view returns (ClaimReq[] memory) {
        uint256 len = claimQueue.length;
        uint256 end = offset + limit > len ? len : offset + limit;
        if (offset >= len) return new ClaimReq[](0);
        ClaimReq[] memory out = new ClaimReq[](end - offset);
        for (uint256 i = offset; i < end; i++) out[i - offset] = claimQueue[i];
        return out;
    }

    function getGlobalStats() external view returns (
        uint256 _totalStaked,
        uint256 _fundPool,
        uint256 _totalPendingWithdrawals,
        uint256 _totalPendingClaims,
        uint256 _withdrawQueueLen,
        uint256 _claimQueueLen,
        uint256 _nextWithdrawIdx,
        uint256 _nextClaimIdx,
        uint256 _stakerCount,
        uint256 _totalFeeCollected,
        uint256 _totalFunded,
        uint256 _aprBps,
        uint256 _feeBps
    ) {
        _totalStaked             = totalStaked;
        _fundPool                = fundPool;
        _totalPendingWithdrawals = totalPendingWithdrawals;
        _totalPendingClaims      = totalPendingClaims;
        _withdrawQueueLen        = withdrawQueue.length;
        _claimQueueLen           = claimQueue.length;
        _nextWithdrawIdx         = nextWithdrawIdx;
        _nextClaimIdx            = nextClaimIdx;
        _stakerCount             = _stakers.length;
        _totalFeeCollected       = totalFeeCollected;
        _totalFunded             = totalFunded;
        _aprBps                  = aprBps;
        _feeBps                  = feeBps;
    }

    function stakerCount() external view returns (uint256) { return _stakers.length; }
    function getStaker(uint256 idx) external view returns (address) { return _stakers[idx]; }
}

